  "description": "A branded chatbot application for Lifewood, a leader in AI data solutions, featuring their signature color palette and 'Always On Never Off' philosophy."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React from 'react';

export const COLORS = {
  paper: '#f5eedb',
  darkSerpent: '#133020',
  castletonGreen: '#046241',
  saffron: '#FFB347',
  earthYellow: '#FFC370',
  seaSalt: '#F9F7F7',
  white: '#ffffff',
};

export const LifewoodLogo: React.FC<{ className?: string }> = ({ className = "h-8" }) => (
  <div className={`flex items-center gap-2 ${className}`}>
    <svg viewBox="0 0 100 120" className="h-full fill-[#FFB347]">
      <path d="M50 0 L90 30 L90 90 L50 120 L10 90 L10 30 Z" />
    </svg>
    <span className="text-[#046241] font-bold text-2xl tracking-tighter">lifewood</span>
  </div>
);

export const SYSTEM_INSTRUCTION = `
You are the Lifewood AI Assistant. Your tone is Adaptable, Innovative, Technological, and Proactive.
Lifewood is a global champion in AI data solutions, serving as a super-bridge between East and West (specifically ASEAN and China).
Our vision is to ignite innovation and sustainability that enriches lives.
Our philosophy is "Always On Never Off".
Always be concise, professional, and helpful. If asked about the company, emphasize our commitment to ESG and our role as a builder of harmony and trust.
`;

export enum SenderType {
  USER = 'user',
  AI = 'ai'
}

export interface Message {
  id: string;
  text: string;
  sender: SenderType;
  timestamp: Date;
}

import { GoogleGenAI } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getGeminiResponse = async (userMessage: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  try {
    const chat = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
      },
    });

    // Note: We're using chat.sendMessage to maintain context if we wanted to pass history,
    // but for this simple version, we can also just use a single message call.
    const response = await chat.sendMessage({ message: userMessage });
    return response.text;
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "I apologize, but I encountered a technological glitch. Our team is proactive and working to resolve it. Please try again later.";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { LifewoodLogo, COLORS } from './constants';
import { Message, SenderType } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      text: "Hello! I'm the Lifewood Assistant. How can I help you bridge your innovation needs today?",
      sender: SenderType.AI,
      timestamp: new Date(),
    },
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      text: input,
      sender: SenderType.USER,
      timestamp: new Date(),
    };

    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    // Mocking history for simple context
    const aiResponseText = await getGeminiResponse(input, []);

    const aiMessage: Message = {
      id: (Date.now() + 1).toString(),
      text: aiResponseText || "I'm sorry, I couldn't generate a response.",
      sender: SenderType.AI,
      timestamp: new Date(),
    };

    setMessages(prev => [...prev, aiMessage]);
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex flex-col h-screen max-h-screen overflow-hidden bg-[#f5eedb]">
      {/* Header */}
      <header className="bg-[#133020] px-6 py-4 flex items-center justify-between shadow-md">
        <LifewoodLogo className="h-10" />
        <div className="hidden md:flex items-center gap-6">
          <span className="text-white text-sm font-medium opacity-80 uppercase tracking-widest">Always On Never Off</span>
          <div className="h-6 w-[1px] bg-white opacity-20"></div>
          <span className="text-white text-sm font-semibold">AI Solutions Hub</span>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col md:flex-row max-w-7xl mx-auto w-full p-4 md:p-6 gap-6 overflow-hidden">

        {/* Left Sidebar - Desktop only */}
        <aside className="hidden lg:flex flex-col w-72 space-y-4">
          <div className="bg-white rounded-xl p-6 shadow-sm border border-[#FFC370]/30">
            <h2 className="text-[#046241] font-bold text-xl mb-3">Our Core Belief</h2>
            <p className="text-sm leading-relaxed opacity-80">
              To be the global champion in AI data solutions, igniting a culture of innovation and sustainability.
            </p>
          </div>
          <div className="bg-[#046241] rounded-xl p-6 shadow-sm text-white">
            <h3 className="font-semibold text-lg mb-2">Technological Bridging</h3>
            <p className="text-xs opacity-80">
              We act as a builder of harmony, trust, and cooperation across borders.
            </p>
          </div>
          <div className="bg-[#FFB347] rounded-xl p-6 shadow-sm text-[#133020]">
            <h3 className="font-bold text-lg mb-1 italic uppercase tracking-tighter">Proactive</h3>
            <p className="text-xs font-medium">
              Innovation at the speed of thought.
            </p>
          </div>
        </aside>

        {/* Chat Window */}
        <section className="flex-1 flex flex-col bg-white rounded-2xl shadow-xl border border-[#046241]/10 overflow-hidden relative">

          {/* Messages Container */}
          <div className="flex-1 overflow-y-auto p-4 md:p-6 lifewood-scrollbar space-y-6">
            {messages.map((msg) => (
              <div 
                key={msg.id} 
                className={`flex ${msg.sender === SenderType.USER ? 'justify-end' : 'justify-start'}`}
              >
                <div className={`max-w-[85%] md:max-w-[70%] flex flex-col ${msg.sender === SenderType.USER ? 'items-end' : 'items-start'}`}>
                  <div 
                    className={`px-5 py-3 rounded-2xl text-sm leading-relaxed shadow-sm ${
                      msg.sender === SenderType.USER 
                        ? 'bg-[#FFB347] text-[#133020] rounded-tr-none' 
                        : 'bg-[#046241] text-white rounded-tl-none'
                    }`}
                  >
                    {msg.text}
                  </div>
                  <span className="text-[10px] text-[#133020]/40 mt-1 font-medium">
                    {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-[#046241]/10 px-5 py-3 rounded-2xl rounded-tl-none flex items-center gap-2">
                  <div className="w-2 h-2 bg-[#046241] rounded-full animate-bounce"></div>
                  <div className="w-2 h-2 bg-[#046241] rounded-full animate-bounce [animation-delay:0.2s]"></div>
                  <div className="w-2 h-2 bg-[#046241] rounded-full animate-bounce [animation-delay:0.4s]"></div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <div className="p-4 bg-[#F9F7F7] border-t border-[#046241]/10">
            <div className="relative flex items-center">
              <textarea
                rows={1}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={handleKeyPress}
                placeholder="Ask Lifewood AI anything..."
                className="w-full bg-white border border-[#046241]/20 rounded-xl px-4 py-3 pr-16 focus:outline-none focus:ring-2 focus:ring-[#FFB347] resize-none text-sm lifewood-scrollbar"
              />
              <button
                onClick={handleSend}
                disabled={isLoading || !input.trim()}
                className={`absolute right-2 p-2 rounded-lg transition-all duration-200 ${
                  isLoading || !input.trim() 
                    ? 'bg-gray-200 text-gray-400 cursor-not-allowed' 
                    : 'bg-[#FFB347] text-[#133020] hover:bg-[#FFC370] active:scale-95 shadow-md'
                }`}
              >
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M6 12L3.269 3.126A59.768 59.768 0 0121.485 12 59.77 59.77 0 013.27 20.876L5.999 12zm0 0h7.5" />
                </svg>
              </button>
            </div>
            <p className="text-[10px] text-center text-[#133020]/50 mt-2 font-medium">
              Lifewood AI can produce inaccurate results. Always verify important information.
            </p>
          </div>
        </section>
      </main>

      {/* Footer Branding */}
      <footer className="bg-[#f5eedb] py-2 px-6 flex justify-between items-center text-[11px] font-bold text-[#133020]/60 border-t border-[#046241]/5">
        <span>© 2024 LIFEWOOD TECHNOLOGY</span>
        <div className="flex gap-4">
          <span className="hover:text-[#046241] cursor-pointer">PRIVACY POLICY</span>
          <span className="hover:text-[#046241] cursor-pointer">TERMS OF SERVICE</span>
        </div>
      </footer>
    </div>
  );
};

export default App;

{
  "name": "Lifewood AI Chat Pro",
  "description": "An advanced branded chatbot for Lifewood with multi-conversation support, persona switching, and file uploads.",
  "requestFramePermissions": [
    "camera"
  ]
}

export enum SenderType {
  USER = 'user',
  AI = 'ai'
}

export interface FileData {
  data: string;
  mimeType: string;
  fileName: string;
}

export interface Message {
  id: string;
  text: string;
  sender: SenderType;
  timestamp: Date;
  attachments?: FileData[];
}

export interface Persona {
  id: string;
  name: string;
  role: string;
  description: string;
  instruction: string;
  avatarColor: string;
}

export interface Conversation {
  id: string;
  title: string;
  messages: Message[];
  personaId: string;
  createdAt: Date;
}

import React from 'react';
import { Persona } from './types';

export const COLORS = {
  paper: '#f5eedb',
  darkSerpent: '#133020',
  castletonGreen: '#046241',
  saffron: '#FFB347',
  earthYellow: '#FFC370',
  seaSalt: '#F9F7F7',
  white: '#ffffff',
};

export const PERSONAS: Persona[] = [
  {
    id: 'specialist',
    name: 'Data Specialist',
    role: 'Technical Expert',
    description: 'Focused on AI pipelines, data quality, and technical implementation.',
    avatarColor: '#046241',
    instruction: "You are the Lifewood Data Specialist. You are technical, precise, and focused on high-quality AI data solutions. You explain things like data labeling, RLHF, and dataset curation with deep expertise. Your tone is professional and detail-oriented."
  },
  {
    id: 'strategist',
    name: 'Strategic Partner',
    role: 'Business Consultant',
    description: 'Focused on growth, ESG, and bridging East-West markets.',
    avatarColor: '#FFB347',
    instruction: "You are the Lifewood Strategic Partner. You focus on the big picture: how AI empowers businesses, ESG sustainability, and Lifewood's role as a bridge between ASEAN and China. Your tone is visionary, proactive, and collaborative."
  },
  {
    id: 'concierge',
    name: 'Support Concierge',
    role: 'Help Desk',
    description: 'Friendly, helpful assistant for general inquiries.',
    avatarColor: '#133020',
    instruction: "You are the Lifewood Support Concierge. Your goal is to be exceptionally friendly and helpful. You guide users through Lifewood's services and answer general questions quickly and concisely. Your tone is warm and welcoming."
  }
];

export const LifewoodLogo: React.FC<{ className?: string }> = ({ className = "h-8" }) => (
  <div className={`flex items-center gap-2 ${className}`}>
    <svg viewBox="0 0 100 120" className="h-full fill-[#FFB347]">
      <path d="M50 0 L90 30 L90 90 L50 120 L10 90 L10 30 Z" />
    </svg>
    <span className="text-white font-bold text-2xl tracking-tighter">lifewood</span>
  </div>
);

import { GoogleGenAI } from "@google/genai";
import { FileData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getGeminiResponse = async (
  userMessage: string, 
  personaInstruction: string,
  attachments: FileData[] = []
) => {
  try {
    const parts: any[] = [{ text: userMessage }];

    // Handle attachments
    attachments.forEach(file => {
      // Remove data:image/png;base64, prefix
      const base64Data = file.data.split(',')[1] || file.data;
      parts.push({
        inlineData: {
          data: base64Data,
          mimeType: file.mimeType
        }
      });
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ parts }],
      config: {
        systemInstruction: personaInstruction,
      },
    });

    return response.text;
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "I apologize, but I encountered a technological glitch. Our team is proactive and working to resolve it. Please try again later.";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { LifewoodLogo, COLORS, PERSONAS } from './constants';
import { Message, SenderType, Conversation, Persona, FileData } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  const [conversations, setConversations] = useState<Conversation[]>(() => {
    const saved = localStorage.getItem('lifewood_conversations');
    return saved ? JSON.parse(saved).map((c: any) => ({
      ...c,
      messages: c.messages.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
      createdAt: new Date(c.createdAt)
    })) : [];
  });

  const [activeId, setActiveId] = useState<string | null>(null);
  const [activePersona, setActivePersona] = useState<Persona>(PERSONAS[0]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [attachments, setAttachments] = useState<FileData[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const currentConversation = conversations.find(c => c.id === activeId);

  useEffect(() => {
    localStorage.setItem('lifewood_conversations', JSON.stringify(conversations));
  }, [conversations]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [currentConversation?.messages, isLoading]);

  const startNewChat = (persona: Persona = activePersona) => {
    const newId = Date.now().toString();
    const newConv: Conversation = {
      id: newId,
      title: 'New Conversation',
      messages: [],
      personaId: persona.id,
      createdAt: new Date(),
    };
    setConversations(prev => [newConv, ...prev]);
    setActiveId(newId);
    setActivePersona(persona);
    setIsSidebarOpen(false); // On mobile
  };

  const deleteConversation = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setConversations(prev => prev.filter(c => c.id !== id));
    if (activeId === id) setActiveId(null);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    Array.from(files).forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const base64 = event.target?.result as string;
        setAttachments(prev => [...prev, {
          data: base64,
          mimeType: file.type,
          fileName: file.name
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleSend = async () => {
    if ((!input.trim() && attachments.length === 0) || isLoading) return;

    let targetConv = currentConversation;
    if (!targetConv) {
      const newId = Date.now().toString();
      targetConv = {
        id: newId,
        title: input.slice(0, 30) || 'New Conversation',
        messages: [],
        personaId: activePersona.id,
        createdAt: new Date(),
      };
      setConversations(prev => [targetConv!, ...prev]);
      setActiveId(newId);
    }

    const userMessage: Message = {
      id: Date.now().toString(),
      text: input,
      sender: SenderType.USER,
      timestamp: new Date(),
      attachments: [...attachments],
    };

    const updatedConv = {
      ...targetConv,
      title: targetConv.messages.length === 0 ? (input.slice(0, 30) || 'New Conversation') : targetConv.title,
      messages: [...targetConv.messages, userMessage]
    };

    setConversations(prev => prev.map(c => c.id === updatedConv.id ? updatedConv : c));
    setInput('');
    setAttachments([]);
    setIsLoading(true);

    const aiResponseText = await getGeminiResponse(
      userMessage.text, 
      activePersona.instruction,
      userMessage.attachments
    );

    const aiMessage: Message = {
      id: (Date.now() + 1).toString(),
      text: aiResponseText || "I encountered an error processing your request.",
      sender: SenderType.AI,
      timestamp: new Date(),
    };

    setConversations(prev => prev.map(c => 
      c.id === updatedConv.id ? { ...c, messages: [...c.messages, aiMessage] } : c
    ));
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex h-screen bg-[#f5eedb] text-[#133020] overflow-hidden">

      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-80 bg-[#133020] transition-transform duration-300 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 flex flex-col shadow-2xl`}>
        <div className="p-6 border-b border-white/10">
          <LifewoodLogo />
          <button 
            onClick={() => startNewChat()}
            className="w-full mt-6 bg-[#046241] hover:bg-[#057a51] text-white py-3 rounded-xl flex items-center justify-center gap-2 font-bold transition-all shadow-lg active:scale-95"
          >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5">
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
            </svg>
            NEW CHAT
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-2 lifewood-scrollbar">
          <h3 className="text-white/40 text-[10px] font-bold uppercase tracking-widest px-2 mb-2">Recent History</h3>
          {conversations.length === 0 ? (
            <div className="text-white/30 text-xs px-2 italic">No conversations yet...</div>
          ) : (
            conversations.map(conv => (
              <div 
                key={conv.id}
                onClick={() => {
                  setActiveId(conv.id);
                  const p = PERSONAS.find(p => p.id === conv.personaId);
                  if (p) setActivePersona(p);
                }}
                className={`group relative p-3 rounded-xl cursor-pointer transition-all flex items-center justify-between ${activeId === conv.id ? 'bg-[#046241] text-white' : 'hover:bg-white/5 text-white/70 hover:text-white'}`}
              >
                <div className="flex-1 min-w-0 pr-6">
                  <div className="text-sm font-semibold truncate">{conv.title}</div>
                  <div className="text-[10px] opacity-50">{conv.createdAt.toLocaleDateString()}</div>
                </div>
                <button 
                  onClick={(e) => deleteConversation(e, conv.id)}
                  className="opacity-0 group-hover:opacity-100 p-1.5 hover:bg-red-500/20 rounded-md transition-all text-red-400"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-4 h-4">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M14.74 9l-.346 9m-4.788 0L9.26 9m9.968-3.21c.342.052.682.107 1.022.166m-1.022-.165L18.16 19.673a2.25 2.25 0 01-2.244 2.077H8.084a2.25 2.25 0 01-2.244-2.077L4.772 5.79m14.456 0a48.108 48.108 0 00-3.478-.397m-12 .562c.34-.059.68-.114 1.022-.165m0 0a48.11 48.11 0 013.478-.397m7.5 0v-.916c0-1.18-.91-2.164-2.09-2.201a51.964 51.964 0 00-3.32 0c-1.18.037-2.09 1.022-2.09 2.201v.916m7.5 0a48.667 48.667 0 00-7.5 0" />
                  </svg>
                </button>
              </div>
            ))
          )}
        </div>

        <div className="p-4 bg-black/20 space-y-4">
          <div className="space-y-2">
            <label className="text-white/40 text-[10px] font-bold uppercase tracking-widest px-2">Active Persona</label>
            <div className="grid grid-cols-1 gap-2">
              {PERSONAS.map(p => (
                <button
                  key={p.id}
                  onClick={() => setActivePersona(p)}
                  className={`flex items-center gap-3 p-2 rounded-lg text-xs text-left transition-all ${activePersona.id === p.id ? 'bg-[#FFB347] text-[#133020]' : 'hover:bg-white/5 text-white/70'}`}
                >
                  <div className="w-6 h-6 rounded-full flex-shrink-0" style={{ backgroundColor: p.avatarColor }}></div>
                  <div>
                    <div className="font-bold">{p.name}</div>
                    <div className="text-[9px] opacity-70 leading-none mt-0.5">{p.role}</div>
                  </div>
                </button>
              ))}
            </div>
          </div>
          <div className="pt-2 border-t border-white/10 flex items-center justify-between text-[10px] text-white/40 font-bold uppercase tracking-tighter">
            <span>Always On Never Off</span>
            <div className="w-2 h-2 rounded-full bg-green-400 animate-pulse"></div>
          </div>
        </div>
      </aside>

      {/* Main Chat Area */}
      <main className="flex-1 flex flex-col relative overflow-hidden">

        {/* Top bar */}
        <header className="bg-white/50 backdrop-blur-md px-6 py-4 flex items-center justify-between border-b border-[#046241]/10">
          <div className="flex items-center gap-3">
            <button lg-hidden="true" onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="lg:hidden p-2 text-[#046241]">
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6">
                <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25h16.5" />
              </svg>
            </button>
            <div>
              <h1 className="text-lg font-bold text-[#133020] leading-none">
                {currentConversation?.title || 'Lifewood AI Chat'}
              </h1>
              <div className="flex items-center gap-2 mt-1">
                <span className="text-[10px] font-bold text-[#046241] bg-[#046241]/10 px-1.5 py-0.5 rounded uppercase">
                  {activePersona.name}
                </span>
                <span className="text-[10px] text-[#133020]/40 font-medium italic">{activePersona.description}</span>
              </div>
            </div>
          </div>
        </header>

        {/* Message Container */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8 lifewood-scrollbar">
          {(!currentConversation || currentConversation.messages.length === 0) && (
            <div className="h-full flex flex-col items-center justify-center text-center max-w-md mx-auto space-y-6">
              <div className="w-20 h-20 bg-white rounded-3xl shadow-xl flex items-center justify-center border border-[#046241]/10">
                <div className="w-10 h-10 rounded-full" style={{ backgroundColor: activePersona.avatarColor }}></div>
              </div>
              <div>
                <h2 className="text-2xl font-bold text-[#046241]">How can {activePersona.name} help?</h2>
                <p className="mt-2 text-sm text-[#133020]/60 leading-relaxed">
                  Start a conversation about AI data solutions, ESG, or our innovative pipelines. You can also upload files or images for analysis.
                </p>
              </div>
            </div>
          )}

          {currentConversation?.messages.map((msg) => (
            <div key={msg.id} className={`flex ${msg.sender === SenderType.USER ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
              <div className={`flex gap-3 max-w-[85%] md:max-w-[70%] ${msg.sender === SenderType.USER ? 'flex-row-reverse' : ''}`}>
                <div className={`flex-shrink-0 w-8 h-8 rounded-lg flex items-center justify-center shadow-sm ${msg.sender === SenderType.USER ? 'bg-[#FFB347]' : ''}`} style={{ backgroundColor: msg.sender === SenderType.AI ? activePersona.avatarColor : undefined }}>
                  {msg.sender === SenderType.AI ? (
                    <div className="w-4 h-4 bg-white/20 rounded-full"></div>
                  ) : (
                    <span className="text-[10px] font-bold text-[#133020]">YOU</span>
                  )}
                </div>
                <div className={`space-y-2 ${msg.sender === SenderType.USER ? 'items-end' : 'items-start'} flex flex-col`}>
                  <div className={`px-5 py-3 rounded-2xl text-sm leading-relaxed shadow-sm ${msg.sender === SenderType.USER ? 'bg-[#FFB347] text-[#133020] rounded-tr-none' : 'bg-white text-[#133020] rounded-tl-none border border-[#046241]/5'}`}>
                    {msg.text}
                    {msg.attachments && msg.attachments.length > 0 && (
                      <div className="mt-3 grid grid-cols-1 gap-2">
                        {msg.attachments.map((file, idx) => (
                          <div key={idx} className="rounded-lg overflow-hidden border border-[#133020]/10 max-h-48">
                            {file.mimeType.startsWith('image/') ? (
                              <img src={file.data} alt="Attachment" className="w-full h-full object-cover" />
                            ) : (
                              <div className="p-3 bg-black/5 flex items-center gap-2 text-xs font-medium">
                                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5">
                                  <path strokeLinecap="round" strokeLinejoin="round" d="M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m.75 12l3 3m0 0l3-3m-3 3v-6m-1.5-9H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z" />
                                </svg>
                                {file.fileName}
                              </div>
                            )}
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                  <span className="text-[9px] text-[#133020]/30 font-bold uppercase">
                    {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              </div>
            </div>
          ))}

          {isLoading && (
            <div className="flex justify-start">
               <div className="flex gap-3">
                <div className="flex-shrink-0 w-8 h-8 rounded-lg flex items-center justify-center" style={{ backgroundColor: activePersona.avatarColor }}>
                  <div className="w-4 h-4 bg-white/20 rounded-full animate-pulse"></div>
                </div>
                <div className="bg-white/40 px-5 py-4 rounded-2xl rounded-tl-none flex items-center gap-1.5 border border-[#046241]/5">
                  <div className="w-1.5 h-1.5 bg-[#046241] rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                  <div className="w-1.5 h-1.5 bg-[#046241] rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                  <div className="w-1.5 h-1.5 bg-[#046241] rounded-full animate-bounce"></div>
                </div>
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input Bar */}
        <div className="p-4 md:p-6 bg-[#f5eedb]">
          <div className="max-w-4xl mx-auto space-y-3">

            {attachments.length > 0 && (
              <div className="flex flex-wrap gap-2 animate-in slide-in-from-bottom-4 duration-300">
                {attachments.map((file, idx) => (
                  <div key={idx} className="relative group rounded-lg overflow-hidden border-2 border-[#FFB347] w-16 h-16 shadow-md">
                    {file.mimeType.startsWith('image/') ? (
                      <img src={file.data} className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full bg-[#133020] flex items-center justify-center text-white">
                         <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                           <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                         </svg>
                      </div>
                    )}
                    <button 
                      onClick={() => setAttachments(prev => prev.filter((_, i) => i !== idx))}
                      className="absolute top-0 right-0 bg-red-500 text-white p-0.5 rounded-bl-lg opacity-0 group-hover:opacity-100 transition-all"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
                      </svg>
                    </button>
                  </div>
                ))}
              </div>
            )}

            <div className="relative flex items-end gap-3 bg-white p-2 md:p-3 rounded-2xl shadow-xl border border-[#046241]/10 focus-within:ring-2 focus-within:ring-[#FFB347] transition-all">
              <input 
                type="file" 
                multiple 
                className="hidden" 
                ref={fileInputRef} 
                onChange={handleFileUpload}
                accept="image/*,application/pdf,text/plain"
              />
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="p-3 text-[#133020]/40 hover:text-[#046241] hover:bg-[#046241]/5 rounded-xl transition-all"
              >
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M18.375 12.739l-7.693 7.693a4.5 4.5 0 01-6.364-6.364l10.94-10.94A3 3 0 1119.5 7.372L8.552 18.32a1.5 1.5 0 01-2.121-2.121L16.715 5.86" />
                </svg>
              </button>

              <textarea
                rows={1}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={handleKeyPress}
                placeholder="Message Lifewood AI..."
                className="flex-1 bg-transparent border-none focus:outline-none focus:ring-0 resize-none py-3 text-sm max-h-40 lifewood-scrollbar"
              />

              <button
                onClick={handleSend}
                disabled={isLoading || (!input.trim() && attachments.length === 0)}
                className={`p-3 rounded-xl transition-all shadow-lg active:scale-95 ${
                  isLoading || (!input.trim() && attachments.length === 0)
                    ? 'bg-gray-100 text-gray-300'
                    : 'bg-[#FFB347] text-[#133020] hover:bg-[#FFC370]'
                }`}
              >
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-6 h-6">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M6 12L3.269 3.126A59.768 59.768 0 0121.485 12 59.77 59.77 0 013.27 20.876L5.999 12zm0 0h7.5" />
                </svg>
              </button>
            </div>
            <div className="flex justify-between items-center px-2">
               <p className="text-[9px] text-[#133020]/40 font-bold uppercase tracking-widest">
                Always On Never Off
              </p>
              <p className="text-[9px] text-[#133020]/40 font-medium">
                Verify important facts. Powered by Gemini 3.
              </p>
            </div>
          </div>
        </div>
      </main>

      {/* Mobile Sidebar Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 backdrop-blur-sm z-40 lg:hidden"
          onClick={() => setIsSidebarOpen(false)}
        ></div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { LifewoodLogo, COLORS, PERSONAS } from './constants';
import { Message, SenderType, Conversation, Persona, FileData } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  const [conversations, setConversations] = useState<Conversation[]>(() => {
    const saved = localStorage.getItem('lifewood_conversations');
    return saved ? JSON.parse(saved).map((c: any) => ({
      ...c,
      messages: c.messages.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
      createdAt: new Date(c.createdAt)
    })) : [];
  });

  const [activeId, setActiveId] = useState<string | null>(null);
  const [activePersona, setActivePersona] = useState<Persona>(PERSONAS[0]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [attachments, setAttachments] = useState<FileData[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const currentConversation = conversations.find(c => c.id === activeId);

  useEffect(() => {
    localStorage.setItem('lifewood_conversations', JSON.stringify(conversations));
  }, [conversations]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [currentConversation?.messages, isLoading]);

  const startNewChat = (persona: Persona = activePersona) => {
    const newId = Date.now().toString();
    const newConv: Conversation = {
      id: newId,
      title: 'New Conversation',
      messages: [],
      personaId: persona.id,
      createdAt: new Date(),
    };
    setConversations(prev => [newConv, ...prev]);
    setActiveId(newId);
    setActivePersona(persona);
    setIsSidebarOpen(false);
  };

  const deleteConversation = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setConversations(prev => prev.filter(c => c.id !== id));
    if (activeId === id) setActiveId(null);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    Array.from(files).forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const base64 = event.target?.result as string;
        setAttachments(prev => [...prev, {
          data: base64,
          mimeType: file.type,
          fileName: file.name
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleSend = async () => {
    if ((!input.trim() && attachments.length === 0) || isLoading) return;

    let targetConv = currentConversation;
    if (!targetConv) {
      const newId = Date.now().toString();
      targetConv = {
        id: newId,
        title: input.slice(0, 30) || 'New Conversation',
        messages: [],
        personaId: activePersona.id,
        createdAt: new Date(),
      };
      setConversations(prev => [targetConv!, ...prev]);
      setActiveId(newId);
    }

    const userMessage: Message = {
      id: Date.now().toString(),
      text: input,
      sender: SenderType.USER,
      timestamp: new Date(),
      attachments: [...attachments],
    };

    const updatedConv = {
      ...targetConv,
      title: targetConv.messages.length === 0 ? (input.slice(0, 30) || 'New Conversation') : targetConv.title,
      messages: [...targetConv.messages, userMessage]
    };

    setConversations(prev => prev.map(c => c.id === updatedConv.id ? updatedConv : c));
    setInput('');
    setAttachments([]);
    setIsLoading(true);

    const aiResponseText = await getGeminiResponse(
      userMessage.text, 
      activePersona.instruction,
      userMessage.attachments
    );

    const aiMessage: Message = {
      id: (Date.now() + 1).toString(),
      text: aiResponseText || "I encountered an error processing your request.",
      sender: SenderType.AI,
      timestamp: new Date(),
    };

    setConversations(prev => prev.map(c => 
      c.id === updatedConv.id ? { ...c, messages: [...c.messages, aiMessage] } : c
    ));
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex h-screen bg-[#f5eedb] text-[#133020] overflow-hidden">

      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-72 bg-[#133020] transition-transform duration-300 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 flex flex-col shadow-2xl`}>
        <div className="p-6 border-b border-white/10">
          <LifewoodLogo />
          <button 
            onClick={() => startNewChat()}
            className="w-full mt-6 bg-[#046241] hover:bg-[#057a51] text-white py-3 rounded-xl flex items-center justify-center gap-2 font-bold transition-all shadow-lg active:scale-95"
          >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5">
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
            </svg>
            NEW CHAT
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-2 lifewood-scrollbar">
          <h3 className="text-white/40 text-[10px] font-bold uppercase tracking-widest px-2 mb-2">History</h3>
          {conversations.length === 0 ? (
            <div className="text-white/30 text-xs px-2 italic mt-4">No recent activity</div>
          ) : (
            conversations.map(conv => (
              <div 
                key={conv.id}
                onClick={() => {
                  setActiveId(conv.id);
                  const p = PERSONAS.find(p => p.id === conv.personaId);
                  if (p) setActivePersona(p);
                  setIsSidebarOpen(false);
                }}
                className={`group relative p-3 rounded-xl cursor-pointer transition-all flex items-center justify-between ${activeId === conv.id ? 'bg-[#046241] text-white shadow-inner' : 'hover:bg-white/5 text-white/70 hover:text-white'}`}
              >
                <div className="flex-1 min-w-0 pr-2">
                  <div className="text-sm font-semibold truncate">{conv.title}</div>
                  <div className="text-[10px] opacity-50 font-medium">
                    {conv.createdAt.toLocaleDateString([], { month: 'short', day: 'numeric' })}
                  </div>
                </div>
                <button 
                  onClick={(e) => deleteConversation(e, conv.id)}
                  className="opacity-0 group-hover:opacity-100 p-1.5 hover:bg-red-500/20 rounded-md transition-all text-red-400"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-4 h-4">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M14.74 9l-.346 9m-4.788 0L9.26 9m9.968-3.21c.342.052.682.107 1.022.166m-1.022-.165L18.16 19.673a2.25 2.25 0 01-2.244 2.077H8.084a2.25 2.25 0 01-2.244-2.077L4.772 5.79m14.456 0a48.108 48.108 0 00-3.478-.397m-12 .562c.34-.059.68-.114 1.022-.165m0 0a48.11 48.11 0 013.478-.397m7.5 0v-.916c0-1.18-.91-2.164-2.09-2.201a51.964 51.964 0 00-3.32 0c-1.18.037-2.09 1.022-2.09 2.201v.916m7.5 0a48.667 48.667 0 00-7.5 0" />
                  </svg>
                </button>
              </div>
            ))
          )}
        </div>

        <div className="p-4 bg-black/20 border-t border-white/5">
          <div className="flex items-center justify-between text-[10px] text-white/40 font-bold uppercase tracking-tighter">
            <span>Always On Never Off</span>
            <div className="flex items-center gap-1.5">
              <span className="text-green-400">ACTIVE</span>
              <div className="w-1.5 h-1.5 rounded-full bg-green-400 animate-pulse"></div>
            </div>
          </div>
        </div>
      </aside>

      {/* Main Chat Area */}
      <main className="flex-1 flex flex-col relative overflow-hidden bg-[#f5eedb]">

        {/* Top bar with Persona Selector */}
        <header className="bg-white/80 backdrop-blur-xl px-4 md:px-6 py-3 flex items-center justify-between border-b border-[#046241]/10 z-10">
          <div className="flex items-center gap-4 overflow-hidden">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="lg:hidden p-2 text-[#046241] hover:bg-[#046241]/5 rounded-lg">
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6">
                <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25h16.5" />
              </svg>
            </button>
            <div className="hidden sm:block">
               <h1 className="text-sm font-bold text-[#133020] truncate max-w-[200px] leading-tight">
                {currentConversation?.title || 'Lifewood AI Chat'}
              </h1>
              <p className="text-[10px] text-[#133020]/40 font-medium italic">Active Session</p>
            </div>
          </div>

          {/* Persona Selection Integrated in Nav */}
          <div className="flex items-center gap-1 md:gap-2 bg-[#133020]/5 p-1 rounded-xl border border-[#046241]/10">
            {PERSONAS.map(p => (
              <button
                key={p.id}
                onClick={() => setActivePersona(p)}
                className={`relative flex items-center gap-2 px-2 md:px-3 py-1.5 rounded-lg transition-all duration-300 ${
                  activePersona.id === p.id 
                    ? 'bg-[#046241] text-white shadow-md' 
                    : 'text-[#133020]/60 hover:bg-[#046241]/5 hover:text-[#046241]'
                }`}
                title={p.description}
              >
                <div 
                  className={`w-2 h-2 md:w-3 md:h-3 rounded-full flex-shrink-0 shadow-sm ${activePersona.id === p.id ? 'ring-2 ring-white/50' : ''}`} 
                  style={{ backgroundColor: p.avatarColor }}
                ></div>
                <div className="flex flex-col items-start leading-none">
                  <span className={`text-[10px] md:text-xs font-bold uppercase tracking-tight ${activePersona.id === p.id ? 'block' : 'hidden md:block'}`}>
                    {p.name.split(' ')[1] || p.name}
                  </span>
                  {activePersona.id === p.id && (
                    <span className="hidden lg:block text-[8px] opacity-70 mt-0.5 font-medium uppercase">{p.role}</span>
                  )}
                </div>
                {activePersona.id === p.id && (
                  <div className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-4 h-[2px] bg-[#FFB347] rounded-full"></div>
                )}
              </button>
            ))}
          </div>
        </header>

        {/* Message Container */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8 lifewood-scrollbar">
          {(!currentConversation || currentConversation.messages.length === 0) && (
            <div className="h-full flex flex-col items-center justify-center text-center max-w-md mx-auto space-y-8 py-12">
              <div className="relative group">
                <div className="absolute inset-0 bg-[#FFB347] blur-2xl opacity-20 group-hover:opacity-40 transition-opacity"></div>
                <div className="relative w-24 h-24 bg-white rounded-[2rem] shadow-2xl flex items-center justify-center border border-[#046241]/10 transition-transform hover:scale-105 duration-300">
                  <div className="w-12 h-12 rounded-full animate-pulse shadow-inner" style={{ backgroundColor: activePersona.avatarColor }}></div>
                </div>
              </div>
              <div className="space-y-3">
                <h2 className="text-3xl font-black text-[#046241] tracking-tighter">I'm your {activePersona.name}</h2>
                <p className="text-sm text-[#133020]/60 leading-relaxed font-medium">
                  {activePersona.description} <br/> How can Lifewood bridge your innovation needs today?
                </p>
                <div className="flex flex-wrap justify-center gap-2 pt-4">
                  <button onClick={() => setInput("Tell me about Lifewood's AI data solutions.")} className="px-3 py-1.5 bg-white border border-[#046241]/10 rounded-full text-[11px] font-bold text-[#046241] hover:border-[#FFB347] transition-all">AI DATA SOLUTIONS</button>
                  <button onClick={() => setInput("How does Lifewood approach ESG and sustainability?")} className="px-3 py-1.5 bg-white border border-[#046241]/10 rounded-full text-[11px] font-bold text-[#046241] hover:border-[#FFB347] transition-all">ESG & SUSTAINABILITY</button>
                </div>
              </div>
            </div>
          )}

          {currentConversation?.messages.map((msg) => (
            <div key={msg.id} className={`flex ${msg.sender === SenderType.USER ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
              <div className={`flex gap-4 max-w-[90%] md:max-w-[75%] ${msg.sender === SenderType.USER ? 'flex-row-reverse' : ''}`}>
                <div className={`flex-shrink-0 w-9 h-9 rounded-xl flex items-center justify-center shadow-md ${msg.sender === SenderType.USER ? 'bg-[#FFB347] border border-[#133020]/10' : ''}`} style={{ backgroundColor: msg.sender === SenderType.AI ? activePersona.avatarColor : undefined }}>
                  {msg.sender === SenderType.AI ? (
                    <div className="w-5 h-5 bg-white/30 rounded-full shadow-inner ring-1 ring-white/20"></div>
                  ) : (
                    <span className="text-[10px] font-bold text-[#133020]">YOU</span>
                  )}
                </div>
                <div className={`space-y-2 ${msg.sender === SenderType.USER ? 'items-end' : 'items-start'} flex flex-col`}>
                  <div className={`px-5 py-4 rounded-2xl text-sm leading-relaxed shadow-sm transition-all ${
                    msg.sender === SenderType.USER 
                      ? 'bg-[#FFB347] text-[#133020] rounded-tr-none font-medium' 
                      : 'bg-white text-[#133020] rounded-tl-none border border-[#046241]/10'
                  }`}>
                    {msg.text}
                    {msg.attachments && msg.attachments.length > 0 && (
                      <div className="mt-4 grid grid-cols-1 gap-2">
                        {msg.attachments.map((file, idx) => (
                          <div key={idx} className="rounded-xl overflow-hidden border border-[#133020]/10 max-h-64 shadow-inner">
                            {file.mimeType.startsWith('image/') ? (
                              <img src={file.data} alt="Attachment" className="w-full h-full object-cover" />
                            ) : (
                              <div className="p-4 bg-black/5 flex items-center gap-3 text-xs font-bold text-[#133020]/70">
                                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6 text-[#046241]">
                                  <path strokeLinecap="round" strokeLinejoin="round" d="M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m.75 12l3 3m0 0l3-3m-3 3v-6m-1.5-9H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z" />
