import { GoogleGenAI } from "@google/genai";
import { FileData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export interface AIResponse {
  text: string;
  generatedImageUrl?: string;
}

export const getGeminiResponse = async (
  userMessage: string, 
  personaInstruction: string,
  attachments: FileData[] = [],
  isCreative: boolean = false
): Promise<AIResponse> => {
  try {
    const parts: any[] = [{ text: userMessage }];

    // Handle attachments
    attachments.forEach(file => {
      const base64Data = file.data.split(',')[1] || file.data;
      parts.push({
        inlineData: {
          data: base64Data,
          mimeType: file.mimeType
        }
      });
    });

    // Select model based on persona type
    const modelName = isCreative ? 'gemini-2.5-flash-image' : 'gemini-3-flash-preview';

    const response = await ai.models.generateContent({
      model: modelName,
      contents: [{ parts }],
      config: {
        systemInstruction: personaInstruction,
        // Only add imageConfig if using the image model
        ...(isCreative && {
          imageConfig: {
            aspectRatio: "1:1"
          }
        })
      },
    });

    let text = "";
    let generatedImageUrl = undefined;

    // Iterate through parts to find text and image data
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.text) {
          text += part.text;
        } else if (part.inlineData) {
          generatedImageUrl = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
    }

    return { 
      text: text || (generatedImageUrl ? "Here is the visual concept you requested:" : ""), 
      generatedImageUrl 
    };
  } catch (error) {
    console.error("Gemini API Error:", error);
    return { 
      text: "I apologize, but I encountered a technological glitch while rendering your request. Our team is proactive and working to resolve it." 
    };
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { LifewoodLogo, COLORS, PERSONAS } from './constants';
import { Message, SenderType, Conversation, Persona, FileData } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  const [conversations, setConversations] = useState<Conversation[]>(() => {
    const saved = localStorage.getItem('lifewood_conversations');
    return saved ? JSON.parse(saved).map((c: any) => ({
      ...c,
      messages: c.messages.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
      createdAt: new Date(c.createdAt)
    })) : [];
  });

  const [activeId, setActiveId] = useState<string | null>(null);
  const [activePersona, setActivePersona] = useState<Persona>(PERSONAS[0]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [attachments, setAttachments] = useState<FileData[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const currentConversation = conversations.find(c => c.id === activeId);

  useEffect(() => {
    localStorage.setItem('lifewood_conversations', JSON.stringify(conversations));
  }, [conversations]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [currentConversation?.messages, isLoading]);

  const startNewChat = (persona: Persona = activePersona) => {
    const newId = Date.now().toString();
    const newConv: Conversation = {
      id: newId,
      title: 'New Conversation',
      messages: [],
      personaId: persona.id,
      createdAt: new Date(),
    };
    setConversations(prev => [newConv, ...prev]);
    setActiveId(newId);
    setActivePersona(persona);
    setIsSidebarOpen(false);
  };

  const deleteConversation = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setConversations(prev => prev.filter(c => c.id !== id));
    if (activeId === id) setActiveId(null);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    Array.from(files).forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const base64 = event.target?.result as string;
        setAttachments(prev => [...prev, {
          data: base64,
          mimeType: file.type,
          fileName: file.name
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleSend = async () => {
    if ((!input.trim() && attachments.length === 0) || isLoading) return;

    let targetConv = currentConversation;
    if (!targetConv) {
      const newId = Date.now().toString();
      targetConv = {
        id: newId,
        title: input.slice(0, 30) || 'New Conversation',
        messages: [],
        personaId: activePersona.id,
        createdAt: new Date(),
      };
      setConversations(prev => [targetConv!, ...prev]);
      setActiveId(newId);
    }

    const userMessage: Message = {
      id: Date.now().toString(),
      text: input,
      sender: SenderType.USER,
      timestamp: new Date(),
      attachments: [...attachments],
    };

    const updatedConv = {
      ...targetConv,
      title: targetConv.messages.length === 0 ? (input.slice(0, 30) || 'New Conversation') : targetConv.title,
      messages: [...targetConv.messages, userMessage]
    };

    setConversations(prev => prev.map(c => c.id === updatedConv.id ? updatedConv : c));
    setInput('');
    setAttachments([]);
    setIsLoading(true);

    const aiResponse = await getGeminiResponse(
      userMessage.text, 
      activePersona.instruction,
      userMessage.attachments,
      !!activePersona.isCreative
    );

    const aiMessage: Message = {
      id: (Date.now() + 1).toString(),
      text: aiResponse.text,
      generatedImageUrl: aiResponse.generatedImageUrl,
      sender: SenderType.AI,
      timestamp: new Date(),
    };

    setConversations(prev => prev.map(c => 
      c.id === updatedConv.id ? { ...c, messages: [...c.messages, aiMessage] } : c
    ));
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleDownload = (url: string, filename: string) => {
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="flex h-screen bg-[#f5eedb] text-[#133020] overflow-hidden">

      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-72 bg-[#133020] transition-transform duration-300 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 flex flex-col shadow-2xl`}>
        <div className="p-6 border-b border-white/10">
          <LifewoodLogo />
          <button 
            onClick={() => startNewChat()}
            className="w-full mt-6 bg-[#046241] hover:bg-[#057a51] text-white py-3 rounded-xl flex items-center justify-center gap-2 font-bold transition-all shadow-lg active:scale-95"
          >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5">
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
            </svg>
            NEW CHAT
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-2 lifewood-scrollbar">
          <h3 className="text-white/40 text-[10px] font-bold uppercase tracking-widest px-2 mb-2">History</h3>
          {conversations.length === 0 ? (
            <div className="text-white/30 text-xs px-2 italic mt-4">No recent activity</div>
          ) : (
            conversations.map(conv => (
              <div 
                key={conv.id}
                onClick={() => {
                  setActiveId(conv.id);
                  const p = PERSONAS.find(p => p.id === conv.personaId);
                  if (p) setActivePersona(p);
                  setIsSidebarOpen(false);
                }}
                className={`group relative p-3 rounded-xl cursor-pointer transition-all flex items-center justify-between ${activeId === conv.id ? 'bg-[#046241] text-white shadow-inner' : 'hover:bg-white/5 text-white/70 hover:text-white'}`}
              >
                <div className="flex-1 min-w-0 pr-2">
                  <div className="text-sm font-semibold truncate">{conv.title}</div>
                  <div className="text-[10px] opacity-50 font-medium">
                    {conv.createdAt.toLocaleDateString([], { month: 'short', day: 'numeric' })}
                  </div>
                </div>
                <button 
                  onClick={(e) => deleteConversation(e, conv.id)}
                  className="opacity-0 group-hover:opacity-100 p-1.5 hover:bg-red-500/20 rounded-md transition-all text-red-400"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-4 h-4">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M14.74 9l-.346 9m-4.788 0L9.26 9m9.968-3.21c.342.052.682.107 1.022.166m-1.022-.165L18.16 19.673a2.25 2.25 0 01-2.244 2.077H8.084a2.25 2.25 0 01-2.244-2.077L4.772 5.79m14.456 0a48.108 48.108 0 00-3.478-.397m-12 .562c.34-.059.68-.114 1.022-.165m0 0a48.11 48.11 0 013.478-.397m7.5 0v-.916c0-1.18-.91-2.164-2.09-2.201a51.964 51.964 0 00-3.32 0c-1.18.037-2.09 1.022-2.09 2.201v.916m7.5 0a48.667 48.667 0 00-7.5 0" />
                  </svg>
                </button>
              </div>
            ))
          )}
        </div>

        <div className="p-4 bg-black/20 border-t border-white/5">
          <div className="flex items-center justify-between text-[10px] text-white/40 font-bold uppercase tracking-tighter">
            <span>Always On Never Off</span>
            <div className="flex items-center gap-1.5">
              <span className="text-green-400">ACTIVE</span>
              <div className="w-1.5 h-1.5 rounded-full bg-green-400 animate-pulse"></div>
            </div>
          </div>
        </div>
      </aside>

      {/* Main Chat Area */}
      <main className="flex-1 flex flex-col relative overflow-hidden bg-[#f5eedb]">

        {/* Top bar with Persona Selector */}
        <header className="bg-white/80 backdrop-blur-xl px-4 md:px-6 py-3 flex items-center justify-between border-b border-[#046241]/10 z-10">
          <div className="flex items-center gap-4 overflow-hidden">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="lg:hidden p-2 text-[#046241] hover:bg-[#046241]/5 rounded-lg">
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6">
                <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25h16.5" />
              </svg>
            </button>
            <div className="hidden sm:block">
               <h1 className="text-sm font-bold text-[#133020] truncate max-w-[200px] leading-tight">
                {currentConversation?.title || 'Lifewood AI Chat'}
              </h1>
              <p className="text-[10px] text-[#133020]/40 font-medium italic">Active Session</p>
            </div>
          </div>

          <div className="flex items-center gap-1 md:gap-2 bg-[#133020]/5 p-1 rounded-xl border border-[#046241]/10">
            {PERSONAS.map(p => (
              <button
                key={p.id}
                onClick={() => setActivePersona(p)}
                className={`relative flex items-center gap-2 px-2 md:px-3 py-1.5 rounded-lg transition-all duration-300 ${
                  activePersona.id === p.id 
                    ? 'bg-[#046241] text-white shadow-md' 
                    : 'text-[#133020]/60 hover:bg-[#046241]/5 hover:text-[#046241]'
                }`}
                title={p.description}
              >
                <div 
                  className={`w-2 h-2 md:w-3 md:h-3 rounded-full flex-shrink-0 shadow-sm ${activePersona.id === p.id ? 'ring-2 ring-white/50' : ''}`} 
                  style={{ backgroundColor: p.avatarColor }}
                ></div>
                <div className="flex flex-col items-start leading-none">
                  <span className={`text-[10px] md:text-xs font-bold uppercase tracking-tight ${activePersona.id === p.id ? 'block' : 'hidden md:block'}`}>
                    {p.name.split(' ')[1] || p.name}
                  </span>
                  {activePersona.id === p.id && (
                    <span className="hidden lg:block text-[8px] opacity-70 mt-0.5 font-medium uppercase">{p.role}</span>
                  )}
                </div>
              </button>
            ))}
          </div>
        </header>

        {/* Message Container */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8 lifewood-scrollbar">
          {(!currentConversation || currentConversation.messages.length === 0) && (
            <div className="h-full flex flex-col items-center justify-center text-center max-w-md mx-auto space-y-8 py-12">
              <div className="relative group">
                <div className="absolute inset-0 bg-[#FFB347] blur-2xl opacity-20 group-hover:opacity-40 transition-opacity"></div>
                <div className="relative w-24 h-24 bg-white rounded-[2rem] shadow-2xl flex items-center justify-center border border-[#046241]/10 transition-transform hover:scale-105 duration-300">
                  <div className="w-12 h-12 rounded-full animate-pulse shadow-inner" style={{ backgroundColor: activePersona.avatarColor }}></div>
                </div>
              </div>
              <div className="space-y-3">
                <h2 className="text-3xl font-black text-[#046241] tracking-tighter">I'm your {activePersona.name}</h2>
                <p className="text-sm text-[#133020]/60 leading-relaxed font-medium">
                  {activePersona.description} <br/> How can Lifewood bridge your innovation needs today?
                </p>
                <div className="flex flex-wrap justify-center gap-2 pt-4">
                  <button onClick={() => setInput("Tell me about Lifewood's AI data solutions.")} className="px-3 py-1.5 bg-white border border-[#046241]/10 rounded-full text-[11px] font-bold text-[#046241] hover:border-[#FFB347] transition-all">AI DATA SOLUTIONS</button>
                  {activePersona.isCreative && (
                    <button onClick={() => setInput("Generate a futuristic concept for an AI bridge in ASEAN.")} className="px-3 py-1.5 bg-[#FFC370] border border-[#133020]/10 rounded-full text-[11px] font-bold text-[#133020] hover:scale-105 transition-all">GENERATE CONCEPT</button>
                  )}
                  <button onClick={() => setInput("How does Lifewood approach ESG and sustainability?")} className="px-3 py-1.5 bg-white border border-[#046241]/10 rounded-full text-[11px] font-bold text-[#046241] hover:border-[#FFB347] transition-all">ESG & SUSTAINABILITY</button>
                </div>
              </div>
            </div>
          )}

          {currentConversation?.messages.map((msg) => (
            <div key={msg.id} className={`flex ${msg.sender === SenderType.USER ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
              <div className={`flex gap-4 max-w-[90%] md:max-w-[75%] ${msg.sender === SenderType.USER ? 'flex-row-reverse' : ''}`}>
                <div className={`flex-shrink-0 w-9 h-9 rounded-xl flex items-center justify-center shadow-md ${msg.sender === SenderType.USER ? 'bg-[#FFB347] border border-[#133020]/10' : ''}`} style={{ backgroundColor: msg.sender === SenderType.AI ? activePersona.avatarColor : undefined }}>
                  {msg.sender === SenderType.AI ? (
                    <div className="w-5 h-5 bg-white/30 rounded-full shadow-inner ring-1 ring-white/20"></div>
                  ) : (
                    <span className="text-[10px] font-bold text-[#133020]">YOU</span>
                  )}
                </div>
                <div className={`space-y-2 ${msg.sender === SenderType.USER ? 'items-end' : 'items-start'} flex flex-col`}>
                  <div className={`px-5 py-4 rounded-2xl text-sm leading-relaxed shadow-sm transition-all ${
                    msg.sender === SenderType.USER 
                      ? 'bg-[#FFB347] text-[#133020] rounded-tr-none font-medium' 
                      : 'bg-white text-[#133020] rounded-tl-none border border-[#046241]/10'
                  }`}>
                    {msg.text}

                    {/* Render Generated Images */}
                    {msg.generatedImageUrl && (
                      <div className="mt-4 relative group">
                        <div className="rounded-2xl overflow-hidden shadow-2xl border-4 border-[#f5eedb]">
                          <img src={msg.generatedImageUrl} alt="Generated Asset" className="w-full h-auto object-cover" />
                        </div>
                        <button 
                          onClick={() => handleDownload(msg.generatedImageUrl!, `lifewood-asset-${msg.id}.png`)}
                          className="absolute bottom-4 right-4 bg-[#133020] text-white p-2.5 rounded-xl shadow-lg opacity-0 group-hover:opacity-100 transition-all active:scale-90"
                        >
                          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75V16.5M7.5 12L12 16.5m0 0L16.5 12M12 16.5V3" />
                          </svg>
                        </button>
                      </div>
                    )}

                    {/* Render User Attachments */}
                    {msg.attachments && msg.attachments.length > 0 && (
                      <div className="mt-4 grid grid-cols-1 gap-2">
                        {msg.attachments.map((file, idx) => (
                          <div key={idx} className="rounded-xl overflow-hidden border border-[#133020]/10 max-h-64 shadow-inner">
                            {file.mimeType.startsWith('image/') ? (
                              <img src={file.data} alt="Attachment" className="w-full h-full object-cover" />
                            ) : (
                              <div className="p-4 bg-black/5 flex items-center gap-3 text-xs font-bold text-[#133020]/70">
                                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6 text-[#046241]">
                                  <path strokeLinecap="round" strokeLinejoin="round" d="M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m.75 12l3 3m0 0l3-3m-3 3v-6m-1.5-9H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z" />
                                </svg>
                                {file.fileName}
                              </div>
                            )}
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                  <span className="text-[9px] text-[#133020]/30 font-black uppercase tracking-widest px-1">
                    {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              </div>
            </div>
          ))}

          {isLoading && (
            <div className="flex justify-start animate-in fade-in duration-300">
               <div className="flex gap-4">
                <div className="flex-shrink-0 w-9 h-9 rounded-xl flex items-center justify-center shadow-md animate-pulse" style={{ backgroundColor: activePersona.avatarColor }}>
                  <div className="w-5 h-5 bg-white/30 rounded-full shadow-inner"></div>
                </div>
                <div className="bg-white/60 px-6 py-4 rounded-2xl rounded-tl-none flex items-center gap-2 border border-[#046241]/10">
                  <span className="text-[11px] font-bold text-[#046241] mr-2">
                    {activePersona.isCreative ? 'GENERATING ASSET' : 'THINKING'}
                  </span>
                  <div className="w-2 h-2 bg-[#046241] rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                  <div className="w-2 h-2 bg-[#046241] rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                  <div className="w-2 h-2 bg-[#046241] rounded-full animate-bounce"></div>
                </div>
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input Bar */}
        <div className="p-4 md:p-8 bg-gradient-to-t from-[#f5eedb] to-transparent">
          <div className="max-w-4xl mx-auto space-y-4">

            {attachments.length > 0 && (
              <div className="flex flex-wrap gap-2 px-2 animate-in slide-in-from-bottom-4 duration-500">
                {attachments.map((file, idx) => (
                  <div key={idx} className="relative group rounded-xl overflow-hidden border-2 border-[#FFB347] w-20 h-20 shadow-xl transition-all hover:scale-105">
                    {file.mimeType.startsWith('image/') ? (
                      <img src={file.data} className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full bg-[#133020] flex items-center justify-center text-white">
                         <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-[#FFB347]" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                           <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                         </svg>
                      </div>
                    )}
                    <button 
                      onClick={() => setAttachments(prev => prev.filter((_, i) => i !== idx))}
                      className="absolute top-0 right-0 bg-red-600 text-white p-1 rounded-bl-xl opacity-100 lg:opacity-0 lg:group-hover:opacity-100 transition-all shadow-md"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                        <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                      </svg>
                    </button>
                  </div>
                ))}
              </div>
            )}

            <div className="relative flex items-end gap-3 bg-white p-3 md:p-4 rounded-3xl shadow-2xl border border-[#046241]/10 focus-within:ring-2 focus-within:ring-[#FFB347] transition-all duration-300">
              <input 
                type="file" 
                multiple 
                className="hidden" 
                ref={fileInputRef} 
                onChange={handleFileUpload}
                accept="image/*,application/pdf,text/plain"
              />
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="p-3 text-[#133020]/30 hover:text-[#046241] hover:bg-[#046241]/5 rounded-2xl transition-all"
              >
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-7 h-7">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M18.375 12.739l-7.693 7.693a4.5 4.5 0 01-6.364-6.364l10.94-10.94A3 3 0 1119.5 7.372L8.552 18.32a1.5 1.5 0 01-2.121-2.121L16.715 5.86" />
                </svg>
              </button>

              <textarea
                rows={1}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={handleKeyPress}
                placeholder={activePersona.isCreative ? "Describe the image you want..." : `Ask ${activePersona.name}...`}
                className="flex-1 bg-transparent border-none focus:outline-none focus:ring-0 resize-none py-3 text-sm font-medium max-h-48 lifewood-scrollbar placeholder-[#133020]/30"
              />

              <button
                onClick={handleSend}
                disabled={isLoading || (!input.trim() && attachments.length === 0)}
                className={`p-3.5 rounded-2xl transition-all shadow-xl active:scale-95 flex items-center justify-center ${
                  isLoading || (!input.trim() && attachments.length === 0)
                    ? 'bg-gray-100 text-gray-300'
                    : activePersona.isCreative ? 'bg-[#FFC370] text-[#133020]' : 'bg-[#FFB347] text-[#133020]'
                }`}
              >
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-6 h-6">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M6 12L3.269 3.126A59.768 59.768 0 0121.485 12 59.77 59.77 0 013.27 20.876L5.999 12zm0 0h7.5" />
                </svg>
              </button>
            </div>

            <div className="flex justify-between items-center px-4">
               <p className="text-[10px] text-[#133020]/40 font-black uppercase tracking-[0.2em]">
                ALWAYS ON NEVER OFF
              </p>
              <div className="flex gap-4 items-center">
                 <p className="text-[10px] text-[#133020]/40 font-bold uppercase cursor-pointer hover:text-[#046241]">Asset Studio</p>
                 <p className="text-[10px] text-[#133020]/40 font-medium">{activePersona.isCreative ? 'Gemini 2.5 Image' : 'Gemini 3 Flash'}</p>
              </div>
            </div>
          </div>
        </div>
      </main>

      {/* Mobile Sidebar Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-[#133020]/40 backdrop-blur-sm z-40 lg:hidden"
          onClick={() => setIsSidebarOpen(false)}
        ></div>
      )}
    </div>
  );
};

export default App;

export enum SenderType {
  USER = 'user',
  AI = 'ai'
}

export interface FileData {
  data: string;
  mimeType: string;
  fileName: string;
}

export interface Message {
  id: string;
  text: string;
  sender: SenderType;
  timestamp: Date;
  attachments?: FileData[];
  generatedImageUrl?: string;
}

export interface Persona {
  id: string;
  name: string;
  role: string;
  description: string;
  instruction: string;
  avatarColor: string;
  isCreative?: boolean;
  suggestedPrompts: string[];
}

export interface Conversation {
  id: string;
  title: string;
  messages: Message[];
  personaId: string;
  createdAt: Date;
}

import React, { useState, useRef, useEffect } from 'react';
import { LifewoodLogo, COLORS, PERSONAS } from './constants';
import { Message, SenderType, Conversation, Persona, FileData } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  const [conversations, setConversations] = useState<Conversation[]>(() => {
    const saved = localStorage.getItem('lifewood_conversations');
    return saved ? JSON.parse(saved).map((c: any) => ({
      ...c,
      messages: c.messages.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
      createdAt: new Date(c.createdAt)
    })) : [];
  });

  const [activeId, setActiveId] = useState<string | null>(null);
  const [activePersona, setActivePersona] = useState<Persona>(PERSONAS[0]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [attachments, setAttachments] = useState<FileData[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const currentConversation = conversations.find(c => c.id === activeId);

  useEffect(() => {
    localStorage.setItem('lifewood_conversations', JSON.stringify(conversations));
  }, [conversations]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [currentConversation?.messages, isLoading]);

  const startNewChat = (persona: Persona = activePersona) => {
    const newId = Date.now().toString();
    const newConv: Conversation = {
      id: newId,
      title: 'New Conversation',
      messages: [],
      personaId: persona.id,
      createdAt: new Date(),
    };
    setConversations(prev => [newConv, ...prev]);
    setActiveId(newId);
    setActivePersona(persona);
    setIsSidebarOpen(false);
  };

  const deleteConversation = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setConversations(prev => prev.filter(c => c.id !== id));
    if (activeId === id) setActiveId(null);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    Array.from(files).forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const base64 = event.target?.result as string;
        setAttachments(prev => [...prev, {
          data: base64,
          mimeType: file.type,
          fileName: file.name
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleSend = async (overrideInput?: string) => {
    const finalInput = overrideInput || input;
    if ((!finalInput.trim() && attachments.length === 0) || isLoading) return;

    let targetConv = currentConversation;
    if (!targetConv) {
      const newId = Date.now().toString();
      targetConv = {
        id: newId,
        title: finalInput.slice(0, 30) || 'New Conversation',
        messages: [],
        personaId: activePersona.id,
        createdAt: new Date(),
      };
      setConversations(prev => [targetConv!, ...prev]);
      setActiveId(newId);
    }

    const userMessage: Message = {
      id: Date.now().toString(),
      text: finalInput,
      sender: SenderType.USER,
      timestamp: new Date(),
      attachments: [...attachments],
    };

    const updatedConv = {
      ...targetConv,
      title: targetConv.messages.length === 0 ? (finalInput.slice(0, 30) || 'New Conversation') : targetConv.title,
      messages: [...targetConv.messages, userMessage]
    };

    setConversations(prev => prev.map(c => c.id === updatedConv.id ? updatedConv : c));
    setInput('');
    setAttachments([]);
    setIsLoading(true);

    const aiResponse = await getGeminiResponse(
      userMessage.text, 
      activePersona.instruction,
      userMessage.attachments,
      !!activePersona.isCreative
    );

    const aiMessage: Message = {
      id: (Date.now() + 1).toString(),
      text: aiResponse.text,
      generatedImageUrl: aiResponse.generatedImageUrl,
      sender: SenderType.AI,
      timestamp: new Date(),
    };

    setConversations(prev => prev.map(c => 
      c.id === updatedConv.id ? { ...c, messages: [...c.messages, aiMessage] } : c
    ));
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleDownload = (url: string, filename: string) => {
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="flex h-screen bg-[#f5eedb] text-[#133020] overflow-hidden">

      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-72 bg-[#133020] transition-transform duration-300 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 flex flex-col shadow-2xl`}>
        <div className="p-6 border-b border-white/10">
          <LifewoodLogo />
          <button 
            onClick={() => startNewChat()}
            className="w-full mt-6 bg-[#046241] hover:bg-[#057a51] text-white py-3 rounded-xl flex items-center justify-center gap-2 font-bold transition-all shadow-lg active:scale-95"
          >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5">
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
            </svg>
            NEW CHAT
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-2 lifewood-scrollbar">
          <h3 className="text-white/40 text-[10px] font-bold uppercase tracking-widest px-2 mb-2">History</h3>
          {conversations.length === 0 ? (
            <div className="text-white/30 text-xs px-2 italic mt-4">No recent activity</div>
          ) : (
            conversations.map(conv => (
              <div 
                key={conv.id}
                onClick={() => {
                  setActiveId(conv.id);
                  const p = PERSONAS.find(p => p.id === conv.personaId);
                  if (p) setActivePersona(p);
                  setIsSidebarOpen(false);
                }}
                className={`group relative p-3 rounded-xl cursor-pointer transition-all flex items-center justify-between ${activeId === conv.id ? 'bg-[#046241] text-white shadow-inner' : 'hover:bg-white/5 text-white/70 hover:text-white'}`}
              >
                <div className="flex-1 min-w-0 pr-2">
                  <div className="text-sm font-semibold truncate">{conv.title}</div>
                  <div className="text-[10px] opacity-50 font-medium">
                    {conv.createdAt.toLocaleDateString([], { month: 'short', day: 'numeric' })}
                  </div>
                </div>
                <button 
                  onClick={(e) => deleteConversation(e, conv.id)}
                  className="opacity-0 group-hover:opacity-100 p-1.5 hover:bg-red-500/20 rounded-md transition-all text-red-400"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-4 h-4">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M14.74 9l-.346 9m-4.788 0L9.26 9m9.968-3.21c.342.052.682.107 1.022.166m-1.022-.165L18.16 19.673a2.25 2.25 0 01-2.244 2.077H8.084a2.25 2.25 0 01-2.244-2.077L4.772 5.79m14.456 0a48.108 48.108 0 00-3.478-.397m-12 .562c.34-.059.68-.114 1.022-.165m0 0a48.11 48.11 0 013.478-.397m7.5 0v-.916c0-1.18-.91-2.164-2.09-2.201a51.964 51.964 0 00-3.32 0c-1.18.037-2.09 1.022-2.09 2.201v.916m7.5 0a48.667 48.667 0 00-7.5 0" />
                  </svg>
                </button>
              </div>
            ))
          )}
        </div>

        <div className="p-4 bg-black/20 border-t border-white/5">
          <div className="flex items-center justify-between text-[10px] text-white/40 font-bold uppercase tracking-tighter">
            <span>Always On Never Off</span>
            <div className="flex items-center gap-1.5">
              <span className="text-green-400">ACTIVE</span>
              <div className="w-1.5 h-1.5 rounded-full bg-green-400 animate-pulse"></div>
            </div>
          </div>
        </div>
      </aside>

      {/* Main Chat Area */}
      <main className="flex-1 flex flex-col relative overflow-hidden bg-[#f5eedb]">

        {/* Top bar with Persona Selector */}
        <header className="bg-white/80 backdrop-blur-xl px-4 md:px-6 py-3 flex items-center justify-between border-b border-[#046241]/10 z-10">
          <div className="flex items-center gap-4 overflow-hidden">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="lg:hidden p-2 text-[#046241] hover:bg-[#046241]/5 rounded-lg">
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6">
                <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25h16.5" />
              </svg>
            </button>
            <div className="hidden sm:block">
               <h1 className="text-sm font-bold text-[#133020] truncate max-w-[200px] leading-tight">
                {currentConversation?.title || 'Lifewood AI Chat'}
              </h1>
              <p className="text-[10px] text-[#133020]/40 font-medium italic">Active Session</p>
            </div>
          </div>

          <div className="flex items-center gap-1 md:gap-2 bg-[#133020]/5 p-1 rounded-xl border border-[#046241]/10">
            {PERSONAS.map(p => (
              <button
                key={p.id}
                onClick={() => setActivePersona(p)}
                className={`relative flex items-center gap-2 px-2 md:px-3 py-1.5 rounded-lg transition-all duration-300 ${
                  activePersona.id === p.id 
                    ? 'bg-[#046241] text-white shadow-md' 
                    : 'text-[#133020]/60 hover:bg-[#046241]/5 hover:text-[#046241]'
                }`}
                title={p.description}
              >
                <div 
                  className={`w-2 h-2 md:w-3 md:h-3 rounded-full flex-shrink-0 shadow-sm ${activePersona.id === p.id ? 'ring-2 ring-white/50' : ''}`} 
                  style={{ backgroundColor: p.avatarColor }}
                ></div>
                <div className="flex flex-col items-start leading-none">
                  <span className={`text-[10px] md:text-xs font-bold uppercase tracking-tight ${activePersona.id === p.id ? 'block' : 'hidden md:block'}`}>
                    {p.name.split(' ')[1] || p.name}
                  </span>
                  {activePersona.id === p.id && (
                    <span className="hidden lg:block text-[8px] opacity-70 mt-0.5 font-medium uppercase">{p.role}</span>
                  )}
                </div>
              </button>
            ))}
          </div>
        </header>

        {/* Message Container */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8 lifewood-scrollbar">
          {(!currentConversation || currentConversation.messages.length === 0) && (
            <div className="h-full flex flex-col items-center justify-center text-center max-w-2xl mx-auto space-y-8 py-12">
              <div className="relative group">
                <div className="absolute inset-0 bg-[#FFB347] blur-3xl opacity-10 group-hover:opacity-30 transition-opacity"></div>
                <div className="relative w-24 h-24 bg-white rounded-[2rem] shadow-2xl flex items-center justify-center border border-[#046241]/10 transition-transform hover:scale-105 duration-300">
