    });

    const response = await ai.models.generateContent({
      model: modelName,
      contents: { parts },
      config: {
        ...(isImageMode && {
          imageConfig: {
            aspectRatio: "1:1"
          }
        })
      },
    });

    let text = "";
    let generatedImageUrl = undefined;

