import React, { useState, useRef, useEffect } from 'react';
import { SparkleIcon, UserAvatar, COLORS, TOOLS, MODELS } from './constants';
import { Message, SenderType, Conversation, FileData } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  const [conversations, setConversations] = useState<Conversation[]>(() => {
    const saved = localStorage.getItem('gemini_conversations');
    return saved ? JSON.parse(saved).map((c: any) => ({
      ...c,
      messages: c.messages.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
      createdAt: new Date(c.createdAt)
    })) : [];
  });

  const [activeId, setActiveId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [attachments, setAttachments] = useState<FileData[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showTools, setShowTools] = useState(false);
  const [selectedTool, setSelectedTool] = useState(TOOLS[1]); // Default to Create images as per context
  const [selectedModel, setSelectedModel] = useState(MODELS[0]);
  const [showModels, setShowModels] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const currentConversation = conversations.find(c => c.id === activeId);

  useEffect(() => {
    localStorage.setItem('gemini_conversations', JSON.stringify(conversations));
  }, [conversations]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [currentConversation?.messages, isLoading]);

  const startNewChat = () => {
    setActiveId(null);
    setInput('');
    setAttachments([]);
    setIsSidebarOpen(false);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    Array.from(files).forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        setAttachments(prev => [...prev, {
          data: event.target?.result as string,
          mimeType: file.type,
          fileName: file.name
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleSend = async (overrideInput?: string) => {
    const finalInput = overrideInput || input;
    if ((!finalInput.trim() && attachments.length === 0) || isLoading) return;

    let targetConv = currentConversation;
    if (!targetConv) {
      const newId = Date.now().toString();
      targetConv = {
        id: newId,
        title: finalInput.slice(0, 30) || 'New Chat',
        messages: [],
        personaId: 'default',
        createdAt: new Date(),
      };
      setConversations(prev => [targetConv!, ...prev]);
      setActiveId(newId);
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      text: finalInput,
      sender: SenderType.USER,
      timestamp: new Date(),
      attachments: [...attachments],
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, userMsg] } : c
    ));

    setInput('');
    setAttachments([]);
    setIsLoading(true);

    const aiResponse = await getGeminiResponse(
      userMsg.text, 
      userMsg.attachments,
      selectedTool.id,
      selectedModel.id
    );

    const aiMsg: Message = {
      id: (Date.now() + 1).toString(),
      text: aiResponse.text,
      generatedImageUrl: aiResponse.generatedImageUrl,
      sender: SenderType.AI,
      timestamp: new Date(),
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, aiMsg] } : c
    ));
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex h-screen bg-[#131314] text-[#e3e3e3] overflow-hidden font-sans">

      {/* Top Header */}
      <header className="fixed top-0 left-0 right-0 h-16 flex items-center justify-between px-6 z-40 bg-[#131314]/80 backdrop-blur-md">
        <div className="flex items-center gap-4">
          <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-white/10 rounded-full">
            <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M3 18h18v-2H3v2zm0-5h18v-2H3v2zm0-7v2h18V6H3z"/></svg>
          </button>
          <span className="text-xl font-medium tracking-tight">Gemini</span>
          <div className="flex items-center gap-1 bg-[#1e1f20] px-3 py-1.5 rounded-full cursor-pointer hover:bg-[#2a2b2d] ml-4">
             <span className="text-sm font-medium">{currentConversation?.title || 'New chat'}</span>
             <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M7 10l5 5 5-5z"/></svg>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button className="hidden md:flex items-center gap-2 bg-[#1e1f20] hover:bg-[#2a2b2d] px-4 py-2 rounded-full border border-[#444746] text-sm font-medium transition-all">
            <SparkleIcon className="w-4 h-4" />
            Upgrade to Gemini Advanced
          </button>
          <UserAvatar />
        </div>
      </header>

      {/* Sidebar Overlay */}
      {isSidebarOpen && (
        <aside className="fixed inset-y-0 left-0 w-72 bg-[#1e1f20] z-50 shadow-2xl animate-in slide-in-from-left duration-300 flex flex-col">
          <div className="p-6">
            <button 
              onClick={startNewChat}
              className="flex items-center gap-3 w-full bg-[#131314] hover:bg-black p-4 rounded-xl text-sm font-medium border border-[#444746]"
            >
              <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24"><path d="M19 13h-6v6h-2v-6H5v-2h6V5h2v6h6v2z"/></svg>
              New chat
            </button>
          </div>
          <div className="flex-1 overflow-y-auto px-4 space-y-1 lifewood-scrollbar">
            <p className="text-xs font-bold text-[#b4b4b4] uppercase tracking-wider px-2 mb-2">Recent</p>
            {conversations.map(conv => (
              <button
                key={conv.id}
                onClick={() => { setActiveId(conv.id); setIsSidebarOpen(false); }}
                className={`w-full text-left p-3 rounded-lg text-sm truncate transition-colors ${activeId === conv.id ? 'bg-[#3c4043] text-white' : 'hover:bg-white/5 text-[#c4c7c5]'}`}
              >
                {conv.title}
              </button>
            ))}
          </div>
        </aside>
      )}

      {/* Main Content */}
      <main className="flex-1 flex flex-col pt-16 relative h-full">
        <div className="flex-1 overflow-y-auto flex flex-col items-center lifewood-scrollbar pb-32">
          <div className="w-full max-w-3xl px-6 md:px-0 space-y-12 py-10">

            {(!currentConversation || currentConversation.messages.length === 0) && (
              <div className="mt-20 space-y-8">
                <h2 className="text-4xl md:text-5xl font-medium tracking-tight text-center bg-gradient-to-r from-[#4285f4] via-[#9b72cb] to-[#d96570] bg-clip-text text-transparent">
                  Hello, Gemini
                </h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="bg-[#1e1f20] p-6 rounded-2xl border border-[#444746] hover:bg-[#2a2b2d] cursor-pointer transition-all">
                    <p className="text-sm font-medium">Create an image of a floating astronaut in a cyberpunk city</p>
                    <div className="mt-4 flex justify-end"><SparkleIcon className="w-5 h-5 opacity-40" /></div>
                  </div>
                  <div className="bg-[#1e1f20] p-6 rounded-2xl border border-[#444746] hover:bg-[#2a2b2d] cursor-pointer transition-all">
                    <p className="text-sm font-medium">Suggest 5-day itinerary for a trip to Japan focusing on food</p>
                    <div className="mt-4 flex justify-end"><SparkleIcon className="w-5 h-5 opacity-40" /></div>
                  </div>
                </div>
              </div>
            )}

            {currentConversation?.messages.map((msg) => (
              <div key={msg.id} className={`flex flex-col ${msg.sender === SenderType.USER ? 'items-end' : 'items-start'} group animate-in fade-in slide-in-from-bottom-2`}>
                <div className="flex gap-4 w-full">
                  {msg.sender === SenderType.AI && (
                    <div className="flex-shrink-0 mt-1">
                      <SparkleIcon className="w-6 h-6" />
                    </div>
                  )}
                  <div className={`flex-1 ${msg.sender === SenderType.USER ? 'max-w-[80%] flex justify-end' : ''}`}>
                    <div className={`${msg.sender === SenderType.USER ? 'bg-[#1e1f20] px-6 py-3 rounded-[2rem] text-[15px] border border-[#444746]' : 'text-[16px] leading-relaxed'}`}>
                      {msg.text}
                      {msg.generatedImageUrl && (
                        <div className="mt-6 rounded-2xl overflow-hidden shadow-2xl max-w-lg border border-[#444746]">
                          <img src={msg.generatedImageUrl} className="w-full h-auto" />
                        </div>
                      )}
                      {msg.attachments?.map((at, i) => (
                        <div key={i} className="mt-4 max-w-xs rounded-xl overflow-hidden border border-[#444746]">
                          {at.mimeType.startsWith('image/') ? <img src={at.data} className="w-full h-auto" /> : <div className="p-4 bg-white/5 text-xs truncate">{at.fileName}</div>}
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            ))}

            {isLoading && (
              <div className="flex gap-4 w-full animate-pulse">
                <SparkleIcon className="w-6 h-6" />
                <div className="flex-1 space-y-3 pt-2">
                  <div className="h-2 bg-[#444746] rounded w-3/4"></div>
                  <div className="h-2 bg-[#444746] rounded w-1/2"></div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
        </div>

        {/* Floating Input Bar */}
        <div className="fixed bottom-0 left-0 right-0 p-6 flex justify-center bg-gradient-to-t from-[#131314] via-[#131314]/90 to-transparent">
          <div className="w-full max-w-3xl relative">

            {/* Tools Menu Popover */}
            {showTools && (
              <div className="absolute bottom-full mb-4 left-0 w-64 bg-[#1e1f20] border border-[#444746] rounded-2xl shadow-2xl overflow-hidden z-50 animate-in slide-in-from-bottom-2 duration-200">
                <div className="p-2 space-y-1">
                  {TOOLS.map(t => (
                    <button
                      key={t.id}
                      onClick={() => { setSelectedTool(t); setShowTools(false); }}
                      className="w-full flex items-center justify-between p-3 hover:bg-white/10 rounded-xl transition-colors"
                    >
                      <div className="flex items-center gap-3">
                        <span className="text-lg">{t.icon}</span>
                        <span className="text-sm font-medium">{t.name}</span>
                      </div>
                      {t.isLabs && <span className="text-[10px] font-bold bg-[#041e49] text-[#7cacf8] px-2 py-0.5 rounded-full">Labs</span>}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Models Menu Popover */}
            {showModels && (
              <div className="absolute bottom-full mb-4 right-0 w-64 bg-[#1e1f20] border border-[#444746] rounded-2xl shadow-2xl overflow-hidden z-50 animate-in slide-in-from-bottom-2 duration-200">
                <div className="p-2 space-y-1">
                  {MODELS.map(m => (
                    <button
                      key={m.id}
                      onClick={() => { setSelectedModel(m); setShowModels(false); }}
                      className={`w-full text-left p-3 rounded-xl transition-colors ${selectedModel.id === m.id ? 'bg-[#3c4043]' : 'hover:bg-white/5'}`}
                    >
                      <div className="text-sm font-bold">{m.name}</div>
                      <div className="text-xs text-[#b4b4b4]">{m.description}</div>
                    </button>
                  ))}
                </div>
              </div>
            )}

            <div className="bg-[#1e1f20] rounded-[2rem] p-2 flex items-end gap-2 border border-[#444746] focus-within:ring-1 focus-within:ring-[#444746] transition-all">
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="p-3 hover:bg-white/5 rounded-full text-[#b4b4b4] transition-colors"
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4"/></svg>
              </button>
              <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" multiple />

              <div className="flex-1 flex flex-col py-1">
                <textarea
                  rows={1}
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyDown={handleKeyPress}
                  placeholder={selectedTool.id === 'image' ? "Describe the image you want..." : "Enter a prompt here"}
                  className="w-full bg-transparent border-none resize-none py-2 px-2 text-[16px] max-h-40 overflow-y-auto"
                />

                <div className="flex items-center gap-2 mt-1">
                  <button 
                    onClick={() => setShowTools(!showTools)}
                    className="flex items-center gap-2 px-3 py-1.5 hover:bg-white/10 rounded-full transition-colors"
                  >
                    <span className="text-xs font-bold text-[#b4b4b4] flex items-center gap-2">
                       <span className="text-base">{selectedTool.icon}</span>
                       {selectedTool.name}
                    </span>
                  </button>
                </div>
              </div>

              <div className="flex items-center gap-1 self-center pr-2">
                 <button 
                  onClick={() => setShowModels(!showModels)}
                  className="flex items-center gap-1 px-3 py-2 hover:bg-white/5 rounded-full text-sm font-medium text-[#b4b4b4]"
                >
                  {selectedModel.name}
                  <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M7 10l5 5 5-5z"/></svg>
                </button>
                <button 
                  disabled={isLoading || (!input.trim() && attachments.length === 0)}
                  onClick={() => handleSend()}
                  className={`p-3 rounded-full transition-all ${(!input.trim() && attachments.length === 0) ? 'text-white/10' : 'text-[#8ab4f8] hover:bg-[#8ab4f8]/10'}`}
                >
                  <svg className="w-6 h-6 rotate-90" fill="currentColor" viewBox="0 0 24 24"><path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/></svg>
                </button>
              </div>
            </div>

            <p className="text-[11px] text-[#b4b4b4]/60 text-center mt-4 font-medium tracking-wide">
              Gemini can make mistakes, so double-check it
            </p>
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React from 'react';

export const COLORS = {
  bg: '#f5eedb',
  sidebar: '#133020',
  accent: '#046241',
  saffron: '#FFB347',
  earthYellow: '#FFC370',
  white: '#ffffff',
  text: '#133020',
};

export const TOOLS = [
  { id: 'chat', name: 'General Chat', icon: '💬', description: 'Standard AI interaction' },
  { id: 'image', name: 'Create Assets', icon: '🎨', description: 'Generate visual concepts' },
  { id: 'research', name: 'Deep Insight', icon: '🔍', description: 'Advanced research & data' },
  { id: 'canvas', name: 'Document Canvas', icon: '📝', description: 'Writing and structured data' },
  { id: 'maps', name: 'Global Logistics', icon: '📍', description: 'Mapping and location data', isLabs: true },
];

export const MODELS = [
  { id: 'gemini-3-flash-preview', name: 'Fast', description: 'Responsive and efficient' },
  { id: 'gemini-3-pro-preview', name: 'Pro', description: 'Advanced reasoning' },
];

export const LifewoodLogo: React.FC<{ className?: string }> = ({ className = "h-8" }) => (
  <div className={`flex items-center gap-2 ${className}`}>
    <svg viewBox="0 0 100 120" className="h-full fill-[#FFB347]">
      <path d="M50 0 L90 30 L90 90 L50 120 L10 90 L10 30 Z" />
    </svg>
    <span className="text-white font-bold text-2xl tracking-tighter">lifewood</span>
  </div>
);

export const SparkleIcon: React.FC<{ className?: string }> = ({ className = "w-5 h-5" }) => (
  <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" className={className}>
    <path d="M12 2L14.5 9.5L22 12L14.5 14.5L12 22L9.5 14.5L2 12L9.5 9.5L12 2Z" fill="#FFB347" />
  </svg>
);

import React, { useState, useRef, useEffect } from 'react';
import { LifewoodLogo, SparkleIcon, COLORS, TOOLS, MODELS } from './constants';
import { Message, SenderType, Conversation, FileData } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  const [conversations, setConversations] = useState<Conversation[]>(() => {
    const saved = localStorage.getItem('lifewood_v3_conversations');
    return saved ? JSON.parse(saved).map((c: any) => ({
      ...c,
      messages: c.messages.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
      createdAt: new Date(c.createdAt)
    })) : [];
  });

  const [activeId, setActiveId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [attachments, setAttachments] = useState<FileData[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const [showTools, setShowTools] = useState(false);
  const [selectedTool, setSelectedTool] = useState(TOOLS[0]);
  const [showModels, setShowModels] = useState(false);
  const [selectedModel, setSelectedModel] = useState(MODELS[0]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const currentConversation = conversations.find(c => c.id === activeId);

  useEffect(() => {
    localStorage.setItem('lifewood_v3_conversations', JSON.stringify(conversations));
  }, [conversations]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [currentConversation?.messages, isLoading]);

  const startNewChat = () => {
    setActiveId(null);
    setInput('');
    setAttachments([]);
    setIsSidebarOpen(false);
    setSelectedTool(TOOLS[0]);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    Array.from(files).forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        setAttachments(prev => [...prev, {
          data: event.target?.result as string,
          mimeType: file.type,
          fileName: file.name
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleSend = async (overrideInput?: string) => {
    const finalInput = overrideInput || input;
    if ((!finalInput.trim() && attachments.length === 0) || isLoading) return;

    let targetConv = currentConversation;
    if (!targetConv) {
      const newId = Date.now().toString();
      targetConv = {
        id: newId,
        title: finalInput.slice(0, 30) || 'New Lifewood Chat',
        messages: [],
        personaId: 'default',
        createdAt: new Date(),
      };
      setConversations(prev => [targetConv!, ...prev]);
      setActiveId(newId);
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      text: finalInput,
      sender: SenderType.USER,
      timestamp: new Date(),
      attachments: [...attachments],
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, userMsg] } : c
    ));

    setInput('');
    setAttachments([]);
    setIsLoading(true);

    const aiResponse = await getGeminiResponse(
      userMsg.text, 
      userMsg.attachments,
      selectedTool.id,
      selectedModel.id
    );

    const aiMsg: Message = {
      id: (Date.now() + 1).toString(),
      text: aiResponse.text,
      generatedImageUrl: aiResponse.generatedImageUrl,
      sender: SenderType.AI,
      timestamp: new Date(),
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, aiMsg] } : c
    ));
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const deleteConversation = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setConversations(prev => prev.filter(c => c.id !== id));
    if (activeId === id) setActiveId(null);
  };

  return (
    <div className="flex h-screen bg-[#f5eedb] text-[#133020] overflow-hidden font-sans">

      {/* Sidebar - Lifewood Branding */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-72 bg-[#133020] transition-transform duration-300 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 flex flex-col shadow-2xl`}>
        <div className="p-6 border-b border-white/10">
          <LifewoodLogo />
          <button 
            onClick={startNewChat}
            className="w-full mt-6 bg-[#046241] hover:bg-[#057a51] text-white py-3 rounded-xl flex items-center justify-center gap-2 font-bold transition-all shadow-lg active:scale-95"
          >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5">
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
            </svg>
            NEW CHAT
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-2 lifewood-scrollbar">
          <h3 className="text-white/40 text-[10px] font-bold uppercase tracking-widest px-2 mb-2">History</h3>
          {conversations.map(conv => (
            <div 
              key={conv.id}
              onClick={() => { setActiveId(conv.id); setIsSidebarOpen(false); }}
              className={`group relative p-3 rounded-xl cursor-pointer transition-all flex items-center justify-between ${activeId === conv.id ? 'bg-[#046241] text-white shadow-inner' : 'hover:bg-white/5 text-white/70 hover:text-white'}`}
            >
              <div className="flex-1 min-w-0 pr-2">
                <div className="text-sm font-semibold truncate">{conv.title}</div>
              </div>
              <button onClick={(e) => deleteConversation(e, conv.id)} className="opacity-0 group-hover:opacity-100 p-1.5 hover:bg-red-500/20 rounded-md transition-all text-red-400">
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
              </button>
            </div>
          ))}
        </div>

        <div className="p-4 bg-black/20 border-t border-white/5">
          <div className="flex items-center justify-between text-[10px] text-white/40 font-bold uppercase tracking-tighter">
            <span>Always On Never Off</span>
            <div className="w-1.5 h-1.5 rounded-full bg-green-400 animate-pulse"></div>
          </div>
        </div>
      </aside>

      {/* Main Area */}
      <main className="flex-1 flex flex-col relative overflow-hidden h-full">

        {/* Header Overlay */}
        <header className="absolute top-0 left-0 right-0 h-16 flex items-center justify-between px-6 z-40 lg:hidden">
          <button onClick={() => setIsSidebarOpen(true)} className="p-2 bg-[#133020] text-white rounded-lg shadow-lg">
            <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M3 18h18v-2H3v2zm0-5h18v-2H3v2zm0-7v2h18V6H3z"/></svg>
          </button>
        </header>

        {/* Message Container */}
        <div className="flex-1 overflow-y-auto flex flex-col items-center lifewood-scrollbar pb-40 px-4">
          <div className="w-full max-w-3xl space-y-12 py-10">

            {(!currentConversation || currentConversation.messages.length === 0) && (
              <div className="mt-20 space-y-10">
                <div className="text-center space-y-4">
                  <h2 className="text-5xl font-black text-[#046241] tracking-tighter drop-shadow-sm">
                    Lifewood AI
                  </h2>
                  <p className="text-sm font-bold text-[#133020]/40 uppercase tracking-widest bg-[#046241]/5 px-4 py-1.5 rounded-full inline-block">
                    PROACTIVE INNOVATION PARTNER
                  </p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {[
                    { text: "Generate a concept image for a sustainable ASEAN data center.", tool: 'image' },
                    { text: "Analyze Lifewood's role in the global AI supply chain.", tool: 'research' },
                    { text: "Draft a partnership proposal for multi-lingual RLHF.", tool: 'canvas' },
                    { text: "How does 'Always On Never Off' influence our ESG goals?", tool: 'chat' }
                  ].map((s, i) => (
                    <button 
                      key={i}
                      onClick={() => { setSelectedTool(TOOLS.find(t => t.id === s.tool) || TOOLS[0]); setInput(s.text); }}
                      className="bg-white p-6 rounded-[2rem] border border-[#046241]/10 hover:border-[#FFB347] hover:shadow-xl transition-all text-left group"
                    >
                      <p className="text-sm font-bold text-[#133020] leading-snug">{s.text}</p>
                      <div className="mt-4 flex justify-end opacity-20 group-hover:opacity-100 transition-opacity">
                        <SparkleIcon />
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {currentConversation?.messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.sender === SenderType.USER ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2`}>
                <div className={`flex gap-4 max-w-[90%] md:max-w-[80%] ${msg.sender === SenderType.USER ? 'flex-row-reverse' : ''}`}>
                   {msg.sender === SenderType.AI && <div className="mt-1"><SparkleIcon className="w-6 h-6" /></div>}
                   <div className={`${msg.sender === SenderType.USER ? 'bg-[#FFB347] text-[#133020] px-6 py-3 rounded-[2rem] font-bold shadow-md border border-[#133020]/10' : 'text-[16px] leading-relaxed font-medium'}`}>
                      {msg.text}
                      {msg.generatedImageUrl && (
                        <div className="mt-6 rounded-3xl overflow-hidden shadow-2xl border-4 border-white max-w-lg">
                          <img src={msg.generatedImageUrl} className="w-full h-auto" />
                        </div>
                      )}
                      {msg.attachments?.map((at, i) => (
                        <div key={i} className="mt-4 max-w-xs rounded-xl overflow-hidden border border-[#046241]/10 shadow-inner">
                          {at.mimeType.startsWith('image/') ? <img src={at.data} className="w-full h-auto" /> : <div className="p-4 bg-white/40 text-xs font-black truncate">{at.fileName}</div>}
                        </div>
                      ))}
                   </div>
                </div>
              </div>
            ))}

            {isLoading && (
              <div className="flex gap-4 w-full animate-pulse">
                <SparkleIcon className="w-6 h-6" />
                <div className="flex-1 space-y-3 pt-3">
                  <div className="h-2 bg-[#046241]/10 rounded-full w-3/4"></div>
                  <div className="h-2 bg-[#046241]/10 rounded-full w-1/2"></div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
        </div>

        {/* Gemini-Style Input Bar with Lifewood Branding */}
        <div className="absolute bottom-0 left-0 right-0 p-6 flex justify-center bg-gradient-to-t from-[#f5eedb] via-[#f5eedb]/90 to-transparent">
          <div className="w-full max-w-3xl relative">

            {/* Tools Popover (Gemini Style) */}
            {showTools && (
              <div className="absolute bottom-full mb-4 left-0 w-64 bg-white border border-[#046241]/10 rounded-3xl shadow-2xl overflow-hidden z-50 animate-in slide-in-from-bottom-2 duration-200">
                <div className="p-2 space-y-1">
                  {TOOLS.map(t => (
                    <button
                      key={t.id}
                      onClick={() => { setSelectedTool(t); setShowTools(false); }}
                      className={`w-full flex items-center justify-between p-3 hover:bg-[#f5eedb] rounded-2xl transition-all ${selectedTool.id === t.id ? 'bg-[#f5eedb]' : ''}`}
                    >
                      <div className="flex items-center gap-3">
                        <span className="text-lg">{t.icon}</span>
                        <div>
                          <div className="text-xs font-black text-[#133020]">{t.name}</div>
                          <div className="text-[10px] text-[#133020]/40 font-bold uppercase">{t.description}</div>
                        </div>
                      </div>
                      {t.isLabs && <span className="text-[9px] font-black bg-[#FFB347] text-[#133020] px-2 py-0.5 rounded-full">LABS</span>}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Model Popover */}
            {showModels && (
              <div className="absolute bottom-full mb-4 right-0 w-48 bg-white border border-[#046241]/10 rounded-3xl shadow-2xl overflow-hidden z-50 animate-in slide-in-from-bottom-2">
                <div className="p-2 space-y-1">
                  {MODELS.map(m => (
                    <button
                      key={m.id}
                      onClick={() => { setSelectedModel(m); setShowModels(false); }}
                      className={`w-full text-left p-3 rounded-2xl transition-all ${selectedModel.id === m.id ? 'bg-[#046241] text-white' : 'hover:bg-[#f5eedb]'}`}
                    >
                      <div className="text-xs font-black uppercase">{m.name}</div>
                      <div className={`text-[10px] font-medium ${selectedModel.id === m.id ? 'text-white/60' : 'text-[#133020]/40'}`}>{m.description}</div>
                    </button>
                  ))}
                </div>
              </div>
            )}

            <div className="bg-white rounded-[2.5rem] p-2 flex items-end gap-1 shadow-2xl border border-[#046241]/10 transition-all focus-within:border-[#FFB347]">

              <button 
                onClick={() => setShowTools(!showTools)}
                className="p-4 text-[#046241] hover:bg-[#f5eedb] rounded-full transition-colors flex items-center gap-2"
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M12 4v16m8-8H4"/></svg>
                <span className="hidden md:inline text-[10px] font-black uppercase tracking-widest">Tools</span>
              </button>

              <div className="flex-1 flex flex-col py-1">
                <textarea
                  rows={1}
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyDown={handleKeyPress}
                  placeholder={selectedTool.id === 'image' ? "Describe the asset to generate..." : "Ask Lifewood Intelligence..."}
                  className="w-full bg-transparent border-none resize-none py-3 px-2 text-[15px] font-bold text-[#133020] placeholder-[#133020]/20 max-h-40 overflow-y-auto"
                />

                <div className="flex items-center gap-2 mb-1 px-2">
                  <div className="flex items-center gap-1.5 bg-[#f5eedb] px-3 py-1 rounded-full border border-[#046241]/5">
                    <span className="text-[14px] leading-none">{selectedTool.icon}</span>
                    <span className="text-[9px] font-black uppercase text-[#046241] tracking-tighter">{selectedTool.name}</span>
                  </div>
                  <button onClick={() => fileInputRef.current?.click()} className="p-1 hover:text-[#046241] text-[#133020]/20 transition-colors">
                     <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13"/></svg>
                  </button>
                  <input type="file" ref={fileInputRef} className="hidden" multiple onChange={handleFileUpload} />
