                      onClick={() => setShowModels(!showModels)}
                      className="px-4 py-2.5 hover:bg-[#133020]/5 rounded-xl text-[9px] font-google font-black uppercase tracking-widest text-[#133020]/30 transition-all border border-transparent active:scale-95"
                    >
                      {selectedModel.name}
                    </button>

                    <button 
                      disabled={isLoading || (!input.trim() && attachments.length === 0)}
