import { Message, SenderType, Conversation, FileData } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  // Persistence states
  const [conversations, setConversations] = useState<Conversation[]>(() => {
    const saved = localStorage.getItem('lifewood_v3_conversations');
    return saved ? JSON.parse(saved).map((c: any) => ({
      ...c,
      messages: c.messages.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
      createdAt: new Date(c.createdAt)
    })) : [];
  });

  const [systemInstruction, setSystemInstruction] = useState(() => 
    localStorage.getItem('lifewood_system_instruction') || 'You are Lifewood Intelligence, a proactive innovation partner focusing on AI data strategy and global logistics.'
  );

  const [theme, setTheme] = useState(() => localStorage.getItem('lifewood_theme') || 'classic');

  // UI states
  const [activeId, setActiveId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [attachments, setAttachments] = useState<FileData[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  const [showTools, setShowTools] = useState(false);
  const [selectedTool, setSelectedTool] = useState(TOOLS[0]);
  const [showModels, setShowModels] = useState(false);
  const [selectedModel, setSelectedModel] = useState(MODELS[0]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const currentConversation = conversations.find(c => c.id === activeId);

  // Persistence Effects
  useEffect(() => {
    localStorage.setItem('lifewood_v3_conversations', JSON.stringify(conversations));
  }, [conversations]);

  useEffect(() => {
    localStorage.setItem('lifewood_system_instruction', systemInstruction);
  }, [systemInstruction]);

  useEffect(() => {
    localStorage.setItem('lifewood_theme', theme);
  }, [theme]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [currentConversation?.messages, isLoading]);

  const startNewChat = () => {
    setActiveId(null);
    setInput('');
    setAttachments([]);
    setIsSidebarOpen(false);
    setSelectedTool(TOOLS[0]);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    Array.from(files).forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        setAttachments(prev => [...prev, {
          data: event.target?.result as string,
          mimeType: file.type,
          fileName: file.name
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleSend = async (overrideInput?: string) => {
    const finalInput = overrideInput || input;
    if ((!finalInput.trim() && attachments.length === 0) || isLoading) return;

    let targetConv = currentConversation;
    if (!targetConv) {
      const newId = Date.now().toString();
      targetConv = {
        id: newId,
        title: finalInput.slice(0, 30) || 'New Lifewood Session',
        messages: [],
        personaId: 'default',
        createdAt: new Date(),
      };
      setConversations(prev => [targetConv!, ...prev]);
      setActiveId(newId);
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      text: finalInput,
      sender: SenderType.USER,
      timestamp: new Date(),
      attachments: [...attachments],
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, userMsg] } : c
    ));

    setInput('');
    setAttachments([]);
    setIsLoading(true);

    const aiResponse = await getGeminiResponse(
      userMsg.text, 
      userMsg.attachments,
      selectedTool.id,
      selectedModel.id,
      systemInstruction
    );

    const aiMsg: Message = {
      id: (Date.now() + 1).toString(),
      text: aiResponse.text,
      generatedImageUrl: aiResponse.generatedImageUrl,
      sender: SenderType.AI,
      timestamp: new Date(),
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, aiMsg] } : c
    ));
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const deleteConversation = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setConversations(prev => prev.filter(c => c.id !== id));
    if (activeId === id) setActiveId(null);
  };

  const suggestedPrompts = [
    { 
      category: 'Strategic Vision', 
      label: 'ASEAN HUB', 
      text: "Conceptualize a logistics-first AI data hub in ASEAN.", 
      tool: 'image',
      icon: '🌐'
    },
    { 
      category: 'Technical Execution', 
      label: 'RLHF QUALITY', 
      text: "Compare data quality benchmarks for multi-lingual RLHF.", 
      tool: 'research',
      icon: '📊'
    },
    { 
      category: 'Brand Value', 
      label: 'ESG GOALS', 
      text: "How does Lifewood's 'Always On' model reduce ESG carbon footprint?", 
      tool: 'chat',
      icon: '🌱'
    }
  ];

  const getThemeClasses = () => {
    switch(theme) {
      case 'dark': return 'bg-[#133020] text-white';
      case 'high-contrast': return 'bg-black text-[#FFB347]';
      default: return 'bg-[#f5eedb] text-[#133020]';
    }
  };

  const getFooterBackground = () => {
    switch(theme) {
      case 'dark': return 'from-[#133020] via-[#133020] to-transparent';
      case 'high-contrast': return 'from-black via-black to-transparent';
      default: return 'from-[#f5eedb] via-[#f5eedb] to-transparent';
    }
  };

  return (
    <div className={`flex h-screen overflow-hidden transition-colors duration-500 ${getThemeClasses()}`}>

      {/* Sidebar - Higher Z-index to be on top of footer container */}
      <aside className={`fixed inset-y-0 left-0 z-[100] w-72 bg-[#133020] transition-transform duration-300 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 flex flex-col shadow-2xl`}>
        <div className="p-8 border-b border-white/5">
          <LifewoodLogo />
          <button 
            onClick={startNewChat}
            className="w-full mt-10 bg-[#046241] hover:bg-[#057a51] text-white py-4 rounded-xl flex items-center justify-center gap-2 font-google font-bold text-xs uppercase tracking-widest transition-all shadow-lg active:scale-95"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M12 4v16m8-8H4"/></svg>
            New Session
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-1 lifewood-scrollbar">
          <h3 className="text-white/30 text-[10px] font-google font-black uppercase tracking-[0.2em] px-4 py-4">Knowledge Base</h3>
          {conversations.map(conv => (
            <div 
              key={conv.id}
              onClick={() => { setActiveId(conv.id); setIsSidebarOpen(false); }}
              className={`group relative px-4 py-3.5 rounded-xl cursor-pointer transition-all flex items-center justify-between ${activeId === conv.id ? 'bg-[#046241] text-white shadow-xl' : 'hover:bg-white/5 text-white/60 hover:text-white'}`}
            >
              <div className="flex-1 min-w-0">
                <div className="text-[13px] font-semibold truncate leading-tight">{conv.title}</div>
                <div className="text-[9px] font-black uppercase tracking-tighter opacity-40 mt-1">{conv.createdAt.toLocaleDateString()}</div>
              </div>
              <button onClick={(e) => deleteConversation(e, conv.id)} className="opacity-0 group-hover:opacity-100 p-2 hover:bg-red-500/20 rounded-lg transition-all text-red-400">
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
              </button>
            </div>
          ))}
        </div>

        <div className="p-6 bg-black/20 border-t border-white/5 space-y-4">
          <button 
            onClick={() => setShowSettings(true)}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-white/5 text-white/40 hover:text-white transition-all text-[10px] font-google font-black uppercase tracking-widest"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37a1.724 1.724 0 002.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            Config
          </button>
          <div className="flex items-center justify-between text-[9px] text-white/20 font-google font-black uppercase tracking-[0.4em]">
            <span>Always On</span>
            <div className="w-1 h-1 rounded-full bg-[#FFB347] animate-pulse"></div>
          </div>
        </div>
      </aside>

      {/* Main Canvas - Dim on mobile when sidebar is open instead of hiding */}
      <main className={`flex-1 flex flex-col relative h-full transition-all duration-300 ${isSidebarOpen ? 'opacity-20 pointer-events-none lg:opacity-100 lg:pointer-events-auto' : 'opacity-100'}`}>
        <header className="absolute top-0 left-0 right-0 h-16 flex items-center justify-between px-6 z-40">
          <button onClick={() => setIsSidebarOpen(true)} className="p-3 bg-[#133020] text-white rounded-full shadow-xl lg:hidden">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M4 6h16M4 12h16m-7 6h7"/></svg>
          </button>
        </header>

        {/* Scrollable conversation text container */}
        <div className="flex-1 overflow-y-auto flex flex-col items-center lifewood-scrollbar pb-80 px-6 pt-12">
          <div className="w-full max-w-2xl space-y-14">

            {(!currentConversation || currentConversation.messages.length === 0) && (
              <div className="mt-16 space-y-12 animate-in fade-in duration-1000">
                <div className="text-center space-y-6">
                  <h2 className={`text-6xl font-google font-black tracking-tighter ${theme === 'classic' ? 'text-[#046241]' : 'text-[#FFB347]'}`}>
                    Innovation. <br/> <span className={theme === 'classic' ? 'text-[#FFB347]' : 'text-white'}>Verified.</span>
                  </h2>
                  <p className={`text-[11px] font-google font-black uppercase tracking-[0.6em] opacity-30`}>
                    Enterprise Intelligence Engine
                  </p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {suggestedPrompts.map((s, i) => (
                    <button 
                      key={i}
                      onClick={() => { setSelectedTool(TOOLS.find(t => t.id === s.tool) || TOOLS[0]); setInput(s.text); }}
                      className={`group p-6 rounded-[2rem] border transition-all text-left flex flex-col justify-between ${theme === 'classic' ? 'bg-white border-[#133020]/5 hover:border-[#FFB347]' : 'bg-white/5 border-white/10 hover:border-[#FFB347]'}`}
                    >
                      <div>
                        <div className="flex items-center justify-between mb-4">
                           <span className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${theme === 'classic' ? 'bg-[#133020]/5 text-[#133020]/60' : 'bg-white/10 text-white/60'}`}>
                             {s.category}
                           </span>
                           <span className="text-lg opacity-40 group-hover:opacity-100 transition-opacity">{s.icon}</span>
                        </div>
                        <h4 className="text-[10px] font-black uppercase tracking-tighter text-[#FFB347] mb-1">{s.label}</h4>
                        <p className={`text-[13px] font-bold leading-snug ${theme === 'classic' ? 'text-[#133020]' : 'text-white'}`}>{s.text}</p>
                      </div>
                      <div className="mt-6 flex justify-end">
                        <div className={`p-2 rounded-full transition-colors ${theme === 'classic' ? 'bg-[#f5eedb] group-hover:bg-[#FFB347]' : 'bg-white/10 group-hover:bg-[#FFB347]'}`}>
                           <SparkleIcon className="w-3 h-3 group-hover:fill-white" />
                        </div>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {currentConversation?.messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.sender === SenderType.USER ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-4 duration-500`}>
                <div className={`flex gap-6 w-full ${msg.sender === SenderType.USER ? 'flex-row-reverse' : ''}`}>
                   {msg.sender === SenderType.AI && (
                     <div className="mt-1 flex-shrink-0">
                       <div className="w-8 h-8 rounded-full bg-[#133020] flex items-center justify-center shadow-lg border border-white/10">
                          <SparkleIcon className="w-4 h-4" />
                       </div>
                     </div>
                   )}
                   <div className={`flex-1 ${msg.sender === SenderType.USER ? 'max-w-[85%]' : ''}`}>
                      <div className={`
                        ${msg.sender === SenderType.USER 
                          ? 'bg-[#FFB347] text-[#133020] px-6 py-4 rounded-3xl rounded-tr-none font-google font-bold text-[14px] shadow-lg border border-[#133020]/10' 
                          : `font-serif text-[18px] leading-relaxed tracking-wide opacity-90 ${theme === 'classic' ? 'text-[#133020]' : 'text-white/90'}`
                        }
                      `}>
                        {msg.text}
                        {msg.generatedImageUrl && (
                          <div className="mt-8 rounded-[2rem] overflow-hidden shadow-2xl border border-white/5 bg-black/10 p-2">
                            <img src={msg.generatedImageUrl} className="w-full h-auto rounded-[1.8rem]" />
                          </div>
                        )}
                      </div>
                      <div className={`mt-2 text-[9px] font-google font-black uppercase tracking-widest opacity-20 ${msg.sender === SenderType.USER ? 'text-right' : ''}`}>
                        {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </div>
                   </div>
                </div>
              </div>
            ))}

            {isLoading && (
              <div className="flex gap-6 w-full animate-pulse">
                <div className="w-8 h-8 rounded-full bg-white/10" />
                <div className="flex-1 space-y-4 pt-3">
                  <div className={`h-2 rounded-full w-3/4 ${theme === 'classic' ? 'bg-[#133020]/5' : 'bg-white/10'}`}></div>
                  <div className={`h-2 rounded-full w-1/2 ${theme === 'classic' ? 'bg-[#133020]/5' : 'bg-white/10'}`}></div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
        </div>

        {/* Architectural Interaction Rail Container - Reduced Z-index relative to Sidebar */}
        <div className={`fixed bottom-0 left-0 right-0 pt-32 pb-8 px-8 flex justify-center bg-gradient-to-t ${getFooterBackground()} z-[50] pointer-events-none`}>
          <div className="w-full max-w-3xl pointer-events-auto">

            {attachments.length > 0 && (
              <div className="flex flex-wrap gap-2 mb-4 px-2 animate-in slide-in-from-bottom-2">
                {attachments.map((file, idx) => (
                  <div key={idx} className="relative group bg-white p-1 rounded-xl shadow-lg border border-[#133020]/5 w-20 h-20">
                    <img src={file.data} className="w-full h-full object-cover rounded-lg" />
                    <button onClick={() => setAttachments(prev => prev.filter((_, i) => i !== idx))} className="absolute -top-2 -right-2 bg-[#133020] text-white p-1 rounded-full shadow-md scale-75">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12"/></svg>
                    </button>
                  </div>
                ))}
              </div>
            )}

            <div className={`rounded-[1.5rem] overflow-visible border-none shadow-2xl relative ${theme === 'classic' ? 'bg-white' : 'bg-[#046241]/95 backdrop-blur-2xl border border-white/5'}`}>

              {/* Interaction Rail */}
              <div className="p-3 flex items-center gap-2 relative">
                {/* Attachment Button */}
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className={`p-3.5 rounded-xl transition-all active:scale-95 ${theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#133020]/40' : 'hover:bg-white/5 text-white/40'}`}
                  title="Upload Attachments"
                >
                  <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M12 4v16m8-8H4"/></svg>
                </button>
                <input type="file" ref={fileInputRef} className="hidden" multiple onChange={handleFileUpload} />

                {/* Tools Popover Trigger */}
                <div className="relative">
                  <button 
                    onClick={() => { setShowTools(!showTools); setShowModels(false); }}
                    className={`flex items-center gap-2 px-4 py-3 rounded-xl transition-all font-google font-black text-[10px] uppercase tracking-widest active:scale-95 ${showTools ? 'bg-[#FFB347] text-[#133020]' : theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#133020]/60' : 'hover:bg-white/5 text-white/60'}`}
                  >
                    <SparkleIcon className={`w-3.5 h-3.5 ${showTools ? 'fill-[#133020]' : 'fill-current opacity-40'}`} />
                    <span className="hidden sm:inline">{selectedTool.name}</span>
                  </button>

                  {/* Tools Menu Popover */}
                  {showTools && (
                    <div className="absolute bottom-full left-0 mb-4 w-56 bg-[#133020] border border-white/10 rounded-2xl shadow-2xl overflow-hidden popover-enter z-[100]">
                      <div className="p-1 space-y-1">
                        {TOOLS.map(t => (
                          <button
                            key={t.id}
                            onClick={() => { setSelectedTool(t); setShowTools(false); }}
                            className={`w-full text-left p-4 rounded-xl transition-all ${selectedTool.id === t.id ? 'bg-[#046241] text-white shadow-inner' : 'hover:bg-white/5 text-white/60'}`}
                          >
                            <div className="flex items-center gap-2">
                               <span>{t.icon}</span>
                               <div className="text-[10px] font-google font-black uppercase tracking-widest">{t.name}</div>
                            </div>
                            <div className={`text-[9px] opacity-40 mt-1`}>{t.description}</div>
                          </button>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                <div className="flex-1 min-w-0">
                  <textarea
                    rows={1}
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={handleKeyPress}
                    placeholder={selectedTool.id === 'image' ? "Define asset parameters..." : "Synthesize new request..."}
                    className={`w-full bg-transparent border-none resize-none py-3.5 px-3 text-[15px] font-google font-bold placeholder-current opacity-60 focus:ring-0 focus:outline-none ring-0 outline-none max-h-40 no-scrollbar ${theme === 'classic' ? 'text-[#133020]' : 'text-white'}`}
                  />
                </div>

                <div className="flex items-center gap-1.5 pr-1">
                   {/* Model Popover Trigger */}
                   <div className="relative">
                     <button 
                        onClick={() => { setShowModels(!showModels); setShowTools(false); }}
                        className={`px-4 py-2.5 rounded-xl text-[9px] font-google font-black uppercase tracking-widest transition-all active:scale-95 ${theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#133020]/30' : 'hover:bg-white/5 text-white/30'}`}
                      >
                        {selectedModel.name}
                      </button>

                      {showModels && (
                        <div className="absolute bottom-full right-0 mb-4 w-56 bg-[#133020] border border-white/10 rounded-2xl shadow-2xl overflow-hidden popover-enter z-[100]">
                          <div className="p-1 space-y-1">
                            {MODELS.map(m => (
                              <button
                                key={m.id}
                                onClick={() => { setSelectedModel(m); setShowModels(false); }}
                                className={`w-full text-left p-4 rounded-xl transition-all ${selectedModel.id === m.id ? 'bg-[#046241] text-white shadow-inner' : 'hover:bg-white/5 text-white/60'}`}
                              >
                                <div className="text-[10px] font-google font-black uppercase tracking-widest">{m.name}</div>
                                <div className={`text-[9px] opacity-40 mt-1`}>{m.description}</div>
                              </button>
                            ))}
                          </div>
                        </div>
                      )}
                   </div>

                    {/* Send Button */}
                    <button 
                      disabled={isLoading || (!input.trim() && attachments.length === 0)}
                      onClick={() => handleSend()}
                      className={`p-4 rounded-xl transition-all shadow-xl active:scale-90 ${(!input.trim() && attachments.length === 0) ? 'bg-black/5 text-black/10 shadow-none' : 'bg-[#FFB347] text-[#133020]'}`}
                    >
                      <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M13.5 4.5L21 12m0 0l-7.5 7.5M21 12H3"/></svg>
                    </button>
                </div>
              </div>
            </div>

            <p className="text-[9px] font-google opacity-20 text-center mt-6 font-black uppercase tracking-[0.4em]">
              Intelligence Authenticated • Lifewood Core
            </p>
          </div>
        </div>
      </main>

      {/* Settings Modal */}
      {showSettings && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className="w-full max-w-xl bg-[#133020] rounded-[2.5rem] overflow-hidden shadow-2xl border border-white/10 text-white animate-in slide-in-from-bottom-4">
            <div className="p-8 border-b border-white/5 flex items-center justify-between">
              <div>
                <h3 className="text-xl font-google font-black uppercase tracking-tighter">Core Directives</h3>
                <p className="text-[10px] opacity-40 font-bold uppercase mt-1">Personalize your intelligence session</p>
              </div>
              <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M6 18L18 6M6 6l12 12"/></svg>
              </button>
            </div>

            <div className="p-8 space-y-8">
              {/* Theme Selector */}
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] opacity-40">Architectural Theme</label>
                <div className="grid grid-cols-3 gap-3">
                  {[
                    { id: 'classic', label: 'Beige', color: 'bg-[#f5eedb]' },
                    { id: 'dark', label: 'Emerald', color: 'bg-[#133020]' },
                    { id: 'high-contrast', label: 'Cyber', color: 'bg-black' },
                  ].map(t => (
                    <button 
                      key={t.id}
                      onClick={() => setTheme(t.id)}
                      className={`flex flex-col items-center gap-3 p-4 rounded-2xl border transition-all ${theme === t.id ? 'border-[#FFB347] bg-white/10 shadow-lg' : 'border-white/5 hover:bg-white/5'}`}
                    >
                      <div className={`w-8 h-8 rounded-full shadow-inner ${t.color} border border-white/10`}></div>
                      <span className="text-[10px] font-bold uppercase tracking-widest">{t.label}</span>
                    </button>
                  ))}
                </div>
              </div>

              {/* System Instructions */}
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] opacity-40">System Directives</label>
                <textarea 
                  value={systemInstruction}
                  onChange={(e) => setSystemInstruction(e.target.value)}
                  placeholder="Define how Lifewood Intelligence should behave..."
                  className="w-full h-32 bg-black/40 border border-white/10 rounded-2xl p-4 text-xs font-medium leading-relaxed resize-none focus:border-[#FFB347] transition-all focus:ring-0"
                />
              </div>
            </div>

            <div className="p-8 bg-black/20 flex justify-end">
              <button 
                onClick={() => setShowSettings(false)}
                className="bg-[#FFB347] text-[#133020] px-8 py-3 rounded-xl font-google font-black text-xs uppercase tracking-widest active:scale-95 transition-all shadow-lg"
              >
                Sync Configuration
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Side View Blur Overlay */}
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-[#133020]/40 backdrop-blur-sm z-[90] lg:hidden animate-in fade-in" onClick={() => setIsSidebarOpen(false)}></div>
      )}
    </div>
  );
};

export default App;

import React from 'react';

export const COLORS = {
  bg: '#f5eedb',
  sidebar: '#133020',
  accent: '#046241',
  saffron: '#FFB347',
  earthYellow: '#FFC370',
  white: '#ffffff',
  text: '#133020',
};

export const TOOLS = [
  { id: 'chat', name: 'General Chat', icon: '💬', description: 'Standard AI interaction' },
  { id: 'image', name: 'Generate Image', icon: '🖼️', description: 'Generate visual concepts' },
  { id: 'research', name: 'Deep Insight', icon: '🔍', description: 'Advanced research & data' },
  { id: 'canvas', name: 'Document Canvas', icon: '📝', description: 'Writing and structured data' },
  { id: 'maps', name: 'Global Logistics', icon: '📍', description: 'Mapping and location data', isLabs: true },
];

export const MODELS = [
  { id: 'gemini-3-flash-preview', name: 'Fast', description: 'Responsive and efficient' },
  { id: 'gemini-3-pro-preview', name: 'Pro', description: 'Advanced reasoning' },
];

export const LifewoodLogo: React.FC<{ className?: string }> = ({ className = "h-8" }) => (
  <div className={`flex items-center gap-2 ${className}`}>
    <svg viewBox="0 0 100 120" className="h-full fill-[#FFB347]">
      <path d="M50 0 L90 30 L90 90 L50 120 L10 90 L10 30 Z" />
    </svg>
    <span className="text-white font-bold text-2xl tracking-tighter">lifewood</span>
  </div>
);

export const SparkleIcon: React.FC<{ className?: string }> = ({ className = "w-5 h-5" }) => (
  <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" className={className}>
    <path d="M12 2L14.5 9.5L22 12L14.5 14.5L12 22L9.5 14.5L2 12L9.5 9.5L12 2Z" fill="#FFB347" />
  </svg>
);

import React, { useState, useRef, useEffect } from 'react';
import { LifewoodLogo, SparkleIcon, TOOLS, MODELS } from './constants';
import { Message, SenderType, Conversation, FileData } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  // Persistence states
  const [conversations, setConversations] = useState<Conversation[]>(() => {
    const saved = localStorage.getItem('lifewood_v3_conversations');
    return saved ? JSON.parse(saved).map((c: any) => ({
      ...c,
      messages: c.messages.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
      createdAt: new Date(c.createdAt)
    })) : [];
  });

  const [systemInstruction, setSystemInstruction] = useState(() => 
    localStorage.getItem('lifewood_system_instruction') || 'You are Lifewood Intelligence, a proactive innovation partner focusing on AI data strategy and global logistics.'
  );

  const [theme, setTheme] = useState(() => localStorage.getItem('lifewood_theme') || 'classic');

  // UI states
  const [activeId, setActiveId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [attachments, setAttachments] = useState<FileData[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  const [showTools, setShowTools] = useState(false);
  const [selectedTool, setSelectedTool] = useState(TOOLS[0]); // Default is General Chat
  const [showModels, setShowModels] = useState(false);
  const [selectedModel, setSelectedModel] = useState(MODELS[0]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const currentConversation = conversations.find(c => c.id === activeId);

  // Persistence Effects
  useEffect(() => {
    localStorage.setItem('lifewood_v3_conversations', JSON.stringify(conversations));
  }, [conversations]);

  useEffect(() => {
    localStorage.setItem('lifewood_system_instruction', systemInstruction);
  }, [systemInstruction]);

  useEffect(() => {
    localStorage.setItem('lifewood_theme', theme);
  }, [theme]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [currentConversation?.messages, isLoading]);

  const startNewChat = () => {
    setActiveId(null);
    setInput('');
    setAttachments([]);
    setIsSidebarOpen(false);
    setSelectedTool(TOOLS[0]);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    Array.from(files).forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        setAttachments(prev => [...prev, {
          data: event.target?.result as string,
          mimeType: file.type,
          fileName: file.name
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleSend = async (overrideInput?: string) => {
    const finalInput = overrideInput || input;
    if ((!finalInput.trim() && attachments.length === 0) || isLoading) return;

    let targetConv = currentConversation;
    if (!targetConv) {
      const newId = Date.now().toString();
      targetConv = {
        id: newId,
        title: finalInput.slice(0, 30) || 'New Lifewood Session',
        messages: [],
        personaId: 'default',
        createdAt: new Date(),
      };
      setConversations(prev => [targetConv!, ...prev]);
      setActiveId(newId);
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      text: finalInput,
      sender: SenderType.USER,
      timestamp: new Date(),
      attachments: [...attachments],
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, userMsg] } : c
    ));

    setInput('');
    setAttachments([]);
    setIsLoading(true);

    const aiResponse = await getGeminiResponse(
      userMsg.text, 
      userMsg.attachments,
      selectedTool.id,
      selectedModel.id,
      systemInstruction
    );

    const aiMsg: Message = {
      id: (Date.now() + 1).toString(),
      text: aiResponse.text,
      generatedImageUrl: aiResponse.generatedImageUrl,
      sender: SenderType.AI,
      timestamp: new Date(),
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, aiMsg] } : c
    ));
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const deleteConversation = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setConversations(prev => prev.filter(c => c.id !== id));
    if (activeId === id) setActiveId(null);
  };

  const suggestedPrompts = [
    { 
      category: 'Strategic Vision', 
      label: 'ASEAN HUB', 
      text: "Conceptualize a logistics-first AI data hub in ASEAN.", 
      tool: 'image',
      icon: '🌐'
    },
    { 
      category: 'Technical Execution', 
      label: 'RLHF QUALITY', 
      text: "Compare data quality benchmarks for multi-lingual RLHF.", 
      tool: 'research',
      icon: '📊'
    },
    { 
      category: 'Brand Value', 
      label: 'ESG GOALS', 
      text: "How does Lifewood's 'Always On' model reduce ESG carbon footprint?", 
      tool: 'chat',
      icon: '🌱'
    }
  ];

  const getThemeClasses = () => {
    switch(theme) {
      case 'dark': return 'bg-[#133020] text-white';
      case 'high-contrast': return 'bg-black text-[#FFB347]';
      default: return 'bg-[#f5eedb] text-[#133020]';
    }
  };

  const getFooterBackground = () => {
    switch(theme) {
      case 'dark': return 'from-[#133020] via-[#133020] to-transparent';
      case 'high-contrast': return 'from-black via-black to-transparent';
      default: return 'from-[#f5eedb] via-[#f5eedb] to-transparent';
    }
  };

  return (
    <div className={`flex h-screen overflow-hidden transition-colors duration-500 ${getThemeClasses()}`}>

      {/* Sidebar - Higher Z-index to be on top of footer container */}
      <aside className={`fixed inset-y-0 left-0 z-[100] w-72 bg-[#133020] transition-transform duration-300 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 flex flex-col shadow-2xl`}>
        <div className="p-8 border-b border-white/5">
          <LifewoodLogo />
          <button 
            onClick={startNewChat}
            className="w-full mt-10 bg-[#046241] hover:bg-[#057a51] text-white py-4 rounded-xl flex items-center justify-center gap-2 font-google font-bold text-xs uppercase tracking-widest transition-all shadow-lg active:scale-95"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M12 4v16m8-8H4"/></svg>
            New Session
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-1 lifewood-scrollbar">
          <h3 className="text-white/30 text-[10px] font-google font-black uppercase tracking-[0.2em] px-4 py-4">Knowledge Base</h3>
          {conversations.map(conv => (
            <div 
              key={conv.id}
              onClick={() => { setActiveId(conv.id); setIsSidebarOpen(false); }}
              className={`group relative px-4 py-3.5 rounded-xl cursor-pointer transition-all flex items-center justify-between ${activeId === conv.id ? 'bg-[#046241] text-white shadow-xl' : 'hover:bg-white/5 text-white/60 hover:text-white'}`}
            >
              <div className="flex-1 min-w-0">
                <div className="text-[13px] font-semibold truncate leading-tight">{conv.title}</div>
                <div className="text-[9px] font-black uppercase tracking-tighter opacity-40 mt-1">{conv.createdAt.toLocaleDateString()}</div>
              </div>
              <button onClick={(e) => deleteConversation(e, conv.id)} className="opacity-0 group-hover:opacity-100 p-2 hover:bg-red-500/20 rounded-lg transition-all text-red-400">
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
              </button>
            </div>
          ))}
        </div>

        <div className="p-6 bg-black/20 border-t border-white/5 space-y-4">
          <button 
            onClick={() => setShowSettings(true)}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-white/5 text-white/40 hover:text-white transition-all text-[10px] font-google font-black uppercase tracking-widest"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37a1.724 1.724 0 002.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            Config
          </button>
          <div className="flex items-center justify-between text-[9px] text-white/20 font-google font-black uppercase tracking-[0.4em]">
            <span>Always On</span>
            <div className="w-1 h-1 rounded-full bg-[#FFB347] animate-pulse"></div>
          </div>
        </div>
      </aside>

      {/* Main Canvas - Dim on mobile when sidebar is open instead of hiding */}
      <main className={`flex-1 flex flex-col relative h-full transition-all duration-300 ${isSidebarOpen ? 'opacity-20 pointer-events-none lg:opacity-100 lg:pointer-events-auto' : 'opacity-100'}`}>
        <header className="absolute top-0 left-0 right-0 h-16 flex items-center justify-between px-6 z-40">
          <button onClick={() => setIsSidebarOpen(true)} className="p-3 bg-[#133020] text-white rounded-full shadow-xl lg:hidden">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M4 6h16M4 12h16m-7 6h7"/></svg>
          </button>
        </header>

        {/* Scrollable conversation text container */}
        <div className="flex-1 overflow-y-auto flex flex-col items-center lifewood-scrollbar pb-80 px-6 pt-12">
          <div className="w-full max-w-2xl space-y-14">

            {(!currentConversation || currentConversation.messages.length === 0) && (
              <div className="mt-16 space-y-12 animate-in fade-in duration-1000">
                <div className="text-center space-y-6">
                  <h2 className={`text-6xl font-google font-black tracking-tighter ${theme === 'classic' ? 'text-[#046241]' : 'text-[#FFB347]'}`}>
                    Innovation. <br/> <span className={theme === 'classic' ? 'text-[#FFB347]' : 'text-white'}>Verified.</span>
                  </h2>
                  <p className={`text-[11px] font-google font-black uppercase tracking-[0.6em] opacity-30`}>
                    Enterprise Intelligence Engine
                  </p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {suggestedPrompts.map((s, i) => (
                    <button 
                      key={i}
                      onClick={() => { setSelectedTool(TOOLS.find(t => t.id === s.tool) || TOOLS[0]); setInput(s.text); }}
                      className={`group p-6 rounded-[2rem] border transition-all text-left flex flex-col justify-between ${theme === 'classic' ? 'bg-white border-[#133020]/5 hover:border-[#FFB347]' : 'bg-white/5 border-white/10 hover:border-[#FFB347]'}`}
                    >
                      <div>
                        <div className="flex items-center justify-between mb-4">
                           <span className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${theme === 'classic' ? 'bg-[#133020]/5 text-[#133020]/60' : 'bg-white/10 text-white/60'}`}>
                             {s.category}
                           </span>
                           <span className="text-lg opacity-40 group-hover:opacity-100 transition-opacity">{s.icon}</span>
                        </div>
                        <h4 className="text-[10px] font-black uppercase tracking-tighter text-[#FFB347] mb-1">{s.label}</h4>
                        <p className={`text-[13px] font-bold leading-snug ${theme === 'classic' ? 'text-[#133020]' : 'text-white'}`}>{s.text}</p>
                      </div>
                      <div className="mt-6 flex justify-end">
                        <div className={`p-2 rounded-full transition-colors ${theme === 'classic' ? 'bg-[#f5eedb] group-hover:bg-[#FFB347]' : 'bg-white/10 group-hover:bg-[#FFB347]'}`}>
                           <SparkleIcon className="w-3 h-3 group-hover:fill-white" />
                        </div>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {currentConversation?.messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.sender === SenderType.USER ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-4 duration-500`}>
                <div className={`flex gap-6 w-full ${msg.sender === SenderType.USER ? 'flex-row-reverse' : ''}`}>
                   {msg.sender === SenderType.AI && (
                     <div className="mt-1 flex-shrink-0">
                       <div className="w-8 h-8 rounded-full bg-[#133020] flex items-center justify-center shadow-lg border border-white/10">
                          <SparkleIcon className="w-4 h-4" />
                       </div>
                     </div>
                   )}
                   <div className={`flex-1 ${msg.sender === SenderType.USER ? 'max-w-[85%]' : ''}`}>
                      <div className={`
                        ${msg.sender === SenderType.USER 
                          ? 'bg-[#FFB347] text-[#133020] px-6 py-4 rounded-3xl rounded-tr-none font-google font-bold text-[14px] shadow-lg border border-[#133020]/10' 
                          : `font-serif text-[18px] leading-relaxed tracking-wide opacity-90 ${theme === 'classic' ? 'text-[#133020]' : 'text-white/90'}`
                        }
                      `}>
                        {msg.text}
                        {msg.generatedImageUrl && (
                          <div className="mt-8 rounded-[2rem] overflow-hidden shadow-2xl border border-white/5 bg-black/10 p-2">
                            <img src={msg.generatedImageUrl} className="w-full h-auto rounded-[1.8rem]" />
                          </div>
                        )}
                      </div>
                      <div className={`mt-2 text-[9px] font-google font-black uppercase tracking-widest opacity-20 ${msg.sender === SenderType.USER ? 'text-right' : ''}`}>
                        {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </div>
                   </div>
                </div>
              </div>
            ))}

            {isLoading && (
              <div className="flex gap-6 w-full animate-pulse">
                <div className="w-8 h-8 rounded-full bg-white/10" />
                <div className="flex-1 space-y-4 pt-3">
                  <div className={`h-2 rounded-full w-3/4 ${theme === 'classic' ? 'bg-[#133020]/5' : 'bg-white/10'}`}></div>
                  <div className={`h-2 rounded-full w-1/2 ${theme === 'classic' ? 'bg-[#133020]/5' : 'bg-white/10'}`}></div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
        </div>

        {/* Architectural Interaction Rail Container - Reduced Z-index relative to Sidebar */}
        <div className={`fixed bottom-0 left-0 right-0 pt-32 pb-8 px-8 flex justify-center bg-gradient-to-t ${getFooterBackground()} z-[50] pointer-events-none`}>
          <div className="w-full max-w-3xl pointer-events-auto">

            {attachments.length > 0 && (
              <div className="flex flex-wrap gap-2 mb-4 px-2 animate-in slide-in-from-bottom-2">
                {attachments.map((file, idx) => (
                  <div key={idx} className="relative group bg-white p-1 rounded-xl shadow-lg border border-[#133020]/5 w-20 h-20">
                    <img src={file.data} className="w-full h-full object-cover rounded-lg" />
                    <button onClick={() => setAttachments(prev => prev.filter((_, i) => i !== idx))} className="absolute -top-2 -right-2 bg-[#133020] text-white p-1 rounded-full shadow-md scale-75">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12"/></svg>
                    </button>
                  </div>
                ))}
              </div>
            )}

            <div className={`rounded-[1.5rem] overflow-visible border-none shadow-2xl relative ${theme === 'classic' ? 'bg-white' : 'bg-[#046241]/95 backdrop-blur-2xl border border-white/5'}`}>

              {/* Interaction Rail */}
              <div className="p-3 flex items-center gap-2 relative">
                {/* Attachment Button */}
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className={`p-3.5 rounded-xl transition-all active:scale-95 ${theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#133020]/40' : 'hover:bg-white/5 text-white/40'}`}
                  title="Upload Attachments"
                >
                  <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M12 4v16m8-8H4"/></svg>
                </button>
                <input type="file" ref={fileInputRef} className="hidden" multiple onChange={handleFileUpload} />

                {/* Tools Popover Trigger */}
                <div className="relative">
                  <button 
                    onClick={() => { setShowTools(!showTools); setShowModels(false); }}
                    className={`flex items-center gap-2 px-4 py-3 rounded-xl transition-all font-google font-black text-[10px] uppercase tracking-widest active:scale-95 ${showTools ? 'bg-[#FFB347] text-[#133020]' : theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#133020]/60' : 'hover:bg-white/5 text-white/60'}`}
                  >
                    <SparkleIcon className={`w-3.5 h-3.5 ${showTools ? 'fill-[#133020]' : 'fill-current opacity-40'}`} />
                    <span className="hidden sm:inline">{selectedTool.name}</span>
                  </button>

                  {/* Tools Menu Popover */}
                  {showTools && (
                    <div className="absolute bottom-full left-0 mb-4 w-56 bg-[#133020] border border-white/10 rounded-2xl shadow-2xl overflow-hidden popover-enter z-[100]">
                      <div className="p-1 space-y-1">
                        {TOOLS.map(t => (
                          <button
                            key={t.id}
                            onClick={() => { setSelectedTool(t); setShowTools(false); }}
                            className={`w-full text-left p-4 rounded-xl transition-all ${selectedTool.id === t.id ? 'bg-[#046241] text-white shadow-inner' : 'hover:bg-white/5 text-white/60'}`}
                          >
                            <div className="flex items-center gap-2">
                               <span>{t.icon}</span>
                               <div className="text-[10px] font-google font-black uppercase tracking-widest">{t.name}</div>
                            </div>
                            <div className={`text-[9px] opacity-40 mt-1`}>{t.description}</div>
                          </button>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                <div className="flex-1 min-w-0">
                  <textarea
                    rows={1}
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={handleKeyPress}
                    placeholder={selectedTool.id === 'image' ? "Define visual parameters..." : "Synthesize new request..."}
                    className={`w-full bg-transparent border-none resize-none py-3.5 px-3 text-[15px] font-google font-bold placeholder-current opacity-60 focus:ring-0 focus:outline-none ring-0 outline-none max-h-40 no-scrollbar ${theme === 'classic' ? 'text-[#133020]' : 'text-white'}`}
                  />
                </div>

                <div className="flex items-center gap-1.5 pr-1">
                   {/* Model Popover Trigger */}
                   <div className="relative">
                     <button 
                        onClick={() => { setShowModels(!showModels); setShowTools(false); }}
                        className={`px-4 py-2.5 rounded-xl text-[9px] font-google font-black uppercase tracking-widest transition-all active:scale-95 ${theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#133020]/30' : 'hover:bg-white/5 text-white/30'}`}
                      >
                        {selectedModel.name}
                      </button>

                      {showModels && (
                        <div className="absolute bottom-full right-0 mb-4 w-56 bg-[#133020] border border-white/10 rounded-2xl shadow-2xl overflow-hidden popover-enter z-[100]">
                          <div className="p-1 space-y-1">
                            {MODELS.map(m => (
                              <button
                                key={m.id}
                                onClick={() => { setSelectedModel(m); setShowModels(false); }}
                                className={`w-full text-left p-4 rounded-xl transition-all ${selectedModel.id === m.id ? 'bg-[#046241] text-white shadow-inner' : 'hover:bg-white/5 text-white/60'}`}
                              >
                                <div className="text-[10px] font-google font-black uppercase tracking-widest">{m.name}</div>
                                <div className={`text-[9px] opacity-40 mt-1`}>{m.description}</div>
                              </button>
                            ))}
                          </div>
                        </div>
                      )}
                   </div>

                    {/* Send Button */}
                    <button 
                      disabled={isLoading || (!input.trim() && attachments.length === 0)}
                      onClick={() => handleSend()}
                      className={`p-4 rounded-xl transition-all shadow-xl active:scale-90 ${(!input.trim() && attachments.length === 0) ? 'bg-black/5 text-black/10 shadow-none' : 'bg-[#FFB347] text-[#133020]'}`}
                    >
                      <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M13.5 4.5L21 12m0 0l-7.5 7.5M21 12H3"/></svg>
                    </button>
                </div>
              </div>
            </div>

            <p className="text-[9px] font-google opacity-20 text-center mt-6 font-black uppercase tracking-[0.4em]">
              Intelligence Authenticated • Lifewood Core
            </p>
          </div>
        </div>
      </main>

      {/* Settings Modal */}
      {showSettings && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className="w-full max-w-xl bg-[#133020] rounded-[2.5rem] overflow-hidden shadow-2xl border border-white/10 text-white animate-in slide-in-from-bottom-4">
            <div className="p-8 border-b border-white/5 flex items-center justify-between">
              <div>
                <h3 className="text-xl font-google font-black uppercase tracking-tighter">Core Directives</h3>
                <p className="text-[10px] opacity-40 font-bold uppercase mt-1">Personalize your intelligence session</p>
              </div>
              <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M6 18L18 6M6 6l12 12"/></svg>
              </button>
            </div>

            <div className="p-8 space-y-8">
              {/* Theme Selector */}
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] opacity-40">Architectural Theme</label>
                <div className="grid grid-cols-3 gap-3">
                  {[
                    { id: 'classic', label: 'Beige', color: 'bg-[#f5eedb]' },
                    { id: 'dark', label: 'Emerald', color: 'bg-[#133020]' },
                    { id: 'high-contrast', label: 'Cyber', color: 'bg-black' },
                  ].map(t => (
                    <button 
                      key={t.id}
                      onClick={() => setTheme(t.id)}
                      className={`flex flex-col items-center gap-3 p-4 rounded-2xl border transition-all ${theme === t.id ? 'border-[#FFB347] bg-white/10 shadow-lg' : 'border-white/5 hover:bg-white/5'}`}
                    >
                      <div className={`w-8 h-8 rounded-full shadow-inner ${t.color} border border-white/10`}></div>
                      <span className="text-[10px] font-bold uppercase tracking-widest">{t.label}</span>
                    </button>
                  ))}
                </div>
              </div>

              {/* System Instructions */}
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] opacity-40">System Directives</label>
                <textarea 
                  value={systemInstruction}
                  onChange={(e) => setSystemInstruction(e.target.value)}
                  placeholder="Define how Lifewood Intelligence should behave..."
                  className="w-full h-32 bg-black/40 border border-white/10 rounded-2xl p-4 text-xs font-medium leading-relaxed resize-none focus:border-[#FFB347] transition-all focus:ring-0"
                />
              </div>
            </div>

            <div className="p-8 bg-black/20 flex justify-end">
              <button 
                onClick={() => setShowSettings(false)}
                className="bg-[#FFB347] text-[#133020] px-8 py-3 rounded-xl font-google font-black text-xs uppercase tracking-widest active:scale-95 transition-all shadow-lg"
              >
                Sync Configuration
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Side View Blur Overlay */}
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-[#133020]/40 backdrop-blur-sm z-[90] lg:hidden animate-in fade-in" onClick={() => setIsSidebarOpen(false)}></div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { LifewoodLogo, SparkleIcon, TOOLS, MODELS } from './constants';
import { Message, SenderType, Conversation, FileData } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  // Persistence states
  const [conversations, setConversations] = useState<Conversation[]>(() => {
    const saved = localStorage.getItem('lifewood_v3_conversations');
    return saved ? JSON.parse(saved).map((c: any) => ({
      ...c,
      messages: c.messages.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
      createdAt: new Date(c.createdAt)
    })) : [];
  });

  const [systemInstruction, setSystemInstruction] = useState(() => 
    localStorage.getItem('lifewood_system_instruction') || 'You are Lifewood Intelligence, a proactive innovation partner focusing on AI data strategy and global logistics.'
  );

  const [theme, setTheme] = useState(() => localStorage.getItem('lifewood_theme') || 'classic');

  // UI states
  const [activeId, setActiveId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [attachments, setAttachments] = useState<FileData[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  const [showTools, setShowTools] = useState(false);
  const [selectedTool, setSelectedTool] = useState(TOOLS[0]); // Default is General Chat
  const [showModels, setShowModels] = useState(false);
  const [selectedModel, setSelectedModel] = useState(MODELS[0]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const currentConversation = conversations.find(c => c.id === activeId);

  // Persistence Effects
  useEffect(() => {
    localStorage.setItem('lifewood_v3_conversations', JSON.stringify(conversations));
  }, [conversations]);

  useEffect(() => {
    localStorage.setItem('lifewood_system_instruction', systemInstruction);
  }, [systemInstruction]);

  useEffect(() => {
    localStorage.setItem('lifewood_theme', theme);
  }, [theme]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [currentConversation?.messages, isLoading]);

  const startNewChat = () => {
    setActiveId(null);
    setInput('');
    setAttachments([]);
    setIsSidebarOpen(false);
    setSelectedTool(TOOLS[0]);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    Array.from(files).forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        setAttachments(prev => [...prev, {
          data: event.target?.result as string,
          mimeType: file.type,
          fileName: file.name
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleSend = async (overrideInput?: string) => {
    const finalInput = overrideInput || input;
    if ((!finalInput.trim() && attachments.length === 0) || isLoading) return;

    let targetConv = currentConversation;
    if (!targetConv) {
      const newId = Date.now().toString();
      targetConv = {
        id: newId,
        title: finalInput.slice(0, 30) || 'New Lifewood Session',
        messages: [],
        personaId: 'default',
        createdAt: new Date(),
      };
      setConversations(prev => [targetConv!, ...prev]);
      setActiveId(newId);
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      text: finalInput,
      sender: SenderType.USER,
      timestamp: new Date(),
      attachments: [...attachments],
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, userMsg] } : c
    ));

    setInput('');
    setAttachments([]);
    setIsLoading(true);

    const aiResponse = await getGeminiResponse(
      userMsg.text, 
      userMsg.attachments,
      selectedTool.id,
      selectedModel.id,
      systemInstruction
    );

    const aiMsg: Message = {
      id: (Date.now() + 1).toString(),
      text: aiResponse.text,
      generatedImageUrl: aiResponse.generatedImageUrl,
      sender: SenderType.AI,
      timestamp: new Date(),
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, aiMsg] } : c
    ));
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const deleteConversation = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setConversations(prev => prev.filter(c => c.id !== id));
    if (activeId === id) setActiveId(null);
  };

  const suggestedPrompts = [
    { 
      category: 'Strategic Vision', 
      label: 'ASEAN HUB', 
      text: "Conceptualize a logistics-first AI data hub in ASEAN.", 
      tool: 'image',
      icon: '🌐'
    },
    { 
      category: 'Technical Execution', 
      label: 'RLHF QUALITY', 
      text: "Compare data quality benchmarks for multi-lingual RLHF.", 
      tool: 'research',
      icon: '📊'
    },
    { 
      category: 'Brand Value', 
      label: 'ESG GOALS', 
      text: "How does Lifewood's 'Always On' model reduce ESG carbon footprint?", 
      tool: 'chat',
      icon: '🌱'
    }
  ];

  const getThemeClasses = () => {
    switch(theme) {
      case 'dark': return 'bg-[#133020] text-white';
      case 'high-contrast': return 'bg-black text-[#FFB347]';
      default: return 'bg-[#f5eedb] text-[#133020]';
    }
  };

  const getFooterBackground = () => {
    switch(theme) {
      case 'dark': return 'from-[#133020] via-[#133020] to-transparent';
      case 'high-contrast': return 'from-black via-black to-transparent';
      default: return 'from-[#f5eedb] via-[#f5eedb] to-transparent';
    }
  };

  return (
    <div className={`flex h-screen overflow-hidden transition-colors duration-500 ${getThemeClasses()}`}>

      {/* Sidebar - Higher Z-index to be on top of footer container */}
      <aside className={`fixed inset-y-0 left-0 z-[100] w-72 bg-[#133020] transition-transform duration-300 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 flex flex-col shadow-2xl`}>
        <div className="p-8 border-b border-white/5">
          <LifewoodLogo />
          <button 
            onClick={startNewChat}
            className="w-full mt-10 bg-[#046241] hover:bg-[#057a51] text-white py-4 rounded-xl flex items-center justify-center gap-2 font-google font-bold text-xs uppercase tracking-widest transition-all shadow-lg active:scale-95"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M12 4v16m8-8H4"/></svg>
            New Session
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-1 lifewood-scrollbar">
          <h3 className="text-white/30 text-[10px] font-google font-black uppercase tracking-[0.2em] px-4 py-4">Knowledge Base</h3>
          {conversations.map(conv => (
            <div 
              key={conv.id}
              onClick={() => { setActiveId(conv.id); setIsSidebarOpen(false); }}
              className={`group relative px-4 py-3.5 rounded-xl cursor-pointer transition-all flex items-center justify-between ${activeId === conv.id ? 'bg-[#046241] text-white shadow-xl' : 'hover:bg-white/5 text-white/60 hover:text-white'}`}
            >
              <div className="flex-1 min-w-0">
                <div className="text-[13px] font-semibold truncate leading-tight">{conv.title}</div>
                <div className="text-[9px] font-black uppercase tracking-tighter opacity-40 mt-1">{conv.createdAt.toLocaleDateString()}</div>
              </div>
              <button onClick={(e) => deleteConversation(e, conv.id)} className="opacity-0 group-hover:opacity-100 p-2 hover:bg-red-500/20 rounded-lg transition-all text-red-400">
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
              </button>
            </div>
          ))}
        </div>

        <div className="p-6 bg-black/20 border-t border-white/5 space-y-4">
          <button 
            onClick={() => setShowSettings(true)}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-white/5 text-white/40 hover:text-white transition-all text-[10px] font-google font-black uppercase tracking-widest"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37a1.724 1.724 0 002.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            Config
          </button>
          <div className="flex items-center justify-between text-[9px] text-white/20 font-google font-black uppercase tracking-[0.4em]">
            <span>Always On</span>
            <div className="w-1 h-1 rounded-full bg-[#FFB347] animate-pulse"></div>
          </div>
        </div>
      </aside>

      {/* Main Canvas - Dim on mobile when sidebar is open instead of hiding */}
      <main className={`flex-1 flex flex-col relative h-full transition-all duration-300 ${isSidebarOpen ? 'opacity-20 pointer-events-none lg:opacity-100 lg:pointer-events-auto' : 'opacity-100'}`}>
        <header className="absolute top-0 left-0 right-0 h-16 flex items-center justify-between px-6 z-40">
          <button onClick={() => setIsSidebarOpen(true)} className="p-3 bg-[#133020] text-white rounded-full shadow-xl lg:hidden">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M4 6h16M4 12h16m-7 6h7"/></svg>
          </button>
        </header>

        {/* Scrollable conversation text container - Aligned to the RIGHT for asymmetry */}
        <div className="flex-1 overflow-y-auto flex flex-col items-end lifewood-scrollbar pb-80 px-6 pt-12 lg:pr-12 xl:pr-24">
          <div className="w-full max-w-2xl space-y-14">

            {(!currentConversation || currentConversation.messages.length === 0) && (
              <div className="mt-16 space-y-12 animate-in fade-in duration-1000">
                <div className="text-right space-y-6">
                  <h2 className={`text-6xl font-google font-black tracking-tighter ${theme === 'classic' ? 'text-[#046241]' : 'text-[#FFB347]'}`}>
                    Innovation. <br/> <span className={theme === 'classic' ? 'text-[#FFB347]' : 'text-white'}>Verified.</span>
                  </h2>
                  <p className={`text-[11px] font-google font-black uppercase tracking-[0.6em] opacity-30`}>
                    Enterprise Intelligence Engine
                  </p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {suggestedPrompts.map((s, i) => (
                    <button 
                      key={i}
                      onClick={() => { setSelectedTool(TOOLS.find(t => t.id === s.tool) || TOOLS[0]); setInput(s.text); }}
                      className={`group p-6 rounded-[2rem] border transition-all text-left flex flex-col justify-between ${theme === 'classic' ? 'bg-white border-[#133020]/5 hover:border-[#FFB347]' : 'bg-white/5 border-white/10 hover:border-[#FFB347]'}`}
                    >
                      <div>
                        <div className="flex items-center justify-between mb-4">
                           <span className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${theme === 'classic' ? 'bg-[#133020]/5 text-[#133020]/60' : 'bg-white/10 text-white/60'}`}>
                             {s.category}
                           </span>
                           <span className="text-lg opacity-40 group-hover:opacity-100 transition-opacity">{s.icon}</span>
                        </div>
                        <h4 className="text-[10px] font-black uppercase tracking-tighter text-[#FFB347] mb-1">{s.label}</h4>
                        <p className={`text-[13px] font-bold leading-snug ${theme === 'classic' ? 'text-[#133020]' : 'text-white'}`}>{s.text}</p>
                      </div>
                      <div className="mt-6 flex justify-end">
                        <div className={`p-2 rounded-full transition-colors ${theme === 'classic' ? 'bg-[#f5eedb] group-hover:bg-[#FFB347]' : 'bg-white/10 group-hover:bg-[#FFB347]'}`}>
                           <SparkleIcon className="w-3 h-3 group-hover:fill-white" />
                        </div>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {currentConversation?.messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.sender === SenderType.USER ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-4 duration-500`}>
                <div className={`flex gap-6 w-full ${msg.sender === SenderType.USER ? 'flex-row-reverse' : ''}`}>
                   {msg.sender === SenderType.AI && (
                     <div className="mt-1 flex-shrink-0">
                       <div className="w-8 h-8 rounded-full bg-[#133020] flex items-center justify-center shadow-lg border border-white/10">
                          <SparkleIcon className="w-4 h-4" />
                       </div>
                     </div>
                   )}
                   <div className={`flex-1 ${msg.sender === SenderType.USER ? 'max-w-[85%]' : ''}`}>
                      <div className={`
                        ${msg.sender === SenderType.USER 
                          ? 'bg-[#FFB347] text-[#133020] px-6 py-4 rounded-3xl rounded-tr-none font-google font-bold text-[14px] shadow-lg border border-[#133020]/10' 
                          : `font-serif text-[18px] leading-relaxed tracking-wide opacity-90 ${theme === 'classic' ? 'text-[#133020]' : 'text-white/90'}`
                        }
                      `}>
                        {msg.text}
                        {msg.generatedImageUrl && (
                          <div className="mt-8 rounded-[2rem] overflow-hidden shadow-2xl border border-white/5 bg-black/10 p-2">
                            <img src={msg.generatedImageUrl} className="w-full h-auto rounded-[1.8rem]" />
                          </div>
                        )}
                      </div>
                      <div className={`mt-2 text-[9px] font-google font-black uppercase tracking-widest opacity-20 ${msg.sender === SenderType.USER ? 'text-right' : ''}`}>
                        {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </div>
                   </div>
                </div>
              </div>
            ))}

            {isLoading && (
              <div className="flex gap-6 w-full animate-pulse">
                <div className="w-8 h-8 rounded-full bg-white/10" />
                <div className="flex-1 space-y-4 pt-3">
                  <div className={`h-2 rounded-full w-3/4 ${theme === 'classic' ? 'bg-[#133020]/5' : 'bg-white/10'}`}></div>
                  <div className={`h-2 rounded-full w-1/2 ${theme === 'classic' ? 'bg-[#133020]/5' : 'bg-white/10'}`}></div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
        </div>

        {/* Architectural Interaction Rail Container - Positioned to the right on large screens */}
        <div className={`fixed bottom-0 left-0 right-0 pt-32 pb-8 px-8 flex justify-center lg:justify-end bg-gradient-to-t ${getFooterBackground()} z-[50] pointer-events-none`}>
          <div className="w-full max-w-3xl lg:mr-12 xl:mr-24 pointer-events-auto">

            {attachments.length > 0 && (
              <div className="flex flex-wrap gap-2 mb-4 px-2 animate-in slide-in-from-bottom-2">
                {attachments.map((file, idx) => (
                  <div key={idx} className="relative group bg-white p-1 rounded-xl shadow-lg border border-[#133020]/5 w-20 h-20">
                    <img src={file.data} className="w-full h-full object-cover rounded-lg" />
                    <button onClick={() => setAttachments(prev => prev.filter((_, i) => i !== idx))} className="absolute -top-2 -right-2 bg-[#133020] text-white p-1 rounded-full shadow-md scale-75">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12"/></svg>
                    </button>
                  </div>
                ))}
              </div>
            )}

            <div className={`rounded-[1.5rem] overflow-visible border-none shadow-2xl relative ${theme === 'classic' ? 'bg-white' : 'bg-[#046241]/95 backdrop-blur-2xl border border-white/5'}`}>

              {/* Interaction Rail */}
              <div className="p-3 flex items-center gap-2 relative">
                {/* Attachment Button */}
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className={`p-3.5 rounded-xl transition-all active:scale-95 ${theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#133020]/40' : 'hover:bg-white/5 text-white/40'}`}
                  title="Upload Attachments"
                >
                  <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M12 4v16m8-8H4"/></svg>
                </button>
                <input type="file" ref={fileInputRef} className="hidden" multiple onChange={handleFileUpload} />

                {/* Tools Popover Trigger */}
                <div className="relative">
                  <button 
                    onClick={() => { setShowTools(!showTools); setShowModels(false); }}
                    className={`flex items-center gap-2 px-4 py-3 rounded-xl transition-all font-google font-black text-[10px] uppercase tracking-widest active:scale-95 ${showTools ? 'bg-[#FFB347] text-[#133020]' : theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#133020]/60' : 'hover:bg-white/5 text-white/60'}`}
                  >
                    <SparkleIcon className={`w-3.5 h-3.5 ${showTools ? 'fill-[#133020]' : 'fill-current opacity-40'}`} />
                    <span className="hidden sm:inline">{selectedTool.name}</span>
                  </button>

                  {/* Tools Menu Popover */}
                  {showTools && (
                    <div className="absolute bottom-full left-0 mb-4 w-56 bg-[#133020] border border-white/10 rounded-2xl shadow-2xl overflow-hidden popover-enter z-[100]">
                      <div className="p-1 space-y-1">
                        {TOOLS.map(t => (
                          <button
                            key={t.id}
                            onClick={() => { setSelectedTool(t); setShowTools(false); }}
                            className={`w-full text-left p-4 rounded-xl transition-all ${selectedTool.id === t.id ? 'bg-[#046241] text-white shadow-inner' : 'hover:bg-white/5 text-white/60'}`}
                          >
                            <div className="flex items-center gap-2">
                               <span>{t.icon}</span>
                               <div className="text-[10px] font-google font-black uppercase tracking-widest">{t.name}</div>
                            </div>
                            <div className={`text-[9px] opacity-40 mt-1`}>{t.description}</div>
                          </button>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                <div className="flex-1 min-w-0">
                  <textarea
                    rows={1}
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={handleKeyPress}
                    placeholder={selectedTool.id === 'image' ? "Define visual parameters..." : "Synthesize new request..."}
                    className={`w-full bg-transparent border-none resize-none py-3.5 px-3 text-[15px] font-google font-bold placeholder-current opacity-60 focus:ring-0 focus:outline-none ring-0 outline-none max-h-40 no-scrollbar ${theme === 'classic' ? 'text-[#133020]' : 'text-white'}`}
                  />
                </div>

                <div className="flex items-center gap-1.5 pr-1">
                   {/* Model Popover Trigger */}
                   <div className="relative">
                     <button 
                        onClick={() => { setShowModels(!showModels); setShowTools(false); }}
                        className={`px-4 py-2.5 rounded-xl text-[9px] font-google font-black uppercase tracking-widest transition-all active:scale-95 ${theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#133020]/30' : 'hover:bg-white/5 text-white/30'}`}
                      >
                        {selectedModel.name}
                      </button>

                      {showModels && (
                        <div className="absolute bottom-full right-0 mb-4 w-56 bg-[#133020] border border-white/10 rounded-2xl shadow-2xl overflow-hidden popover-enter z-[100]">
                          <div className="p-1 space-y-1">
                            {MODELS.map(m => (
                              <button
                                key={m.id}
                                onClick={() => { setSelectedModel(m); setShowModels(false); }}
                                className={`w-full text-left p-4 rounded-xl transition-all ${selectedModel.id === m.id ? 'bg-[#046241] text-white shadow-inner' : 'hover:bg-white/5 text-white/60'}`}
                              >
                                <div className="text-[10px] font-google font-black uppercase tracking-widest">{m.name}</div>
                                <div className={`text-[9px] opacity-40 mt-1`}>{m.description}</div>
                              </button>
                            ))}
                          </div>
                        </div>
                      )}
                   </div>

                    {/* Send Button */}
                    <button 
                      disabled={isLoading || (!input.trim() && attachments.length === 0)}
                      onClick={() => handleSend()}
                      className={`p-4 rounded-xl transition-all shadow-xl active:scale-90 ${(!input.trim() && attachments.length === 0) ? 'bg-black/5 text-black/10 shadow-none' : 'bg-[#FFB347] text-[#133020]'}`}
                    >
                      <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M13.5 4.5L21 12m0 0l-7.5 7.5M21 12H3"/></svg>
                    </button>
                </div>
              </div>
            </div>

            <p className="text-[9px] font-google opacity-20 text-center mt-6 font-black uppercase tracking-[0.4em]">
              Intelligence Authenticated • Lifewood Core
            </p>
          </div>
        </div>
      </main>

      {/* Settings Modal */}
      {showSettings && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className="w-full max-w-xl bg-[#133020] rounded-[2.5rem] overflow-hidden shadow-2xl border border-white/10 text-white animate-in slide-in-from-bottom-4">
            <div className="p-8 border-b border-white/5 flex items-center justify-between">
              <div>
                <h3 className="text-xl font-google font-black uppercase tracking-tighter">Core Directives</h3>
                <p className="text-[10px] opacity-40 font-bold uppercase mt-1">Personalize your intelligence session</p>
              </div>
              <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M6 18L18 6M6 6l12 12"/></svg>
              </button>
            </div>

            <div className="p-8 space-y-8">
              {/* Theme Selector */}
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] opacity-40">Architectural Theme</label>
                <div className="grid grid-cols-3 gap-3">
                  {[
                    { id: 'classic', label: 'Beige', color: 'bg-[#f5eedb]' },
                    { id: 'dark', label: 'Emerald', color: 'bg-[#133020]' },
                    { id: 'high-contrast', label: 'Cyber', color: 'bg-black' },
                  ].map(t => (
                    <button 
                      key={t.id}
                      onClick={() => setTheme(t.id)}
                      className={`flex flex-col items-center gap-3 p-4 rounded-2xl border transition-all ${theme === t.id ? 'border-[#FFB347] bg-white/10 shadow-lg' : 'border-white/5 hover:bg-white/5'}`}
                    >
                      <div className={`w-8 h-8 rounded-full shadow-inner ${t.color} border border-white/10`}></div>
                      <span className="text-[10px] font-bold uppercase tracking-widest">{t.label}</span>
                    </button>
                  ))}
                </div>
              </div>

              {/* System Instructions */}
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] opacity-40">System Directives</label>
                <textarea 
                  value={systemInstruction}
                  onChange={(e) => setSystemInstruction(e.target.value)}
                  placeholder="Define how Lifewood Intelligence should behave..."
                  className="w-full h-32 bg-black/40 border border-white/10 rounded-2xl p-4 text-xs font-medium leading-relaxed resize-none focus:border-[#FFB347] transition-all focus:ring-0"
                />
              </div>
            </div>

            <div className="p-8 bg-black/20 flex justify-end">
              <button 
                onClick={() => setShowSettings(false)}
                className="bg-[#FFB347] text-[#133020] px-8 py-3 rounded-xl font-google font-black text-xs uppercase tracking-widest active:scale-95 transition-all shadow-lg"
              >
                Sync Configuration
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Side View Blur Overlay */}
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-[#133020]/40 backdrop-blur-sm z-[90] lg:hidden animate-in fade-in" onClick={() => setIsSidebarOpen(false)}></div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { LifewoodLogo, SparkleIcon, TOOLS, MODELS } from './constants';
import { Message, SenderType, Conversation, FileData } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  // Persistence states
  const [conversations, setConversations] = useState<Conversation[]>(() => {
    const saved = localStorage.getItem('lifewood_v3_conversations');
    return saved ? JSON.parse(saved).map((c: any) => ({
      ...c,
      messages: c.messages.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
      createdAt: new Date(c.createdAt)
    })) : [];
  });

  const [systemInstruction, setSystemInstruction] = useState(() => 
    localStorage.getItem('lifewood_system_instruction') || 'You are Lifewood Intelligence, a proactive innovation partner focusing on AI data strategy and global logistics.'
  );

  const [theme, setTheme] = useState(() => localStorage.getItem('lifewood_theme') || 'classic');

  // UI states
  const [activeId, setActiveId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [attachments, setAttachments] = useState<FileData[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  const [showTools, setShowTools] = useState(false);
  const [selectedTool, setSelectedTool] = useState(TOOLS[0]); // Default is General Chat
  const [showModels, setShowModels] = useState(false);
  const [selectedModel, setSelectedModel] = useState(MODELS[0]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const currentConversation = conversations.find(c => c.id === activeId);

  // Persistence Effects
  useEffect(() => {
    localStorage.setItem('lifewood_v3_conversations', JSON.stringify(conversations));
  }, [conversations]);

  useEffect(() => {
    localStorage.setItem('lifewood_system_instruction', systemInstruction);
  }, [systemInstruction]);

  useEffect(() => {
    localStorage.setItem('lifewood_theme', theme);
  }, [theme]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [currentConversation?.messages, isLoading]);

  const startNewChat = () => {
    setActiveId(null);
    setInput('');
    setAttachments([]);
    setIsSidebarOpen(false);
    setSelectedTool(TOOLS[0]);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    Array.from(files).forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        setAttachments(prev => [...prev, {
          data: event.target?.result as string,
          mimeType: file.type,
          fileName: file.name
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleSend = async (overrideInput?: string) => {
    const finalInput = overrideInput || input;
    if ((!finalInput.trim() && attachments.length === 0) || isLoading) return;

    let targetConv = currentConversation;
    if (!targetConv) {
      const newId = Date.now().toString();
      targetConv = {
        id: newId,
        title: finalInput.slice(0, 30) || 'New Lifewood Session',
        messages: [],
        personaId: 'default',
        createdAt: new Date(),
      };
      setConversations(prev => [targetConv!, ...prev]);
      setActiveId(newId);
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      text: finalInput,
      sender: SenderType.USER,
      timestamp: new Date(),
      attachments: [...attachments],
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, userMsg] } : c
    ));

    setInput('');
    setAttachments([]);
    setIsLoading(true);

    const aiResponse = await getGeminiResponse(
      userMsg.text, 
      userMsg.attachments,
      selectedTool.id,
      selectedModel.id,
      systemInstruction
    );

    const aiMsg: Message = {
      id: (Date.now() + 1).toString(),
      text: aiResponse.text,
      generatedImageUrl: aiResponse.generatedImageUrl,
      sender: SenderType.AI,
      timestamp: new Date(),
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, aiMsg] } : c
    ));
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const deleteConversation = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setConversations(prev => prev.filter(c => c.id !== id));
    if (activeId === id) setActiveId(null);
  };

  const suggestedPrompts = [
    { 
      category: 'Strategic Vision', 
      label: 'ASEAN HUB', 
      text: "Conceptualize a logistics-first AI data hub in ASEAN.", 
      tool: 'image',
      icon: '🌐'
    },
    { 
      category: 'Technical Execution', 
      label: 'RLHF QUALITY', 
      text: "Compare data quality benchmarks for multi-lingual RLHF.", 
      tool: 'research',
      icon: '📊'
    },
    { 
      category: 'Brand Value', 
      label: 'ESG GOALS', 
      text: "How does Lifewood's 'Always On' model reduce ESG carbon footprint?", 
      tool: 'chat',
      icon: '🌱'
    }
  ];

  const getThemeClasses = () => {
    switch(theme) {
      case 'dark': return 'bg-[#133020] text-white';
      case 'high-contrast': return 'bg-black text-[#FFB347]';
      default: return 'bg-[#f5eedb] text-[#133020]';
    }
  };

  const getFooterBackground = () => {
    switch(theme) {
      case 'dark': return 'from-[#133020] via-[#133020] to-transparent';
      case 'high-contrast': return 'from-black via-black to-transparent';
      default: return 'from-[#f5eedb] via-[#f5eedb] to-transparent';
    }
  };

  return (
    <div className={`flex h-screen overflow-hidden transition-colors duration-500 ${getThemeClasses()}`}>

      {/* Sidebar - Higher Z-index to be on top of footer container */}
      <aside className={`fixed inset-y-0 left-0 z-[100] w-72 bg-[#133020] transition-transform duration-300 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 flex flex-col shadow-2xl`}>
        <div className="p-8 border-b border-white/5">
          <LifewoodLogo />
          <button 
            onClick={startNewChat}
            className="w-full mt-10 bg-[#046241] hover:bg-[#057a51] text-white py-4 rounded-xl flex items-center justify-center gap-2 font-google font-bold text-xs uppercase tracking-widest transition-all shadow-lg active:scale-95"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M12 4v16m8-8H4"/></svg>
            New Session
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-1 lifewood-scrollbar">
          <h3 className="text-white/30 text-[10px] font-google font-black uppercase tracking-[0.2em] px-4 py-4">Knowledge Base</h3>
          {conversations.map(conv => (
            <div 
              key={conv.id}
              onClick={() => { setActiveId(conv.id); setIsSidebarOpen(false); }}
              className={`group relative px-4 py-3.5 rounded-xl cursor-pointer transition-all flex items-center justify-between ${activeId === conv.id ? 'bg-[#046241] text-white shadow-xl' : 'hover:bg-white/5 text-white/60 hover:text-white'}`}
            >
              <div className="flex-1 min-w-0">
                <div className="text-[13px] font-semibold truncate leading-tight">{conv.title}</div>
                <div className="text-[9px] font-black uppercase tracking-tighter opacity-40 mt-1">{conv.createdAt.toLocaleDateString()}</div>
              </div>
              <button onClick={(e) => deleteConversation(e, conv.id)} className="opacity-0 group-hover:opacity-100 p-2 hover:bg-red-500/20 rounded-lg transition-all text-red-400">
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
              </button>
            </div>
          ))}
        </div>

        <div className="p-6 bg-black/20 border-t border-white/5 space-y-4">
          <button 
            onClick={() => setShowSettings(true)}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-white/5 text-white/40 hover:text-white transition-all text-[10px] font-google font-black uppercase tracking-widest"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37a1.724 1.724 0 002.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            Config
          </button>
          <div className="flex items-center justify-between text-[9px] text-white/20 font-google font-black uppercase tracking-[0.4em]">
            <span>Always On</span>
            <div className="w-1 h-1 rounded-full bg-[#FFB347] animate-pulse"></div>
          </div>
        </div>
      </aside>

      {/* Main Canvas - Dim on mobile when sidebar is open instead of hiding */}
      <main className={`flex-1 flex flex-col relative h-full transition-all duration-300 ${isSidebarOpen ? 'opacity-20 pointer-events-none lg:opacity-100 lg:pointer-events-auto' : 'opacity-100'}`}>
        <header className="absolute top-0 left-0 right-0 h-16 flex items-center justify-between px-6 z-40">
          <button onClick={() => setIsSidebarOpen(true)} className="p-3 bg-[#133020] text-white rounded-full shadow-xl lg:hidden">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M4 6h16M4 12h16m-7 6h7"/></svg>
          </button>
        </header>

        {/* Scrollable conversation text container - Aligned to the LEFT for asymmetry */}
        <div className="flex-1 overflow-y-auto flex flex-col items-start lifewood-scrollbar pb-80 px-6 pt-12 lg:pl-12 xl:pl-24">
          <div className="w-full max-w-2xl space-y-14">

            {(!currentConversation || currentConversation.messages.length === 0) && (
              <div className="mt-16 space-y-12 animate-in fade-in duration-1000">
                <div className="text-left space-y-6">
                  <h2 className={`text-6xl font-google font-black tracking-tighter ${theme === 'classic' ? 'text-[#046241]' : 'text-[#FFB347]'}`}>
                    Innovation. <br/> <span className={theme === 'classic' ? 'text-[#FFB347]' : 'text-white'}>Verified.</span>
                  </h2>
                  <p className={`text-[11px] font-google font-black uppercase tracking-[0.6em] opacity-30`}>
                    Enterprise Intelligence Engine
                  </p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {suggestedPrompts.map((s, i) => (
                    <button 
                      key={i}
                      onClick={() => { setSelectedTool(TOOLS.find(t => t.id === s.tool) || TOOLS[0]); setInput(s.text); }}
                      className={`group p-6 rounded-[2rem] border transition-all text-left flex flex-col justify-between ${theme === 'classic' ? 'bg-white border-[#133020]/5 hover:border-[#FFB347]' : 'bg-white/5 border-white/10 hover:border-[#FFB347]'}`}
                    >
                      <div>
                        <div className="flex items-center justify-between mb-4">
                           <span className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${theme === 'classic' ? 'bg-[#133020]/5 text-[#133020]/60' : 'bg-white/10 text-white/60'}`}>
                             {s.category}
                           </span>
                           <span className="text-lg opacity-40 group-hover:opacity-100 transition-opacity">{s.icon}</span>
                        </div>
                        <h4 className="text-[10px] font-black uppercase tracking-tighter text-[#FFB347] mb-1">{s.label}</h4>
                        <p className={`text-[13px] font-bold leading-snug ${theme === 'classic' ? 'text-[#133020]' : 'text-white'}`}>{s.text}</p>
                      </div>
                      <div className="mt-6 flex justify-end">
                        <div className={`p-2 rounded-full transition-colors ${theme === 'classic' ? 'bg-[#f5eedb] group-hover:bg-[#FFB347]' : 'bg-white/10 group-hover:bg-[#FFB347]'}`}>
                           <SparkleIcon className="w-3 h-3 group-hover:fill-white" />
                        </div>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {currentConversation?.messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.sender === SenderType.USER ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-4 duration-500`}>
                <div className={`flex gap-6 w-full ${msg.sender === SenderType.USER ? 'flex-row-reverse' : ''}`}>
                   {msg.sender === SenderType.AI && (
                     <div className="mt-1 flex-shrink-0">
                       <div className="w-8 h-8 rounded-full bg-[#133020] flex items-center justify-center shadow-lg border border-white/10">
                          <SparkleIcon className="w-4 h-4" />
                       </div>
                     </div>
                   )}
                   <div className={`flex-1 ${msg.sender === SenderType.USER ? 'max-w-[85%]' : ''}`}>
                      <div className={`
                        ${msg.sender === SenderType.USER 
                          ? 'bg-[#FFB347] text-[#133020] px-6 py-4 rounded-3xl rounded-tr-none font-google font-bold text-[14px] shadow-lg border border-[#133020]/10' 
                          : `font-serif text-[18px] leading-relaxed tracking-wide opacity-90 ${theme === 'classic' ? 'text-[#133020]' : 'text-white/90'}`
                        }
                      `}>
                        {msg.text}
                        {msg.generatedImageUrl && (
                          <div className="mt-8 rounded-[2rem] overflow-hidden shadow-2xl border border-white/5 bg-black/10 p-2">
                            <img src={msg.generatedImageUrl} className="w-full h-auto rounded-[1.8rem]" />
                          </div>
                        )}
                      </div>
                      <div className={`mt-2 text-[9px] font-google font-black uppercase tracking-widest opacity-20 ${msg.sender === SenderType.USER ? 'text-right' : ''}`}>
                        {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </div>
                   </div>
                </div>
              </div>
            ))}

            {isLoading && (
              <div className="flex gap-6 w-full animate-pulse">
                <div className="w-8 h-8 rounded-full bg-white/10" />
                <div className="flex-1 space-y-4 pt-3">
                  <div className={`h-2 rounded-full w-3/4 ${theme === 'classic' ? 'bg-[#133020]/5' : 'bg-white/10'}`}></div>
                  <div className={`h-2 rounded-full w-1/2 ${theme === 'classic' ? 'bg-[#133020]/5' : 'bg-white/10'}`}></div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
        </div>

        {/* Architectural Interaction Rail Container - Positioned to the left on large screens */}
        <div className={`fixed bottom-0 left-0 right-0 pt-32 pb-8 px-8 flex justify-center lg:justify-start bg-gradient-to-t ${getFooterBackground()} z-[50] pointer-events-none`}>
          <div className="w-full max-w-3xl lg:ml-12 xl:ml-24 pointer-events-auto">

            {attachments.length > 0 && (
              <div className="flex flex-wrap gap-2 mb-4 px-2 animate-in slide-in-from-bottom-2">
                {attachments.map((file, idx) => (
                  <div key={idx} className="relative group bg-white p-1 rounded-xl shadow-lg border border-[#133020]/5 w-20 h-20">
                    <img src={file.data} className="w-full h-full object-cover rounded-lg" />
                    <button onClick={() => setAttachments(prev => prev.filter((_, i) => i !== idx))} className="absolute -top-2 -right-2 bg-[#133020] text-white p-1 rounded-full shadow-md scale-75">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12"/></svg>
                    </button>
                  </div>
                ))}
              </div>
            )}

            <div className={`rounded-[1.5rem] overflow-visible border-none shadow-2xl relative ${theme === 'classic' ? 'bg-white' : 'bg-[#046241]/95 backdrop-blur-2xl border border-white/5'}`}>

              {/* Interaction Rail */}
              <div className="p-3 flex items-center gap-2 relative">
                {/* Attachment Button */}
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className={`p-3.5 rounded-xl transition-all active:scale-95 ${theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#133020]/40' : 'hover:bg-white/5 text-white/40'}`}
                  title="Upload Attachments"
                >
                  <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M12 4v16m8-8H4"/></svg>
                </button>
                <input type="file" ref={fileInputRef} className="hidden" multiple onChange={handleFileUpload} />

                {/* Tools Popover Trigger */}
                <div className="relative">
                  <button 
                    onClick={() => { setShowTools(!showTools); setShowModels(false); }}
                    className={`flex items-center gap-2 px-4 py-3 rounded-xl transition-all font-google font-black text-[10px] uppercase tracking-widest active:scale-95 ${showTools ? 'bg-[#FFB347] text-[#133020]' : theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#133020]/60' : 'hover:bg-white/5 text-white/60'}`}
                  >
                    <SparkleIcon className={`w-3.5 h-3.5 ${showTools ? 'fill-[#133020]' : 'fill-current opacity-40'}`} />
                    <span className="hidden sm:inline">{selectedTool.name}</span>
                  </button>

                  {/* Tools Menu Popover */}
                  {showTools && (
                    <div className="absolute bottom-full left-0 mb-4 w-56 bg-[#133020] border border-white/10 rounded-2xl shadow-2xl overflow-hidden popover-enter z-[100]">
                      <div className="p-1 space-y-1">
                        {TOOLS.map(t => (
                          <button
                            key={t.id}
                            onClick={() => { setSelectedTool(t); setShowTools(false); }}
                            className={`w-full text-left p-4 rounded-xl transition-all ${selectedTool.id === t.id ? 'bg-[#046241] text-white shadow-inner' : 'hover:bg-white/5 text-white/60'}`}
                          >
                            <div className="flex items-center gap-2">
                               <span>{t.icon}</span>
                               <div className="text-[10px] font-google font-black uppercase tracking-widest">{t.name}</div>
                            </div>
                            <div className={`text-[9px] opacity-40 mt-1`}>{t.description}</div>
                          </button>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                <div className="flex-1 min-w-0">
                  <textarea
                    rows={1}
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={handleKeyPress}
                    placeholder={selectedTool.id === 'image' ? "Define visual parameters..." : "Synthesize new request..."}
                    className={`w-full bg-transparent border-none resize-none py-3.5 px-3 text-[15px] font-google font-bold placeholder-current opacity-60 focus:ring-0 focus:outline-none ring-0 outline-none max-h-40 no-scrollbar ${theme === 'classic' ? 'text-[#133020]' : 'text-white'}`}
                  />
                </div>

                <div className="flex items-center gap-1.5 pr-1">
                   {/* Model Popover Trigger */}
                   <div className="relative">
                     <button 
                        onClick={() => { setShowModels(!showModels); setShowTools(false); }}
                        className={`px-4 py-2.5 rounded-xl text-[9px] font-google font-black uppercase tracking-widest transition-all active:scale-95 ${theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#133020]/30' : 'hover:bg-white/5 text-white/30'}`}
                      >
                        {selectedModel.name}
                      </button>

                      {showModels && (
                        <div className="absolute bottom-full right-0 mb-4 w-56 bg-[#133020] border border-white/10 rounded-2xl shadow-2xl overflow-hidden popover-enter z-[100]">
                          <div className="p-1 space-y-1">
                            {MODELS.map(m => (
                              <button
                                key={m.id}
                                onClick={() => { setSelectedModel(m); setShowModels(false); }}
                                className={`w-full text-left p-4 rounded-xl transition-all ${selectedModel.id === m.id ? 'bg-[#046241] text-white shadow-inner' : 'hover:bg-white/5 text-white/60'}`}
                              >
                                <div className="text-[10px] font-google font-black uppercase tracking-widest">{m.name}</div>
                                <div className={`text-[9px] opacity-40 mt-1`}>{m.description}</div>
                              </button>
                            ))}
                          </div>
                        </div>
                      )}
                   </div>

                    {/* Send Button */}
                    <button 
                      disabled={isLoading || (!input.trim() && attachments.length === 0)}
                      onClick={() => handleSend()}
                      className={`p-4 rounded-xl transition-all shadow-xl active:scale-90 ${(!input.trim() && attachments.length === 0) ? 'bg-black/5 text-black/10 shadow-none' : 'bg-[#FFB347] text-[#133020]'}`}
                    >
                      <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M13.5 4.5L21 12m0 0l-7.5 7.5M21 12H3"/></svg>
                    </button>
                </div>
              </div>
            </div>

            <p className="text-[9px] font-google opacity-20 text-center mt-6 font-black uppercase tracking-[0.4em]">
              Intelligence Authenticated • Lifewood Core
            </p>
          </div>
        </div>
      </main>

      {/* Settings Modal */}
      {showSettings && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className="w-full max-w-xl bg-[#133020] rounded-[2.5rem] overflow-hidden shadow-2xl border border-white/10 text-white animate-in slide-in-from-bottom-4">
            <div className="p-8 border-b border-white/5 flex items-center justify-between">
              <div>
                <h3 className="text-xl font-google font-black uppercase tracking-tighter">Core Directives</h3>
                <p className="text-[10px] opacity-40 font-bold uppercase mt-1">Personalize your intelligence session</p>
              </div>
              <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M6 18L18 6M6 6l12 12"/></svg>
              </button>
            </div>

            <div className="p-8 space-y-8">
              {/* Theme Selector */}
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] opacity-40">Architectural Theme</label>
                <div className="grid grid-cols-3 gap-3">
                  {[
                    { id: 'classic', label: 'Beige', color: 'bg-[#f5eedb]' },
                    { id: 'dark', label: 'Emerald', color: 'bg-[#133020]' },
                    { id: 'high-contrast', label: 'Cyber', color: 'bg-black' },
                  ].map(t => (
                    <button 
                      key={t.id}
                      onClick={() => setTheme(t.id)}
                      className={`flex flex-col items-center gap-3 p-4 rounded-2xl border transition-all ${theme === t.id ? 'border-[#FFB347] bg-white/10 shadow-lg' : 'border-white/5 hover:bg-white/5'}`}
                    >
                      <div className={`w-8 h-8 rounded-full shadow-inner ${t.color} border border-white/10`}></div>
                      <span className="text-[10px] font-bold uppercase tracking-widest">{t.label}</span>
                    </button>
                  ))}
                </div>
              </div>

              {/* System Instructions */}
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] opacity-40">System Directives</label>
                <textarea 
                  value={systemInstruction}
                  onChange={(e) => setSystemInstruction(e.target.value)}
                  placeholder="Define how Lifewood Intelligence should behave..."
                  className="w-full h-32 bg-black/40 border border-white/10 rounded-2xl p-4 text-xs font-medium leading-relaxed resize-none focus:border-[#FFB347] transition-all focus:ring-0"
                />
              </div>
            </div>

            <div className="p-8 bg-black/20 flex justify-end">
              <button 
                onClick={() => setShowSettings(false)}
                className="bg-[#FFB347] text-[#133020] px-8 py-3 rounded-xl font-google font-black text-xs uppercase tracking-widest active:scale-95 transition-all shadow-lg"
              >
                Sync Configuration
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Side View Blur Overlay */}
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-[#133020]/40 backdrop-blur-sm z-[90] lg:hidden animate-in fade-in" onClick={() => setIsSidebarOpen(false)}></div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { LifewoodLogo, SparkleIcon, TOOLS, MODELS } from './constants';
import { Message, SenderType, Conversation, FileData } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  // Persistence states
  const [conversations, setConversations] = useState<Conversation[]>(() => {
    const saved = localStorage.getItem('lifewood_v3_conversations');
    return saved ? JSON.parse(saved).map((c: any) => ({
      ...c,
      messages: c.messages.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
      createdAt: new Date(c.createdAt)
    })) : [];
  });

  const [systemInstruction, setSystemInstruction] = useState(() => 
    localStorage.getItem('lifewood_system_instruction') || 'You are Lifewood Intelligence, a proactive innovation partner focusing on AI data strategy and global logistics.'
  );

  const [theme, setTheme] = useState(() => localStorage.getItem('lifewood_theme') || 'classic');

  // UI states
  const [activeId, setActiveId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [attachments, setAttachments] = useState<FileData[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  const [showTools, setShowTools] = useState(false);
  const [selectedTool, setSelectedTool] = useState(TOOLS[0]); // Default is General Chat
  const [showModels, setShowModels] = useState(false);
  const [selectedModel, setSelectedModel] = useState(MODELS[0]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const currentConversation = conversations.find(c => c.id === activeId);

  // Persistence Effects
  useEffect(() => {
    localStorage.setItem('lifewood_v3_conversations', JSON.stringify(conversations));
  }, [conversations]);

  useEffect(() => {
    localStorage.setItem('lifewood_system_instruction', systemInstruction);
  }, [systemInstruction]);

  useEffect(() => {
    localStorage.setItem('lifewood_theme', theme);
  }, [theme]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [currentConversation?.messages, isLoading]);

  const startNewChat = () => {
    setActiveId(null);
    setInput('');
    setAttachments([]);
    setIsSidebarOpen(false);
    setSelectedTool(TOOLS[0]);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    Array.from(files).forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        setAttachments(prev => [...prev, {
          data: event.target?.result as string,
          mimeType: file.type,
          fileName: file.name
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleSend = async (overrideInput?: string) => {
    const finalInput = overrideInput || input;
    if ((!finalInput.trim() && attachments.length === 0) || isLoading) return;

    let targetConv = currentConversation;
    if (!targetConv) {
      const newId = Date.now().toString();
      targetConv = {
        id: newId,
        title: finalInput.slice(0, 30) || 'New Lifewood Session',
        messages: [],
        personaId: 'default',
        createdAt: new Date(),
      };
      setConversations(prev => [targetConv!, ...prev]);
      setActiveId(newId);
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      text: finalInput,
      sender: SenderType.USER,
      timestamp: new Date(),
      attachments: [...attachments],
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, userMsg] } : c
    ));

    setInput('');
    setAttachments([]);
    setIsLoading(true);

    const aiResponse = await getGeminiResponse(
      userMsg.text, 
      userMsg.attachments,
      selectedTool.id,
      selectedModel.id,
      systemInstruction
    );

    const aiMsg: Message = {
      id: (Date.now() + 1).toString(),
      text: aiResponse.text,
      generatedImageUrl: aiResponse.generatedImageUrl,
      sender: SenderType.AI,
      timestamp: new Date(),
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, aiMsg] } : c
    ));
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const deleteConversation = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setConversations(prev => prev.filter(c => c.id !== id));
    if (activeId === id) setActiveId(null);
  };

  const suggestedPrompts = [
    { 
      category: 'Strategic Vision', 
      label: 'ASEAN HUB', 
      text: "Conceptualize a logistics-first AI data hub in ASEAN.", 
      tool: 'image',
      icon: '🌐'
    },
    { 
      category: 'Technical Execution', 
      label: 'RLHF QUALITY', 
      text: "Compare data quality benchmarks for multi-lingual RLHF.", 
      tool: 'research',
      icon: '📊'
    },
    { 
      category: 'Brand Value', 
      label: 'ESG GOALS', 
      text: "How does Lifewood's 'Always On' model reduce ESG carbon footprint?", 
      tool: 'chat',
      icon: '🌱'
    }
  ];

  const getThemeClasses = () => {
    switch(theme) {
      case 'dark': return 'bg-[#133020] text-white';
      case 'high-contrast': return 'bg-black text-[#FFB347]';
      default: return 'bg-[#f5eedb] text-[#133020]';
    }
  };

  const getFooterBackground = () => {
    switch(theme) {
      case 'dark': return 'from-[#133020] via-[#133020] to-transparent';
      case 'high-contrast': return 'from-black via-black to-transparent';
      default: return 'from-[#f5eedb] via-[#f5eedb] to-transparent';
    }
  };

  return (
    <div className={`flex h-screen overflow-hidden transition-colors duration-500 ${getThemeClasses()}`}>

      {/* Sidebar - Higher Z-index to be on top of footer container */}
      <aside className={`fixed inset-y-0 left-0 z-[100] w-72 bg-[#133020] transition-transform duration-300 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 flex flex-col shadow-2xl`}>
        <div className="p-8 border-b border-white/5">
          <LifewoodLogo />
          <button 
            onClick={startNewChat}
            className="w-full mt-10 bg-[#046241] hover:bg-[#057a51] text-white py-4 rounded-xl flex items-center justify-center gap-2 font-google font-bold text-xs uppercase tracking-widest transition-all shadow-lg active:scale-95"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M12 4v16m8-8H4"/></svg>
            New Session
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-1 lifewood-scrollbar">
          <h3 className="text-white/30 text-[10px] font-google font-black uppercase tracking-[0.2em] px-4 py-4">Knowledge Base</h3>
          {conversations.map(conv => (
            <div 
              key={conv.id}
              onClick={() => { setActiveId(conv.id); setIsSidebarOpen(false); }}
              className={`group relative px-4 py-3.5 rounded-xl cursor-pointer transition-all flex items-center justify-between ${activeId === conv.id ? 'bg-[#046241] text-white shadow-xl' : 'hover:bg-white/5 text-white/60 hover:text-white'}`}
            >
              <div className="flex-1 min-w-0">
                <div className="text-[13px] font-semibold truncate leading-tight">{conv.title}</div>
                <div className="text-[9px] font-black uppercase tracking-tighter opacity-40 mt-1">{conv.createdAt.toLocaleDateString()}</div>
              </div>
              <button onClick={(e) => deleteConversation(e, conv.id)} className="opacity-0 group-hover:opacity-100 p-2 hover:bg-red-500/20 rounded-lg transition-all text-red-400">
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
              </button>
            </div>
          ))}
        </div>

        <div className="p-6 bg-black/20 border-t border-white/5 space-y-4">
          <button 
            onClick={() => setShowSettings(true)}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-white/5 text-white/40 hover:text-white transition-all text-[10px] font-google font-black uppercase tracking-widest"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37a1.724 1.724 0 002.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            Config
          </button>
          <div className="flex items-center justify-between text-[9px] text-white/20 font-google font-black uppercase tracking-[0.4em]">
            <span>Always On</span>
            <div className="w-1 h-1 rounded-full bg-[#FFB347] animate-pulse"></div>
          </div>
        </div>
      </aside>

      {/* Main Canvas - Dim on mobile when sidebar is open */}
      <main className={`flex-1 flex flex-col relative h-full transition-all duration-300 ${isSidebarOpen ? 'opacity-20 pointer-events-none lg:opacity-100 lg:pointer-events-auto' : 'opacity-100'}`}>
        <header className="absolute top-0 left-0 right-0 h-16 flex items-center justify-between px-6 z-40">
          <button onClick={() => setIsSidebarOpen(true)} className="p-3 bg-[#133020] text-white rounded-full shadow-xl lg:hidden">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M4 6h16M4 12h16m-7 6h7"/></svg>
          </button>
        </header>

        {/* Scrollable conversation text container - CENTERED lane */}
        <div className="flex-1 overflow-y-auto flex flex-col items-center lifewood-scrollbar pb-80 px-6 pt-12">
          {/* Broadened max-w-3xl to allow "left-ish" AI feel while lane is centered */}
          <div className="w-full max-w-3xl space-y-14">

            {(!currentConversation || currentConversation.messages.length === 0) && (
              <div className="mt-16 space-y-12 animate-in fade-in duration-1000">
                <div className="text-center space-y-6">
                  <h2 className={`text-6xl font-google font-black tracking-tighter ${theme === 'classic' ? 'text-[#046241]' : 'text-[#FFB347]'}`}>
                    Innovation. <br/> <span className={theme === 'classic' ? 'text-[#FFB347]' : 'text-white'}>Verified.</span>
                  </h2>
                  <p className={`text-[11px] font-google font-black uppercase tracking-[0.6em] opacity-30`}>
                    Enterprise Intelligence Engine
                  </p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {suggestedPrompts.map((s, i) => (
                    <button 
                      key={i}
                      onClick={() => { setSelectedTool(TOOLS.find(t => t.id === s.tool) || TOOLS[0]); setInput(s.text); }}
                      className={`group p-6 rounded-[2rem] border transition-all text-left flex flex-col justify-between ${theme === 'classic' ? 'bg-white border-[#133020]/5 hover:border-[#FFB347]' : 'bg-white/5 border-white/10 hover:border-[#FFB347]'}`}
                    >
                      <div>
                        <div className="flex items-center justify-between mb-4">
                           <span className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${theme === 'classic' ? 'bg-[#133020]/5 text-[#133020]/60' : 'bg-white/10 text-white/60'}`}>
                             {s.category}
                           </span>
                           <span className="text-lg opacity-40 group-hover:opacity-100 transition-opacity">{s.icon}</span>
                        </div>
                        <h4 className="text-[10px] font-black uppercase tracking-tighter text-[#FFB347] mb-1">{s.label}</h4>
                        <p className={`text-[13px] font-bold leading-snug ${theme === 'classic' ? 'text-[#133020]' : 'text-white'}`}>{s.text}</p>
                      </div>
                      <div className="mt-6 flex justify-end">
                        <div className={`p-2 rounded-full transition-colors ${theme === 'classic' ? 'bg-[#f5eedb] group-hover:bg-[#FFB347]' : 'bg-white/10 group-hover:bg-[#FFB347]'}`}>
                           <SparkleIcon className="w-3 h-3 group-hover:fill-white" />
                        </div>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {currentConversation?.messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.sender === SenderType.USER ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-4 duration-500`}>
                <div className={`flex gap-6 w-full ${msg.sender === SenderType.USER ? 'flex-row-reverse' : ''}`}>
                   {msg.sender === SenderType.AI && (
                     <div className="mt-1 flex-shrink-0">
                       <div className="w-8 h-8 rounded-full bg-[#133020] flex items-center justify-center shadow-lg border border-white/10">
                          <SparkleIcon className="w-4 h-4" />
                       </div>
                     </div>
                   )}
                   <div className={`flex-1 ${msg.sender === SenderType.USER ? 'max-w-[85%]' : 'max-w-[90%]'}`}>
                      <div className={`
                        ${msg.sender === SenderType.USER 
                          ? 'bg-[#FFB347] text-[#133020] px-6 py-4 rounded-3xl rounded-tr-none font-google font-bold text-[14px] shadow-lg border border-[#133020]/10' 
                          : `font-serif text-[18px] leading-relaxed tracking-wide opacity-90 ${theme === 'classic' ? 'text-[#133020]' : 'text-white/90'}`
                        }
                      `}>
                        {msg.text}
                        {msg.generatedImageUrl && (
                          <div className="mt-8 rounded-[2rem] overflow-hidden shadow-2xl border border-white/5 bg-black/10 p-2">
                            <img src={msg.generatedImageUrl} className="w-full h-auto rounded-[1.8rem]" />
                          </div>
                        )}
                      </div>
                      <div className={`mt-2 text-[9px] font-google font-black uppercase tracking-widest opacity-20 ${msg.sender === SenderType.USER ? 'text-right' : ''}`}>
                        {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </div>
                   </div>
                </div>
              </div>
            ))}

            {isLoading && (
              <div className="flex gap-6 w-full animate-pulse justify-start">
                <div className="w-8 h-8 rounded-full bg-white/10" />
                <div className="flex-1 space-y-4 pt-3">
                  <div className={`h-2 rounded-full w-3/4 ${theme === 'classic' ? 'bg-[#133020]/5' : 'bg-white/10'}`}></div>
                  <div className={`h-2 rounded-full w-1/2 ${theme === 'classic' ? 'bg-[#133020]/5' : 'bg-white/10'}`}></div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
        </div>

        {/* Architectural Interaction Rail Container - CENTERED on screen */}
        <div className={`fixed bottom-0 left-0 right-0 pt-32 pb-8 px-8 flex justify-center bg-gradient-to-t ${getFooterBackground()} z-[50] pointer-events-none`}>
          <div className="w-full max-w-3xl pointer-events-auto">

            {attachments.length > 0 && (
              <div className="flex flex-wrap gap-2 mb-4 px-2 animate-in slide-in-from-bottom-2">
                {attachments.map((file, idx) => (
                  <div key={idx} className="relative group bg-white p-1 rounded-xl shadow-lg border border-[#133020]/5 w-20 h-20">
                    <img src={file.data} className="w-full h-full object-cover rounded-lg" />
                    <button onClick={() => setAttachments(prev => prev.filter((_, i) => i !== idx))} className="absolute -top-2 -right-2 bg-[#133020] text-white p-1 rounded-full shadow-md scale-75">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12"/></svg>
                    </button>
                  </div>
                ))}
              </div>
            )}

            <div className={`rounded-[1.5rem] overflow-visible border-none shadow-2xl relative ${theme === 'classic' ? 'bg-white' : 'bg-[#046241]/95 backdrop-blur-2xl border border-white/5'}`}>

              {/* Interaction Rail */}
              <div className="p-3 flex items-center gap-2 relative">
                {/* Attachment Button */}
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className={`p-3.5 rounded-xl transition-all active:scale-95 ${theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#133020]/40' : 'hover:bg-white/5 text-white/40'}`}
                  title="Upload Attachments"
                >
                  <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M12 4v16m8-8H4"/></svg>
                </button>
                <input type="file" ref={fileInputRef} className="hidden" multiple onChange={handleFileUpload} />

                {/* Tools Popover Trigger */}
                <div className="relative">
                  <button 
                    onClick={() => { setShowTools(!showTools); setShowModels(false); }}
                    className={`flex items-center gap-2 px-4 py-3 rounded-xl transition-all font-google font-black text-[10px] uppercase tracking-widest active:scale-95 ${showTools ? 'bg-[#FFB347] text-[#133020]' : theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#133020]/60' : 'hover:bg-white/5 text-white/60'}`}
                  >
                    <SparkleIcon className={`w-3.5 h-3.5 ${showTools ? 'fill-[#133020]' : 'fill-current opacity-40'}`} />
                    <span className="hidden sm:inline">{selectedTool.name}</span>
                  </button>

                  {/* Tools Menu Popover */}
                  {showTools && (
                    <div className="absolute bottom-full left-0 mb-4 w-56 bg-[#133020] border border-white/10 rounded-2xl shadow-2xl overflow-hidden popover-enter z-[100]">
                      <div className="p-1 space-y-1">
                        {TOOLS.map(t => (
                          <button
                            key={t.id}
                            onClick={() => { setSelectedTool(t); setShowTools(false); }}
                            className={`w-full text-left p-4 rounded-xl transition-all ${selectedTool.id === t.id ? 'bg-[#046241] text-white shadow-inner' : 'hover:bg-white/5 text-white/60'}`}
                          >
                            <div className="flex items-center gap-2">
                               <span>{t.icon}</span>
                               <div className="text-[10px] font-google font-black uppercase tracking-widest">{t.name}</div>
                            </div>
                            <div className={`text-[9px] opacity-40 mt-1`}>{t.description}</div>
                          </button>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                <div className="flex-1 min-w-0">
                  <textarea
                    rows={1}
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={handleKeyPress}
                    placeholder={selectedTool.id === 'image' ? "Define visual parameters..." : "Synthesize new request..."}
                    className={`w-full bg-transparent border-none resize-none py-3.5 px-3 text-[15px] font-google font-bold placeholder-current opacity-60 focus:ring-0 focus:outline-none ring-0 outline-none max-h-40 no-scrollbar ${theme === 'classic' ? 'text-[#133020]' : 'text-white'}`}
                  />
                </div>

                <div className="flex items-center gap-1.5 pr-1">
                   {/* Model Popover Trigger */}
                   <div className="relative">
                     <button 
                        onClick={() => { setShowModels(!showModels); setShowTools(false); }}
                        className={`px-4 py-2.5 rounded-xl text-[9px] font-google font-black uppercase tracking-widest transition-all active:scale-95 ${theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#133020]/30' : 'hover:bg-white/5 text-white/30'}`}
                      >
                        {selectedModel.name}
                      </button>

                      {showModels && (
                        <div className="absolute bottom-full right-0 mb-4 w-56 bg-[#133020] border border-white/10 rounded-2xl shadow-2xl overflow-hidden popover-enter z-[100]">
                          <div className="p-1 space-y-1">
                            {MODELS.map(m => (
                              <button
                                key={m.id}
                                onClick={() => { setSelectedModel(m); setShowModels(false); }}
                                className={`w-full text-left p-4 rounded-xl transition-all ${selectedModel.id === m.id ? 'bg-[#046241] text-white shadow-inner' : 'hover:bg-white/5 text-white/60'}`}
                              >
                                <div className="text-[10px] font-google font-black uppercase tracking-widest">{m.name}</div>
                                <div className={`text-[9px] opacity-40 mt-1`}>{m.description}</div>
                              </button>
                            ))}
                          </div>
                        </div>
                      )}
                   </div>

                    {/* Send Button */}
                    <button 
                      disabled={isLoading || (!input.trim() && attachments.length === 0)}
                      onClick={() => handleSend()}
                      className={`p-4 rounded-xl transition-all shadow-xl active:scale-90 ${(!input.trim() && attachments.length === 0) ? 'bg-black/5 text-black/10 shadow-none' : 'bg-[#FFB347] text-[#133020]'}`}
                    >
                      <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M13.5 4.5L21 12m0 0l-7.5 7.5M21 12H3"/></svg>
                    </button>
                </div>
              </div>
            </div>

            <p className="text-[9px] font-google opacity-20 text-center mt-6 font-black uppercase tracking-[0.4em]">
              Intelligence Authenticated • Lifewood Core
            </p>
          </div>
        </div>
      </main>

      {/* Settings Modal */}
      {showSettings && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className="w-full max-w-xl bg-[#133020] rounded-[2.5rem] overflow-hidden shadow-2xl border border-white/10 text-white animate-in slide-in-from-bottom-4">
            <div className="p-8 border-b border-white/5 flex items-center justify-between">
              <div>
                <h3 className="text-xl font-google font-black uppercase tracking-tighter">Core Directives</h3>
                <p className="text-[10px] opacity-40 font-bold uppercase mt-1">Personalize your intelligence session</p>
              </div>
              <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M6 18L18 6M6 6l12 12"/></svg>
              </button>
            </div>

            <div className="p-8 space-y-8">
              {/* Theme Selector */}
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] opacity-40">Architectural Theme</label>
                <div className="grid grid-cols-3 gap-3">
                  {[
                    { id: 'classic', label: 'Beige', color: 'bg-[#f5eedb]' },
                    { id: 'dark', label: 'Emerald', color: 'bg-[#133020]' },
                    { id: 'high-contrast', label: 'Cyber', color: 'bg-black' },
                  ].map(t => (
                    <button 
                      key={t.id}
                      onClick={() => setTheme(t.id)}
                      className={`flex flex-col items-center gap-3 p-4 rounded-2xl border transition-all ${theme === t.id ? 'border-[#FFB347] bg-white/10 shadow-lg' : 'border-white/5 hover:bg-white/5'}`}
                    >
                      <div className={`w-8 h-8 rounded-full shadow-inner ${t.color} border border-white/10`}></div>
                      <span className="text-[10px] font-bold uppercase tracking-widest">{t.label}</span>
                    </button>
                  ))}
                </div>
              </div>

              {/* System Instructions */}
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] opacity-40">System Directives</label>
                <textarea 
                  value={systemInstruction}
                  onChange={(e) => setSystemInstruction(e.target.value)}
                  placeholder="Define how Lifewood Intelligence should behave..."
                  className="w-full h-32 bg-black/40 border border-white/10 rounded-2xl p-4 text-xs font-medium leading-relaxed resize-none focus:border-[#FFB347] transition-all focus:ring-0"
                />
              </div>
            </div>

            <div className="p-8 bg-black/20 flex justify-end">
              <button 
                onClick={() => setShowSettings(false)}
                className="bg-[#FFB347] text-[#133020] px-8 py-3 rounded-xl font-google font-black text-xs uppercase tracking-widest active:scale-95 transition-all shadow-lg"
              >
                Sync Configuration
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Side View Blur Overlay */}
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-[#133020]/40 backdrop-blur-sm z-[90] lg:hidden animate-in fade-in" onClick={() => setIsSidebarOpen(false)}></div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { LifewoodLogo, SparkleIcon, TOOLS, MODELS } from './constants';
import { Message, SenderType, Conversation, FileData } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  // Persistence states
  const [conversations, setConversations] = useState<Conversation[]>(() => {
    const saved = localStorage.getItem('lifewood_v3_conversations');
    return saved ? JSON.parse(saved).map((c: any) => ({
      ...c,
      messages: c.messages.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
      createdAt: new Date(c.createdAt)
    })) : [];
  });

  const [systemInstruction, setSystemInstruction] = useState(() => 
    localStorage.getItem('lifewood_system_instruction') || 'You are Lifewood Intelligence, a proactive innovation partner focusing on AI data strategy and global logistics.'
  );

  const [theme, setTheme] = useState(() => localStorage.getItem('lifewood_theme') || 'classic');

  // UI states
  const [activeId, setActiveId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [attachments, setAttachments] = useState<FileData[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  const [showTools, setShowTools] = useState(false);
  const [selectedTool, setSelectedTool] = useState(TOOLS[0]); // Default is General Chat
  const [showModels, setShowModels] = useState(false);
  const [selectedModel, setSelectedModel] = useState(MODELS[0]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const currentConversation = conversations.find(c => c.id === activeId);

  // Persistence Effects
  useEffect(() => {
    localStorage.setItem('lifewood_v3_conversations', JSON.stringify(conversations));
  }, [conversations]);

  useEffect(() => {
    localStorage.setItem('lifewood_system_instruction', systemInstruction);
  }, [systemInstruction]);

  useEffect(() => {
    localStorage.setItem('lifewood_theme', theme);
  }, [theme]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [currentConversation?.messages, isLoading]);

  const startNewChat = () => {
    setActiveId(null);
    setInput('');
    setAttachments([]);
    setIsSidebarOpen(false);
    setSelectedTool(TOOLS[0]);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    Array.from(files).forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        setAttachments(prev => [...prev, {
          data: event.target?.result as string,
          mimeType: file.type,
          fileName: file.name
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleSend = async (overrideInput?: string) => {
    const finalInput = overrideInput || input;
    if ((!finalInput.trim() && attachments.length === 0) || isLoading) return;

    let targetConv = currentConversation;
    if (!targetConv) {
      const newId = Date.now().toString();
      targetConv = {
        id: newId,
        title: finalInput.slice(0, 30) || 'New Lifewood Session',
        messages: [],
        personaId: 'default',
        createdAt: new Date(),
      };
      setConversations(prev => [targetConv!, ...prev]);
      setActiveId(newId);
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      text: finalInput,
      sender: SenderType.USER,
      timestamp: new Date(),
      attachments: [...attachments],
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, userMsg] } : c
    ));

    setInput('');
    setAttachments([]);
    setIsLoading(true);

    const aiResponse = await getGeminiResponse(
      userMsg.text, 
      userMsg.attachments,
      selectedTool.id,
      selectedModel.id,
      systemInstruction
    );

    const aiMsg: Message = {
      id: (Date.now() + 1).toString(),
      text: aiResponse.text,
      generatedImageUrl: aiResponse.generatedImageUrl,
      sender: SenderType.AI,
      timestamp: new Date(),
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, aiMsg] } : c
    ));
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const deleteConversation = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setConversations(prev => prev.filter(c => c.id !== id));
    if (activeId === id) setActiveId(null);
  };

  const suggestedPrompts = [
    { 
      category: 'Strategic Vision', 
      label: 'ASEAN HUB', 
      text: "Conceptualize a logistics-first AI data hub in ASEAN.", 
      tool: 'image',
      icon: '🌐'
    },
    { 
      category: 'Technical Execution', 
      label: 'RLHF QUALITY', 
      text: "Compare data quality benchmarks for multi-lingual RLHF.", 
      tool: 'research',
      icon: '📊'
    },
    { 
      category: 'Brand Value', 
      label: 'ESG GOALS', 
      text: "How does Lifewood's 'Always On' model reduce ESG carbon footprint?", 
      tool: 'chat',
      icon: '🌱'
    }
  ];

  const getThemeClasses = () => {
    switch(theme) {
      case 'dark': return 'bg-[#133020] text-white';
      case 'high-contrast': return 'bg-black text-[#FFB347]';
      default: return 'bg-[#f5eedb] text-[#133020]';
    }
  };

  const getFooterBackground = () => {
    switch(theme) {
      case 'dark': return 'from-[#133020] via-[#133020] to-transparent';
      case 'high-contrast': return 'from-black via-black to-transparent';
      default: return 'from-[#f5eedb] via-[#f5eedb] to-transparent';
    }
  };

  return (
    <div className={`flex h-screen overflow-hidden transition-colors duration-500 ${getThemeClasses()}`}>

      {/* Sidebar - Persistent Storage Access */}
      <aside className={`fixed inset-y-0 left-0 z-[100] w-72 bg-[#133020] transition-transform duration-300 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 flex flex-col shadow-2xl`}>
        <div className="p-8 border-b border-white/5">
          <LifewoodLogo />
          <button 
            onClick={startNewChat}
            className="w-full mt-10 bg-[#046241] hover:bg-[#057a51] text-white py-4 rounded-xl flex items-center justify-center gap-2 font-google font-bold text-xs uppercase tracking-widest transition-all shadow-lg active:scale-95"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M12 4v16m8-8H4"/></svg>
            New Session
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-1 lifewood-scrollbar">
          <h3 className="text-white/30 text-[10px] font-google font-black uppercase tracking-[0.2em] px-4 py-4">Knowledge Base</h3>
          {conversations.map(conv => (
            <div 
              key={conv.id}
              onClick={() => { setActiveId(conv.id); setIsSidebarOpen(false); }}
              className={`group relative px-4 py-3.5 rounded-xl cursor-pointer transition-all flex items-center justify-between ${activeId === conv.id ? 'bg-[#046241] text-white shadow-xl' : 'hover:bg-white/5 text-white/60 hover:text-white'}`}
            >
              <div className="flex-1 min-w-0">
                <div className="text-[13px] font-semibold truncate leading-tight">{conv.title}</div>
                <div className="text-[9px] font-black uppercase tracking-tighter opacity-40 mt-1">{conv.createdAt.toLocaleDateString()}</div>
              </div>
              <button onClick={(e) => deleteConversation(e, conv.id)} className="opacity-0 group-hover:opacity-100 p-2 hover:bg-red-500/20 rounded-lg transition-all text-red-400">
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
              </button>
            </div>
          ))}
        </div>

        <div className="p-6 bg-black/20 border-t border-white/5 space-y-4">
          <button 
            onClick={() => setShowSettings(true)}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-white/5 text-white/40 hover:text-white transition-all text-[10px] font-google font-black uppercase tracking-widest"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37a1.724 1.724 0 002.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            Config
          </button>
        </div>
      </aside>

      {/* Main UI Canvas */}
      <main className={`flex-1 flex flex-col relative h-full transition-all duration-300 ${isSidebarOpen ? 'opacity-20 pointer-events-none lg:opacity-100 lg:pointer-events-auto' : 'opacity-100'}`}>
        <header className="absolute top-0 left-0 right-0 h-16 flex items-center justify-between px-6 z-40">
          <button onClick={() => setIsSidebarOpen(true)} className="p-3 bg-[#133020] text-white rounded-full shadow-xl lg:hidden">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M4 6h16M4 12h16m-7 6h7"/></svg>
          </button>
        </header>

        {/* Scrollable Conversation Container */}
        <div className="flex-1 overflow-y-auto flex flex-col items-center lifewood-scrollbar pb-80 px-6 pt-12">
          {/* Widened to max-w-5xl to push AI responses leftward within the lane */}
          <div className="w-full max-w-5xl space-y-14">

            {(!currentConversation || currentConversation.messages.length === 0) && (
              <div className="mt-16 space-y-12 animate-in fade-in duration-1000 max-w-2xl mx-auto">
                <div className="text-center space-y-6">
                  <h2 className={`text-6xl font-google font-black tracking-tighter ${theme === 'classic' ? 'text-[#046241]' : 'text-[#FFB347]'}`}>
                    Innovation. <br/> <span className={theme === 'classic' ? 'text-[#FFB347]' : 'text-white'}>Verified.</span>
                  </h2>
                  <p className={`text-[11px] font-google font-black uppercase tracking-[0.6em] opacity-30`}>
                    Enterprise Intelligence Engine
                  </p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {suggestedPrompts.map((s, i) => (
                    <button 
                      key={i}
                      onClick={() => { setSelectedTool(TOOLS.find(t => t.id === s.tool) || TOOLS[0]); setInput(s.text); }}
                      className={`group p-6 rounded-[2rem] border transition-all text-left flex flex-col justify-between ${theme === 'classic' ? 'bg-white border-[#133020]/5 hover:border-[#FFB347]' : 'bg-white/5 border-white/10 hover:border-[#FFB347]'}`}
                    >
                      <div>
                        <div className="flex items-center justify-between mb-4">
                           <span className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${theme === 'classic' ? 'bg-[#133020]/5 text-[#133020]/60' : 'bg-white/10 text-white/60'}`}>
                             {s.category}
                           </span>
                           <span className="text-lg opacity-40 group-hover:opacity-100 transition-opacity">{s.icon}</span>
                        </div>
                        <h4 className="text-[10px] font-black uppercase tracking-tighter text-[#FFB347] mb-1">{s.label}</h4>
                        <p className={`text-[13px] font-bold leading-snug ${theme === 'classic' ? 'text-[#133020]' : 'text-white'}`}>{s.text}</p>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {currentConversation?.messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.sender === SenderType.USER ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-4 duration-500`}>
                <div className={`flex gap-6 ${msg.sender === SenderType.USER ? 'flex-row-reverse max-w-[80%]' : 'max-w-[85%]'}`}>
                   {msg.sender === SenderType.AI && (
                     <div className="mt-1 flex-shrink-0">
                       <div className="w-10 h-10 rounded-full bg-[#133020] flex items-center justify-center shadow-lg border border-white/10">
                          <SparkleIcon className="w-5 h-5 fill-[#FFB347]" />
                       </div>
                     </div>
                   )}
                   <div className="flex-1">
                      <div className={`
                        ${msg.sender === SenderType.USER 
                          ? 'bg-[#FFB347] text-[#133020] px-6 py-4 rounded-3xl rounded-tr-none font-google font-bold text-[14px] shadow-lg border border-[#133020]/10' 
                          : `font-serif text-[19px] leading-relaxed tracking-wide opacity-90 py-2 ${theme === 'classic' ? 'text-[#133020]' : 'text-white/90'}`
                        }
                      `}>
                        {msg.text}
                        {msg.generatedImageUrl && (
                          <div className="mt-8 rounded-[2rem] overflow-hidden shadow-2xl border border-white/5 bg-black/10 p-2 max-w-xl">
                            <img src={msg.generatedImageUrl} className="w-full h-auto rounded-[1.8rem]" />
                          </div>
                        )}
                      </div>
                      <div className={`mt-2 text-[9px] font-google font-black uppercase tracking-widest opacity-20 ${msg.sender === SenderType.USER ? 'text-right' : ''}`}>
                        {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </div>
                   </div>
                </div>
              </div>
            ))}

            {isLoading && (
              <div className="flex gap-6 w-full animate-pulse justify-start">
                <div className="w-10 h-10 rounded-full bg-black/10" />
                <div className="flex-1 space-y-4 pt-3">
                  <div className={`h-2.5 rounded-full w-3/4 ${theme === 'classic' ? 'bg-[#133020]/5' : 'bg-white/10'}`}></div>
                  <div className={`h-2.5 rounded-full w-1/2 ${theme === 'classic' ? 'bg-[#133020]/5' : 'bg-white/10'}`}></div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
        </div>

        {/* Interaction Rail - Positioned for Architecture */}
        <div className={`fixed bottom-0 left-0 right-0 pt-32 pb-8 px-8 flex justify-center bg-gradient-to-t ${getFooterBackground()} z-[50] pointer-events-none`}>
          <div className="w-full max-w-3xl pointer-events-auto">

            {attachments.length > 0 && (
              <div className="flex flex-wrap gap-2 mb-4 px-2 animate-in slide-in-from-bottom-2">
                {attachments.map((file, idx) => (
                  <div key={idx} className="relative group bg-white p-1 rounded-xl shadow-lg border border-[#133020]/5 w-20 h-20">
                    <img src={file.data} className="w-full h-full object-cover rounded-lg" />
                    <button onClick={() => setAttachments(prev => prev.filter((_, i) => i !== idx))} className="absolute -top-2 -right-2 bg-[#133020] text-white p-1 rounded-full shadow-md scale-75">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12"/></svg>
                    </button>
                  </div>
                ))}
              </div>
            )}

            <div className={`rounded-[1.5rem] overflow-visible border-none shadow-2xl relative ${theme === 'classic' ? 'bg-white' : 'bg-[#046241]/95 backdrop-blur-2xl border border-white/5'}`}>

              <div className="p-3 flex items-center gap-2 relative">
                {/* Plus/Upload Button */}
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className={`p-3 rounded-xl transition-all active:scale-95 ${theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#133020]/30' : 'hover:bg-white/5 text-white/30'}`}
                >
                  <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M12 4v16m8-8H4"/></svg>
                </button>
                <input type="file" ref={fileInputRef} className="hidden" multiple onChange={handleFileUpload} />

                {/* Tool Selection */}
                <div className="relative">
                  <button 
                    onClick={() => { setShowTools(!showTools); setShowModels(false); }}
                    className={`flex items-center gap-2 px-3 py-2.5 rounded-xl transition-all font-google font-black text-[10px] uppercase tracking-widest active:scale-95 ${showTools ? 'bg-[#FFB347] text-[#133020]' : theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#FFB347]' : 'hover:bg-white/5 text-[#FFB347]'}`}
                  >
                    <SparkleIcon className={`w-3.5 h-3.5 ${showTools ? 'fill-[#133020]' : 'fill-[#FFB347]'}`} />
                    <span className="hidden sm:inline">{selectedTool.name}</span>
                  </button>

                  {showTools && (
                    <div className="absolute bottom-full left-0 mb-4 w-56 bg-[#133020] border border-white/10 rounded-2xl shadow-2xl overflow-hidden popover-enter z-[100]">
                      <div className="p-1 space-y-1">
                        {TOOLS.map(t => (
                          <button
                            key={t.id}
                            onClick={() => { setSelectedTool(t); setShowTools(false); }}
                            className={`w-full text-left p-4 rounded-xl transition-all ${selectedTool.id === t.id ? 'bg-[#046241] text-white shadow-inner' : 'hover:bg-white/5 text-white/60'}`}
                          >
                            <div className="flex items-center gap-2">
                               <span>{t.icon}</span>
                               <div className="text-[10px] font-google font-black uppercase tracking-widest">{t.name}</div>
                            </div>
                          </button>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                <div className="flex-1 min-w-0">
                  <textarea
                    rows={1}
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={handleKeyPress}
                    placeholder={selectedTool.id === 'image' ? "Define visual parameters..." : "Synthesize new request..."}
                    className={`w-full bg-transparent border-none resize-none py-3 px-3 text-[15px] font-google font-bold placeholder-[#133020]/30 focus:ring-0 focus:outline-none ring-0 outline-none max-h-40 no-scrollbar ${theme === 'classic' ? 'text-[#133020]' : 'text-white'}`}
                  />
                </div>

                <div className="flex items-center gap-3 pr-2">
                   {/* Model Label */}
                   <div className="relative">
                     <button 
                        onClick={() => { setShowModels(!showModels); setShowTools(false); }}
                        className={`px-3 py-2 rounded-lg text-[9px] font-google font-black uppercase tracking-widest transition-all ${theme === 'classic' ? 'text-[#133020]/20' : 'text-white/20'}`}
                      >
                        {selectedModel.name}
                      </button>

                      {showModels && (
                        <div className="absolute bottom-full right-0 mb-4 w-56 bg-[#133020] border border-white/10 rounded-2xl shadow-2xl overflow-hidden popover-enter z-[100]">
                          <div className="p-1 space-y-1">
                            {MODELS.map(m => (
                              <button
                                key={m.id}
                                onClick={() => { setSelectedModel(m); setShowModels(false); }}
                                className={`w-full text-left p-4 rounded-xl transition-all ${selectedModel.id === m.id ? 'bg-[#046241] text-white shadow-inner' : 'hover:bg-white/5 text-white/60'}`}
                              >
                                <div className="text-[10px] font-google font-black uppercase tracking-widest">{m.name}</div>
                              </button>
                            ))}
                          </div>
                        </div>
                      )}
                   </div>

                    {/* Architectural Send Button */}
                    <button 
                      disabled={isLoading || (!input.trim() && attachments.length === 0)}
                      onClick={() => handleSend()}
                      className={`p-3.5 rounded-2xl transition-all active:scale-90 ${(!input.trim() && attachments.length === 0) ? 'bg-black/5 text-black/10' : 'bg-black/5 text-[#133020] hover:bg-black/10 shadow-lg'}`}
                    >
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M13.5 4.5L21 12m0 0l-7.5 7.5M21 12H3"/></svg>
                    </button>
                </div>
              </div>
            </div>

            <p className="text-[9px] font-google opacity-20 text-center mt-6 font-black uppercase tracking-[0.4em]">
              Intelligence Authenticated • Lifewood Core
            </p>
          </div>
        </div>
      </main>

      {/* Settings Modal */}
      {showSettings && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className="w-full max-w-xl bg-[#133020] rounded-[2.5rem] overflow-hidden shadow-2xl border border-white/10 text-white animate-in slide-in-from-bottom-4">
            <div className="p-8 border-b border-white/5 flex items-center justify-between">
              <div>
                <h3 className="text-xl font-google font-black uppercase tracking-tighter">Core Directives</h3>
              </div>
              <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M6 18L18 6M6 6l12 12"/></svg>
              </button>
            </div>

            <div className="p-8 space-y-8">
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] opacity-40">System Directives</label>
                <textarea 
                  value={systemInstruction}
                  onChange={(e) => setSystemInstruction(e.target.value)}
                  placeholder="Define how Lifewood Intelligence should behave..."
                  className="w-full h-32 bg-black/40 border border-white/10 rounded-2xl p-4 text-xs font-medium leading-relaxed resize-none focus:border-[#FFB347] transition-all focus:ring-0"
                />
              </div>
            </div>

            <div className="p-8 bg-black/20 flex justify-end">
              <button 
                onClick={() => setShowSettings(false)}
                className="bg-[#FFB347] text-[#133020] px-8 py-3 rounded-xl font-google font-black text-xs uppercase tracking-widest active:scale-95 transition-all shadow-lg"
              >
                Sync Configuration
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Mobile Sidebar Overlay */}
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-[#133020]/40 backdrop-blur-sm z-[90] lg:hidden animate-in fade-in" onClick={() => setIsSidebarOpen(false)}></div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { LifewoodLogo, SparkleIcon, TOOLS, MODELS } from './constants';
import { Message, SenderType, Conversation, FileData } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  // Persistence states
  const [conversations, setConversations] = useState<Conversation[]>(() => {
    const saved = localStorage.getItem('lifewood_v3_conversations');
    return saved ? JSON.parse(saved).map((c: any) => ({
      ...c,
      messages: c.messages.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
      createdAt: new Date(c.createdAt)
    })) : [];
  });

  const [systemInstruction, setSystemInstruction] = useState(() => 
    localStorage.getItem('lifewood_system_instruction') || 'You are Lifewood Intelligence, a proactive innovation partner focusing on AI data strategy and global logistics.'
  );

  const [theme, setTheme] = useState(() => localStorage.getItem('lifewood_theme') || 'classic');

  // UI states
  const [activeId, setActiveId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [attachments, setAttachments] = useState<FileData[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  const [showTools, setShowTools] = useState(false);
  const [selectedTool, setSelectedTool] = useState(TOOLS[0]); // Default is General Chat
  const [showModels, setShowModels] = useState(false);
  const [selectedModel, setSelectedModel] = useState(MODELS[0]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const currentConversation = conversations.find(c => c.id === activeId);

  // Persistence Effects
  useEffect(() => {
    localStorage.setItem('lifewood_v3_conversations', JSON.stringify(conversations));
  }, [conversations]);

  useEffect(() => {
    localStorage.setItem('lifewood_system_instruction', systemInstruction);
  }, [systemInstruction]);

  useEffect(() => {
    localStorage.setItem('lifewood_theme', theme);
  }, [theme]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [currentConversation?.messages, isLoading]);

  const startNewChat = () => {
    setActiveId(null);
    setInput('');
    setAttachments([]);
    setIsSidebarOpen(false);
    setSelectedTool(TOOLS[0]);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    Array.from(files).forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        setAttachments(prev => [...prev, {
          data: event.target?.result as string,
          mimeType: file.type,
          fileName: file.name
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleSend = async (overrideInput?: string) => {
    const finalInput = overrideInput || input;
    if ((!finalInput.trim() && attachments.length === 0) || isLoading) return;

    let targetConv = currentConversation;
    if (!targetConv) {
      const newId = Date.now().toString();
      targetConv = {
        id: newId,
        title: finalInput.slice(0, 30) || 'New Lifewood Session',
        messages: [],
        personaId: 'default',
        createdAt: new Date(),
      };
      setConversations(prev => [targetConv!, ...prev]);
      setActiveId(newId);
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      text: finalInput,
      sender: SenderType.USER,
      timestamp: new Date(),
      attachments: [...attachments],
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, userMsg] } : c
    ));

    setInput('');
    setAttachments([]);
    setIsLoading(true);

    const aiResponse = await getGeminiResponse(
      userMsg.text, 
      userMsg.attachments,
      selectedTool.id,
      selectedModel.id,
      systemInstruction
    );

    const aiMsg: Message = {
      id: (Date.now() + 1).toString(),
      text: aiResponse.text,
      generatedImageUrl: aiResponse.generatedImageUrl,
      sender: SenderType.AI,
      timestamp: new Date(),
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, aiMsg] } : c
    ));
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const deleteConversation = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setConversations(prev => prev.filter(c => c.id !== id));
    if (activeId === id) setActiveId(null);
  };

  const suggestedPrompts = [
    { 
      category: 'Strategic Vision', 
      label: 'ASEAN HUB', 
      text: "Conceptualize a logistics-first AI data hub in ASEAN.", 
      tool: 'image',
      icon: '🌐'
    },
    { 
      category: 'Technical Execution', 
      label: 'RLHF QUALITY', 
      text: "Compare data quality benchmarks for multi-lingual RLHF.", 
      tool: 'research',
      icon: '📊'
    },
    { 
      category: 'Brand Value', 
      label: 'ESG GOALS', 
      text: "How does Lifewood's 'Always On' model reduce ESG carbon footprint?", 
      tool: 'chat',
      icon: '🌱'
    }
  ];

  const getThemeClasses = () => {
    switch(theme) {
      case 'dark': return 'bg-[#133020] text-white';
      case 'high-contrast': return 'bg-black text-[#FFB347]';
      default: return 'bg-[#f5eedb] text-[#133020]';
    }
  };

  const getFooterBackground = () => {
    switch(theme) {
      case 'dark': return 'from-[#133020] via-[#133020] to-transparent';
      case 'high-contrast': return 'from-black via-black to-transparent';
      default: return 'from-[#f5eedb] via-[#f5eedb] to-transparent';
    }
  };

  const getNavbarClasses = () => {
    switch(theme) {
      case 'dark': return 'bg-[#133020]/80 border-white/5';
      case 'high-contrast': return 'bg-black/80 border-white/10';
      default: return 'bg-[#f5eedb]/80 border-[#133020]/5';
    }
  };

  return (
    <div className={`flex h-screen overflow-hidden transition-colors duration-500 ${getThemeClasses()}`}>

      {/* Sidebar - Persistent Storage Access */}
      <aside className={`fixed inset-y-0 left-0 z-[100] w-72 bg-[#133020] transition-transform duration-300 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 flex flex-col shadow-2xl`}>
        <div className="p-8 border-b border-white/5">
          <LifewoodLogo />
          <button 
            onClick={startNewChat}
            className="w-full mt-10 bg-[#046241] hover:bg-[#057a51] text-white py-4 rounded-xl flex items-center justify-center gap-2 font-google font-bold text-xs uppercase tracking-widest transition-all shadow-lg active:scale-95"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M12 4v16m8-8H4"/></svg>
            New Session
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-1 lifewood-scrollbar">
          <h3 className="text-white/30 text-[10px] font-google font-black uppercase tracking-[0.2em] px-4 py-4">Knowledge Base</h3>
          {conversations.map(conv => (
            <div 
              key={conv.id}
              onClick={() => { setActiveId(conv.id); setIsSidebarOpen(false); }}
              className={`group relative px-4 py-3.5 rounded-xl cursor-pointer transition-all flex items-center justify-between ${activeId === conv.id ? 'bg-[#046241] text-white shadow-xl' : 'hover:bg-white/5 text-white/60 hover:text-white'}`}
            >
              <div className="flex-1 min-w-0">
                <div className="text-[13px] font-semibold truncate leading-tight">{conv.title}</div>
                <div className="text-[9px] font-black uppercase tracking-tighter opacity-40 mt-1">{conv.createdAt.toLocaleDateString()}</div>
              </div>
              <button onClick={(e) => deleteConversation(e, conv.id)} className="opacity-0 group-hover:opacity-100 p-2 hover:bg-red-500/20 rounded-lg transition-all text-red-400">
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
              </button>
            </div>
          ))}
        </div>

        <div className="p-6 bg-black/20 border-t border-white/5 space-y-4">
          <button 
            onClick={() => setShowSettings(true)}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-white/5 text-white/40 hover:text-white transition-all text-[10px] font-google font-black uppercase tracking-widest"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37a1.724 1.724 0 002.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            Config
          </button>
        </div>
      </aside>

      {/* Main UI Canvas */}
      <main className={`flex-1 flex flex-col relative h-full transition-all duration-300 ${isSidebarOpen ? 'opacity-20 pointer-events-none lg:opacity-100 lg:pointer-events-auto' : 'opacity-100'}`}>

        {/* Architectural Navbar - Centered Convo Title */}
        <header className={`sticky top-0 left-0 right-0 h-16 flex items-center justify-between px-6 z-40 backdrop-blur-md border-b transition-all duration-500 ${getNavbarClasses()}`}>
          <div className="flex-1 flex items-center">
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 bg-[#133020] text-white rounded-lg shadow-xl lg:hidden">
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M4 6h16M4 12h16m-7 6h7"/></svg>
            </button>
          </div>

          <div className="flex-1 flex justify-center">
            {currentConversation && (
              <h1 className="text-[10px] font-google font-black uppercase tracking-[0.4em] opacity-40 truncate max-w-[200px] sm:max-w-md text-center">
                {currentConversation.title}
              </h1>
            )}
          </div>

          <div className="flex-1 flex justify-end">
            <div className="hidden sm:flex items-center gap-2">
               <span className="text-[8px] font-black uppercase tracking-widest opacity-20">Secure Instance</span>
               <div className="w-1.5 h-1.5 rounded-full bg-[#046241]"></div>
            </div>
          </div>
        </header>

        {/* Scrollable Conversation Container */}
        <div className="flex-1 overflow-y-auto flex flex-col items-center lifewood-scrollbar pb-80 px-6 pt-12">
          {/* Widened to max-w-5xl to push AI responses leftward within the lane */}
          <div className="w-full max-w-5xl space-y-14">

            {(!currentConversation || currentConversation.messages.length === 0) && (
              <div className="mt-16 space-y-12 animate-in fade-in duration-1000 max-w-2xl mx-auto">
                <div className="text-center space-y-6">
                  <h2 className={`text-6xl font-google font-black tracking-tighter ${theme === 'classic' ? 'text-[#046241]' : 'text-[#FFB347]'}`}>
                    Innovation. <br/> <span className={theme === 'classic' ? 'text-[#FFB347]' : 'text-white'}>Verified.</span>
                  </h2>
                  <p className={`text-[11px] font-google font-black uppercase tracking-[0.6em] opacity-30`}>
                    Enterprise Intelligence Engine
                  </p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {suggestedPrompts.map((s, i) => (
                    <button 
                      key={i}
                      onClick={() => { setSelectedTool(TOOLS.find(t => t.id === s.tool) || TOOLS[0]); setInput(s.text); }}
                      className={`group p-6 rounded-[2rem] border transition-all text-left flex flex-col justify-between ${theme === 'classic' ? 'bg-white border-[#133020]/5 hover:border-[#FFB347]' : 'bg-white/5 border-white/10 hover:border-[#FFB347]'}`}
                    >
                      <div>
                        <div className="flex items-center justify-between mb-4">
                           <span className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${theme === 'classic' ? 'bg-[#133020]/5 text-[#133020]/60' : 'bg-white/10 text-white/60'}`}>
                             {s.category}
                           </span>
                           <span className="text-lg opacity-40 group-hover:opacity-100 transition-opacity">{s.icon}</span>
                        </div>
                        <h4 className="text-[10px] font-black uppercase tracking-tighter text-[#FFB347] mb-1">{s.label}</h4>
                        <p className={`text-[13px] font-bold leading-snug ${theme === 'classic' ? 'text-[#133020]' : 'text-white'}`}>{s.text}</p>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {currentConversation?.messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.sender === SenderType.USER ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-4 duration-500`}>
                <div className={`flex gap-6 ${msg.sender === SenderType.USER ? 'flex-row-reverse max-w-[80%]' : 'max-w-[85%]'}`}>
                   {msg.sender === SenderType.AI && (
                     <div className="mt-1 flex-shrink-0">
                       <div className="w-10 h-10 rounded-full bg-[#133020] flex items-center justify-center shadow-lg border border-white/10">
                          <SparkleIcon className="w-5 h-5 fill-[#FFB347]" />
                       </div>
                     </div>
                   )}
                   <div className="flex-1">
                      <div className={`
                        ${msg.sender === SenderType.USER 
                          ? 'bg-[#FFB347] text-[#133020] px-6 py-4 rounded-3xl rounded-tr-none font-google font-bold text-[14px] shadow-lg border border-[#133020]/10' 
                          : `font-serif text-[19px] leading-relaxed tracking-wide opacity-90 py-2 ${theme === 'classic' ? 'text-[#133020]' : 'text-white/90'}`
                        }
                      `}>
                        {msg.text}
                        {msg.generatedImageUrl && (
                          <div className="mt-8 rounded-[2rem] overflow-hidden shadow-2xl border border-white/5 bg-black/10 p-2 max-w-xl">
                            <img src={msg.generatedImageUrl} className="w-full h-auto rounded-[1.8rem]" />
                          </div>
                        )}
                      </div>
                      <div className={`mt-2 text-[9px] font-google font-black uppercase tracking-widest opacity-20 ${msg.sender === SenderType.USER ? 'text-right' : ''}`}>
                        {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </div>
                   </div>
                </div>
              </div>
            ))}

            {isLoading && (
              <div className="flex gap-6 w-full animate-pulse justify-start">
                <div className="w-10 h-10 rounded-full bg-black/10" />
                <div className="flex-1 space-y-4 pt-3">
                  <div className={`h-2.5 rounded-full w-3/4 ${theme === 'classic' ? 'bg-[#133020]/5' : 'bg-white/10'}`}></div>
                  <div className={`h-2.5 rounded-full w-1/2 ${theme === 'classic' ? 'bg-[#133020]/5' : 'bg-white/10'}`}></div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
        </div>

        {/* Interaction Rail - Positioned for Architecture */}
        <div className={`fixed bottom-0 left-0 right-0 pt-32 pb-8 px-8 flex justify-center bg-gradient-to-t ${getFooterBackground()} z-[50] pointer-events-none`}>
          <div className="w-full max-w-3xl pointer-events-auto">

            {attachments.length > 0 && (
              <div className="flex flex-wrap gap-2 mb-4 px-2 animate-in slide-in-from-bottom-2">
                {attachments.map((file, idx) => (
                  <div key={idx} className="relative group bg-white p-1 rounded-xl shadow-lg border border-[#133020]/5 w-20 h-20">
                    <img src={file.data} className="w-full h-full object-cover rounded-lg" />
                    <button onClick={() => setAttachments(prev => prev.filter((_, i) => i !== idx))} className="absolute -top-2 -right-2 bg-[#133020] text-white p-1 rounded-full shadow-md scale-75">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12"/></svg>
                    </button>
                  </div>
                ))}
              </div>
            )}

            <div className={`rounded-[1.5rem] overflow-visible border-none shadow-2xl relative ${theme === 'classic' ? 'bg-white' : 'bg-[#046241]/95 backdrop-blur-2xl border border-white/5'}`}>

              <div className="p-3 flex items-center gap-2 relative">
                {/* Plus/Upload Button */}
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className={`p-3 rounded-xl transition-all active:scale-95 ${theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#133020]/30' : 'hover:bg-white/5 text-white/30'}`}
                >
                  <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M12 4v16m8-8H4"/></svg>
                </button>
                <input type="file" ref={fileInputRef} className="hidden" multiple onChange={handleFileUpload} />

                {/* Tool Selection */}
                <div className="relative">
                  <button 
                    onClick={() => { setShowTools(!showTools); setShowModels(false); }}
                    className={`flex items-center gap-2 px-3 py-2.5 rounded-xl transition-all font-google font-black text-[10px] uppercase tracking-widest active:scale-95 ${showTools ? 'bg-[#FFB347] text-[#133020]' : theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#FFB347]' : 'hover:bg-white/5 text-[#FFB347]'}`}
                  >
                    <SparkleIcon className={`w-3.5 h-3.5 ${showTools ? 'fill-[#133020]' : 'fill-[#FFB347]'}`} />
                    <span className="hidden sm:inline">{selectedTool.name}</span>
                  </button>

                  {showTools && (
                    <div className="absolute bottom-full left-0 mb-4 w-56 bg-[#133020] border border-white/10 rounded-2xl shadow-2xl overflow-hidden popover-enter z-[100]">
                      <div className="p-1 space-y-1">
                        {TOOLS.map(t => (
                          <button
                            key={t.id}
                            onClick={() => { setSelectedTool(t); setShowTools(false); }}
                            className={`w-full text-left p-4 rounded-xl transition-all ${selectedTool.id === t.id ? 'bg-[#046241] text-white shadow-inner' : 'hover:bg-white/5 text-white/60'}`}
                          >
                            <div className="flex items-center gap-2">
                               <span>{t.icon}</span>
                               <div className="text-[10px] font-google font-black uppercase tracking-widest">{t.name}</div>
                            </div>
                          </button>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                <div className="flex-1 min-w-0">
                  <textarea
                    rows={1}
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={handleKeyPress}
                    placeholder={selectedTool.id === 'image' ? "Define visual parameters..." : "Synthesize new request..."}
                    className={`w-full bg-transparent border-none resize-none py-3 px-3 text-[15px] font-google font-bold placeholder-[#133020]/30 focus:ring-0 focus:outline-none ring-0 outline-none max-h-40 no-scrollbar ${theme === 'classic' ? 'text-[#133020]' : 'text-white'}`}
                  />
                </div>

                <div className="flex items-center gap-3 pr-2">
                   {/* Model Label */}
                   <div className="relative">
                     <button 
                        onClick={() => { setShowModels(!showModels); setShowTools(false); }}
                        className={`px-3 py-2 rounded-lg text-[9px] font-google font-black uppercase tracking-widest transition-all ${theme === 'classic' ? 'text-[#133020]/20' : 'text-white/20'}`}
                      >
                        {selectedModel.name}
                      </button>

                      {showModels && (
                        <div className="absolute bottom-full right-0 mb-4 w-56 bg-[#133020] border border-white/10 rounded-2xl shadow-2xl overflow-hidden popover-enter z-[100]">
                          <div className="p-1 space-y-1">
                            {MODELS.map(m => (
                              <button
                                key={m.id}
                                onClick={() => { setSelectedModel(m); setShowModels(false); }}
                                className={`w-full text-left p-4 rounded-xl transition-all ${selectedModel.id === m.id ? 'bg-[#046241] text-white shadow-inner' : 'hover:bg-white/5 text-white/60'}`}
                              >
                                <div className="text-[10px] font-google font-black uppercase tracking-widest">{m.name}</div>
                              </button>
                            ))}
                          </div>
                        </div>
                      )}
                   </div>

                    {/* Architectural Send Button */}
                    <button 
                      disabled={isLoading || (!input.trim() && attachments.length === 0)}
                      onClick={() => handleSend()}
                      className={`p-3.5 rounded-2xl transition-all active:scale-90 ${(!input.trim() && attachments.length === 0) ? 'bg-black/5 text-black/10' : 'bg-black/5 text-[#133020] hover:bg-black/10 shadow-lg'}`}
                    >
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M13.5 4.5L21 12m0 0l-7.5 7.5M21 12H3"/></svg>
                    </button>
                </div>
              </div>
            </div>

            <p className="text-[9px] font-google opacity-20 text-center mt-6 font-black uppercase tracking-[0.4em]">
              Intelligence Authenticated • Lifewood Core
            </p>
          </div>
        </div>
      </main>

      {/* Settings Modal */}
      {showSettings && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className="w-full max-w-xl bg-[#133020] rounded-[2.5rem] overflow-hidden shadow-2xl border border-white/10 text-white animate-in slide-in-from-bottom-4">
            <div className="p-8 border-b border-white/5 flex items-center justify-between">
              <div>
                <h3 className="text-xl font-google font-black uppercase tracking-tighter">Core Directives</h3>
              </div>
              <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M6 18L18 6M6 6l12 12"/></svg>
              </button>
            </div>

            <div className="p-8 space-y-8">
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] opacity-40">System Directives</label>
                <textarea 
                  value={systemInstruction}
                  onChange={(e) => setSystemInstruction(e.target.value)}
                  placeholder="Define how Lifewood Intelligence should behave..."
                  className="w-full h-32 bg-black/40 border border-white/10 rounded-2xl p-4 text-xs font-medium leading-relaxed resize-none focus:border-[#FFB347] transition-all focus:ring-0"
                />
              </div>
            </div>

            <div className="p-8 bg-black/20 flex justify-end">
              <button 
                onClick={() => setShowSettings(false)}
                className="bg-[#FFB347] text-[#133020] px-8 py-3 rounded-xl font-google font-black text-xs uppercase tracking-widest active:scale-95 transition-all shadow-lg"
              >
                Sync Configuration
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Mobile Sidebar Overlay */}
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-[#133020]/40 backdrop-blur-sm z-[90] lg:hidden animate-in fade-in" onClick={() => setIsSidebarOpen(false)}></div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { LifewoodLogo, SparkleIcon, TOOLS, MODELS } from './constants';
import { Message, SenderType, Conversation, FileData } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  // Persistence states
  const [conversations, setConversations] = useState<Conversation[]>(() => {
    const saved = localStorage.getItem('lifewood_v3_conversations');
    return saved ? JSON.parse(saved).map((c: any) => ({
      ...c,
      messages: c.messages.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
      createdAt: new Date(c.createdAt)
    })) : [];
  });

  const [systemInstruction, setSystemInstruction] = useState(() => 
    localStorage.getItem('lifewood_system_instruction') || 'You are Lifewood Intelligence, a proactive innovation partner focusing on AI data strategy and global logistics.'
  );

  const [theme, setTheme] = useState(() => localStorage.getItem('lifewood_theme') || 'classic');

  // UI states
  const [activeId, setActiveId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [attachments, setAttachments] = useState<FileData[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  const [showTools, setShowTools] = useState(false);
  const [selectedTool, setSelectedTool] = useState(TOOLS[0]); // Default is General Chat
  const [showModels, setShowModels] = useState(false);
  const [selectedModel, setSelectedModel] = useState(MODELS[0]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const currentConversation = conversations.find(c => c.id === activeId);

  // Persistence Effects
  useEffect(() => {
    localStorage.setItem('lifewood_v3_conversations', JSON.stringify(conversations));
  }, [conversations]);

  useEffect(() => {
    localStorage.setItem('lifewood_system_instruction', systemInstruction);
  }, [systemInstruction]);

  useEffect(() => {
    localStorage.setItem('lifewood_theme', theme);
  }, [theme]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [currentConversation?.messages, isLoading]);

  const startNewChat = () => {
    setActiveId(null);
    setInput('');
    setAttachments([]);
    setIsSidebarOpen(false);
    setSelectedTool(TOOLS[0]);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    Array.from(files).forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        setAttachments(prev => [...prev, {
          data: event.target?.result as string,
          mimeType: file.type,
          fileName: file.name
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleSend = async (overrideInput?: string) => {
    const finalInput = overrideInput || input;
    if ((!finalInput.trim() && attachments.length === 0) || isLoading) return;

    let targetConv = currentConversation;
    if (!targetConv) {
      const newId = Date.now().toString();
      targetConv = {
        id: newId,
        title: finalInput.slice(0, 30) || 'New Lifewood Session',
        messages: [],
        personaId: 'default',
        createdAt: new Date(),
      };
      setConversations(prev => [targetConv!, ...prev]);
      setActiveId(newId);
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      text: finalInput,
      sender: SenderType.USER,
      timestamp: new Date(),
      attachments: [...attachments],
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, userMsg] } : c
    ));

    setInput('');
    setAttachments([]);
    setIsLoading(true);

    const aiResponse = await getGeminiResponse(
      userMsg.text, 
      userMsg.attachments,
      selectedTool.id,
      selectedModel.id,
      systemInstruction
    );

    const aiMsg: Message = {
      id: (Date.now() + 1).toString(),
      text: aiResponse.text,
      generatedImageUrl: aiResponse.generatedImageUrl,
      sender: SenderType.AI,
      timestamp: new Date(),
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, aiMsg] } : c
    ));
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const deleteConversation = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setConversations(prev => prev.filter(c => c.id !== id));
    if (activeId === id) setActiveId(null);
  };

  const suggestedPrompts = [
    { 
      category: 'Strategic Vision', 
      label: 'ASEAN HUB', 
      text: "Conceptualize a logistics-first AI data hub in ASEAN.", 
      tool: 'image',
      icon: '🌐'
    },
    { 
      category: 'Technical Execution', 
      label: 'RLHF QUALITY', 
      text: "Compare data quality benchmarks for multi-lingual RLHF.", 
      tool: 'research',
      icon: '📊'
    },
    { 
      category: 'Brand Value', 
      label: 'ESG GOALS', 
      text: "How does Lifewood's 'Always On' model reduce ESG carbon footprint?", 
      tool: 'chat',
      icon: '🌱'
    }
  ];

  const getThemeClasses = () => {
    switch(theme) {
      case 'dark': return 'bg-[#133020] text-white';
      case 'high-contrast': return 'bg-black text-[#FFB347]';
      default: return 'bg-[#f5eedb] text-[#133020]';
    }
  };

  const getFooterBackground = () => {
    switch(theme) {
      case 'dark': return 'from-[#133020] via-[#133020] to-transparent';
      case 'high-contrast': return 'from-black via-black to-transparent';
      default: return 'from-[#f5eedb] via-[#f5eedb] to-transparent';
    }
  };

  const getNavbarClasses = () => {
    switch(theme) {
      case 'dark': return 'bg-[#133020]/80 border-white/5';
      case 'high-contrast': return 'bg-black/80 border-white/10';
      default: return 'bg-[#f5eedb]/80 border-[#133020]/5';
    }
  };

  return (
    <div className={`flex h-screen overflow-hidden transition-colors duration-500 ${getThemeClasses()}`}>

      {/* Sidebar - Persistent Storage Access */}
      <aside className={`fixed inset-y-0 left-0 z-[100] w-72 bg-[#133020] transition-transform duration-300 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 flex flex-col shadow-2xl`}>
        <div className="p-8 border-b border-white/5">
          <LifewoodLogo />
          <button 
            onClick={startNewChat}
            className="w-full mt-10 bg-[#046241] hover:bg-[#057a51] text-white py-4 rounded-xl flex items-center justify-center gap-2 font-google font-bold text-xs uppercase tracking-widest transition-all shadow-lg active:scale-95"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M12 4v16m8-8H4"/></svg>
            New Session
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-1 lifewood-scrollbar">
          <h3 className="text-white/30 text-[10px] font-google font-black uppercase tracking-[0.2em] px-4 py-4">Knowledge Base</h3>
          {conversations.map(conv => (
            <div 
              key={conv.id}
              onClick={() => { setActiveId(conv.id); setIsSidebarOpen(false); }}
              className={`group relative px-4 py-3.5 rounded-xl cursor-pointer transition-all flex items-center justify-between ${activeId === conv.id ? 'bg-[#046241] text-white shadow-xl' : 'hover:bg-white/5 text-white/60 hover:text-white'}`}
            >
              <div className="flex-1 min-w-0">
                <div className="text-[13px] font-semibold truncate leading-tight">{conv.title}</div>
                <div className="text-[9px] font-black uppercase tracking-tighter opacity-40 mt-1">{conv.createdAt.toLocaleDateString()}</div>
              </div>
              <button onClick={(e) => deleteConversation(e, conv.id)} className="opacity-0 group-hover:opacity-100 p-2 hover:bg-red-500/20 rounded-lg transition-all text-red-400">
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
              </button>
            </div>
          ))}
        </div>

        <div className="p-6 bg-black/20 border-t border-white/5 space-y-4">
          <button 
            onClick={() => setShowSettings(true)}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-white/5 text-white/40 hover:text-white transition-all text-[10px] font-google font-black uppercase tracking-widest"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37a1.724 1.724 0 002.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            Config
          </button>
        </div>
      </aside>

      {/* Main UI Canvas */}
      <main className={`flex-1 flex flex-col relative h-full transition-all duration-300 ${isSidebarOpen ? 'opacity-20 pointer-events-none lg:opacity-100 lg:pointer-events-auto' : 'opacity-100'}`}>

        {/* Architectural Navbar - Centered Convo Title */}
        <header className={`sticky top-0 left-0 right-0 h-16 flex items-center justify-between px-6 z-40 backdrop-blur-md border-b transition-all duration-500 ${getNavbarClasses()}`}>
          <div className="flex-1 flex items-center">
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 bg-[#133020] text-white rounded-lg shadow-xl lg:hidden">
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M4 6h16M4 12h16m-7 6h7"/></svg>
            </button>
          </div>

          <div className="flex-1 flex justify-center">
            {currentConversation && (
              <h1 className="text-[10px] font-google font-black uppercase tracking-[0.4em] opacity-40 truncate max-w-[200px] sm:max-w-md text-center">
                {currentConversation.title}
              </h1>
            )}
          </div>

          <div className="flex-1 flex justify-end">
            <div className="hidden sm:flex items-center gap-2">
               <span className="text-[8px] font-black uppercase tracking-widest opacity-20">Secure Instance</span>
               <div className="w-1.5 h-1.5 rounded-full bg-[#046241]"></div>
            </div>
          </div>
        </header>

        {/* Scrollable Conversation Container - PADDING TOP INCREASED TO MOVE REPLY LOWER */}
        <div className="flex-1 overflow-y-auto flex flex-col items-center lifewood-scrollbar pb-80 px-6 pt-32">
          {/* Widened to max-w-5xl to push AI responses leftward within the lane */}
          <div className="w-full max-w-5xl space-y-14">

            {(!currentConversation || currentConversation.messages.length === 0) && (
              <div className="mt-16 space-y-12 animate-in fade-in duration-1000 max-w-2xl mx-auto">
                <div className="text-center space-y-6">
                  <h2 className={`text-6xl font-google font-black tracking-tighter ${theme === 'classic' ? 'text-[#046241]' : 'text-[#FFB347]'}`}>
                    Innovation. <br/> <span className={theme === 'classic' ? 'text-[#FFB347]' : 'text-white'}>Verified.</span>
                  </h2>
                  <p className={`text-[11px] font-google font-black uppercase tracking-[0.6em] opacity-30`}>
                    Enterprise Intelligence Engine
                  </p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {suggestedPrompts.map((s, i) => (
                    <button 
                      key={i}
                      onClick={() => { setSelectedTool(TOOLS.find(t => t.id === s.tool) || TOOLS[0]); setInput(s.text); }}
                      className={`group p-6 rounded-[2rem] border transition-all text-left flex flex-col justify-between ${theme === 'classic' ? 'bg-white border-[#133020]/5 hover:border-[#FFB347]' : 'bg-white/5 border-white/10 hover:border-[#FFB347]'}`}
                    >
                      <div>
                        <div className="flex items-center justify-between mb-4">
                           <span className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${theme === 'classic' ? 'bg-[#133020]/5 text-[#133020]/60' : 'bg-white/10 text-white/60'}`}>
                             {s.category}
                           </span>
                           <span className="text-lg opacity-40 group-hover:opacity-100 transition-opacity">{s.icon}</span>
                        </div>
                        <h4 className="text-[10px] font-black uppercase tracking-tighter text-[#FFB347] mb-1">{s.label}</h4>
                        <p className={`text-[13px] font-bold leading-snug ${theme === 'classic' ? 'text-[#133020]' : 'text-white'}`}>{s.text}</p>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {currentConversation?.messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.sender === SenderType.USER ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-4 duration-500`}>
                <div className={`flex gap-6 ${msg.sender === SenderType.USER ? 'flex-row-reverse max-w-[80%]' : 'max-w-[85%]'}`}>
                   {msg.sender === SenderType.AI && (
                     <div className="mt-1 flex-shrink-0">
                       <div className="w-10 h-10 rounded-full bg-[#133020] flex items-center justify-center shadow-lg border border-white/10">
                          <SparkleIcon className="w-5 h-5 fill-[#FFB347]" />
                       </div>
                     </div>
                   )}
                   <div className="flex-1">
                      <div className={`
                        ${msg.sender === SenderType.USER 
                          ? 'bg-[#FFB347] text-[#133020] px-6 py-4 rounded-3xl rounded-tr-none font-google font-bold text-[14px] shadow-lg border border-[#133020]/10' 
                          : `font-serif text-[19px] leading-relaxed tracking-wide opacity-90 py-2 ${theme === 'classic' ? 'text-[#133020]' : 'text-white/90'}`
                        }
                      `}>
                        {msg.text}
                        {msg.generatedImageUrl && (
                          <div className="mt-8 rounded-[2rem] overflow-hidden shadow-2xl border border-white/5 bg-black/10 p-2 max-w-xl">
                            <img src={msg.generatedImageUrl} className="w-full h-auto rounded-[1.8rem]" />
                          </div>
                        )}
                      </div>
                      <div className={`mt-2 text-[9px] font-google font-black uppercase tracking-widest opacity-20 ${msg.sender === SenderType.USER ? 'text-right' : ''}`}>
                        {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </div>
                   </div>
                </div>
              </div>
            ))}

            {isLoading && (
              <div className="flex gap-6 w-full animate-pulse justify-start">
                <div className="w-10 h-10 rounded-full bg-black/10" />
                <div className="flex-1 space-y-4 pt-3">
                  <div className={`h-2.5 rounded-full w-3/4 ${theme === 'classic' ? 'bg-[#133020]/5' : 'bg-white/10'}`}></div>
                  <div className={`h-2.5 rounded-full w-1/2 ${theme === 'classic' ? 'bg-[#133020]/5' : 'bg-white/10'}`}></div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
        </div>

        {/* Interaction Rail - Positioned for Architecture */}
        <div className={`fixed bottom-0 left-0 right-0 pt-32 pb-8 px-8 flex justify-center bg-gradient-to-t ${getFooterBackground()} z-[50] pointer-events-none`}>
          <div className="w-full max-w-3xl pointer-events-auto">

            {attachments.length > 0 && (
              <div className="flex flex-wrap gap-2 mb-4 px-2 animate-in slide-in-from-bottom-2">
                {attachments.map((file, idx) => (
                  <div key={idx} className="relative group bg-white p-1 rounded-xl shadow-lg border border-[#133020]/5 w-20 h-20">
                    <img src={file.data} className="w-full h-full object-cover rounded-lg" />
                    <button onClick={() => setAttachments(prev => prev.filter((_, i) => i !== idx))} className="absolute -top-2 -right-2 bg-[#133020] text-white p-1 rounded-full shadow-md scale-75">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12"/></svg>
                    </button>
                  </div>
                ))}
              </div>
            )}

            <div className={`rounded-[1.5rem] overflow-visible border-none shadow-2xl relative ${theme === 'classic' ? 'bg-white' : 'bg-[#046241]/95 backdrop-blur-2xl border border-white/5'}`}>

              <div className="p-3 flex items-center gap-2 relative">
                {/* Plus/Upload Button */}
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className={`p-3 rounded-xl transition-all active:scale-95 ${theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#133020]/30' : 'hover:bg-white/5 text-white/30'}`}
                >
                  <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M12 4v16m8-8H4"/></svg>
                </button>
                <input type="file" ref={fileInputRef} className="hidden" multiple onChange={handleFileUpload} />

                {/* Tool Selection */}
                <div className="relative">
                  <button 
                    onClick={() => { setShowTools(!showTools); setShowModels(false); }}
                    className={`flex items-center gap-2 px-3 py-2.5 rounded-xl transition-all font-google font-black text-[10px] uppercase tracking-widest active:scale-95 ${showTools ? 'bg-[#FFB347] text-[#133020]' : theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#FFB347]' : 'hover:bg-white/5 text-[#FFB347]'}`}
                  >
                    <SparkleIcon className={`w-3.5 h-3.5 ${showTools ? 'fill-[#133020]' : 'fill-[#FFB347]'}`} />
                    <span className="hidden sm:inline">{selectedTool.name}</span>
                  </button>

                  {showTools && (
                    <div className="absolute bottom-full left-0 mb-4 w-56 bg-[#133020] border border-white/10 rounded-2xl shadow-2xl overflow-hidden popover-enter z-[100]">
                      <div className="p-1 space-y-1">
                        {TOOLS.map(t => (
                          <button
                            key={t.id}
                            onClick={() => { setSelectedTool(t); setShowTools(false); }}
                            className={`w-full text-left p-4 rounded-xl transition-all ${selectedTool.id === t.id ? 'bg-[#046241] text-white shadow-inner' : 'hover:bg-white/5 text-white/60'}`}
                          >
                            <div className="flex items-center gap-2">
                               <span>{t.icon}</span>
                               <div className="text-[10px] font-google font-black uppercase tracking-widest">{t.name}</div>
                            </div>
                          </button>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                <div className="flex-1 min-w-0">
                  <textarea
                    rows={1}
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={handleKeyPress}
                    placeholder={selectedTool.id === 'image' ? "Define visual parameters..." : "Synthesize new request..."}
                    className={`w-full bg-transparent border-none resize-none py-3 px-3 text-[15px] font-google font-bold placeholder-[#133020]/30 focus:ring-0 focus:outline-none ring-0 outline-none max-h-40 no-scrollbar ${theme === 'classic' ? 'text-[#133020]' : 'text-white'}`}
                  />
                </div>

                <div className="flex items-center gap-3 pr-2">
                   {/* Model Label */}
                   <div className="relative">
                     <button 
                        onClick={() => { setShowModels(!showModels); setShowTools(false); }}
                        className={`px-3 py-2 rounded-lg text-[9px] font-google font-black uppercase tracking-widest transition-all ${theme === 'classic' ? 'text-[#133020]/20' : 'text-white/20'}`}
                      >
                        {selectedModel.name}
                      </button>

                      {showModels && (
                        <div className="absolute bottom-full right-0 mb-4 w-56 bg-[#133020] border border-white/10 rounded-2xl shadow-2xl overflow-hidden popover-enter z-[100]">
                          <div className="p-1 space-y-1">
                            {MODELS.map(m => (
                              <button
                                key={m.id}
                                onClick={() => { setSelectedModel(m); setShowModels(false); }}
                                className={`w-full text-left p-4 rounded-xl transition-all ${selectedModel.id === m.id ? 'bg-[#046241] text-white shadow-inner' : 'hover:bg-white/5 text-white/60'}`}
                              >
                                <div className="text-[10px] font-google font-black uppercase tracking-widest">{m.name}</div>
                              </button>
                            ))}
                          </div>
                        </div>
                      )}
                   </div>

                    {/* Architectural Send Button */}
                    <button 
                      disabled={isLoading || (!input.trim() && attachments.length === 0)}
                      onClick={() => handleSend()}
                      className={`p-3.5 rounded-2xl transition-all active:scale-90 ${(!input.trim() && attachments.length === 0) ? 'bg-black/5 text-black/10' : 'bg-black/5 text-[#133020] hover:bg-black/10 shadow-lg'}`}
                    >
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M13.5 4.5L21 12m0 0l-7.5 7.5M21 12H3"/></svg>
                    </button>
                </div>
              </div>
            </div>

            <p className="text-[9px] font-google opacity-20 text-center mt-6 font-black uppercase tracking-[0.4em]">
              Intelligence Authenticated • Lifewood Core
            </p>
          </div>
        </div>
      </main>

      {/* Settings Modal */}
      {showSettings && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className="w-full max-w-xl bg-[#133020] rounded-[2.5rem] overflow-hidden shadow-2xl border border-white/10 text-white animate-in slide-in-from-bottom-4">
            <div className="p-8 border-b border-white/5 flex items-center justify-between">
              <div>
                <h3 className="text-xl font-google font-black uppercase tracking-tighter">Core Directives</h3>
              </div>
              <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M6 18L18 6M6 6l12 12"/></svg>
              </button>
            </div>

            <div className="p-8 space-y-8">
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] opacity-40">System Directives</label>
                <textarea 
                  value={systemInstruction}
                  onChange={(e) => setSystemInstruction(e.target.value)}
                  placeholder="Define how Lifewood Intelligence should behave..."
                  className="w-full h-32 bg-black/40 border border-white/10 rounded-2xl p-4 text-xs font-medium leading-relaxed resize-none focus:border-[#FFB347] transition-all focus:ring-0"
                />
              </div>
            </div>

            <div className="p-8 bg-black/20 flex justify-end">
              <button 
                onClick={() => setShowSettings(false)}
                className="bg-[#FFB347] text-[#133020] px-8 py-3 rounded-xl font-google font-black text-xs uppercase tracking-widest active:scale-95 transition-all shadow-lg"
              >
                Sync Configuration
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Mobile Sidebar Overlay */}
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-[#133020]/40 backdrop-blur-sm z-[90] lg:hidden animate-in fade-in" onClick={() => setIsSidebarOpen(false)}></div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { LifewoodLogo, SparkleIcon, TOOLS, MODELS } from './constants';
import { Message, SenderType, Conversation, FileData } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  // Persistence states
  const [conversations, setConversations] = useState<Conversation[]>(() => {
    const saved = localStorage.getItem('lifewood_v3_conversations');
    return saved ? JSON.parse(saved).map((c: any) => ({
      ...c,
      messages: c.messages.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
      createdAt: new Date(c.createdAt)
    })) : [];
  });

  const [systemInstruction, setSystemInstruction] = useState(() => 
    localStorage.getItem('lifewood_system_instruction') || 'You are Lifewood Intelligence, a proactive innovation partner focusing on AI data strategy and global logistics.'
  );

  const [theme, setTheme] = useState(() => localStorage.getItem('lifewood_theme') || 'classic');

  // UI states
  const [activeId, setActiveId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [attachments, setAttachments] = useState<FileData[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  const [showTools, setShowTools] = useState(false);
  const [selectedTool, setSelectedTool] = useState(TOOLS[0]); // Default is General Chat
  const [showModels, setShowModels] = useState(false);
  const [selectedModel, setSelectedModel] = useState(MODELS[0]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const currentConversation = conversations.find(c => c.id === activeId);

  // Persistence Effects
  useEffect(() => {
    localStorage.setItem('lifewood_v3_conversations', JSON.stringify(conversations));
  }, [conversations]);

  useEffect(() => {
    localStorage.setItem('lifewood_system_instruction', systemInstruction);
  }, [systemInstruction]);

  useEffect(() => {
    localStorage.setItem('lifewood_theme', theme);
  }, [theme]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [currentConversation?.messages, isLoading]);

  const startNewChat = () => {
    setActiveId(null);
    setInput('');
    setAttachments([]);
    setIsSidebarOpen(false);
    setSelectedTool(TOOLS[0]);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    Array.from(files).forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        setAttachments(prev => [...prev, {
          data: event.target?.result as string,
          mimeType: file.type,
          fileName: file.name
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleSend = async (overrideInput?: string) => {
    const finalInput = overrideInput || input;
    if ((!finalInput.trim() && attachments.length === 0) || isLoading) return;

    let targetConv = currentConversation;
    if (!targetConv) {
      const newId = Date.now().toString();
      targetConv = {
        id: newId,
        title: finalInput.slice(0, 30) || 'New Lifewood Session',
        messages: [],
        personaId: 'default',
        createdAt: new Date(),
      };
      setConversations(prev => [targetConv!, ...prev]);
      setActiveId(newId);
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      text: finalInput,
      sender: SenderType.USER,
      timestamp: new Date(),
      attachments: [...attachments],
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, userMsg] } : c
    ));

    setInput('');
    setAttachments([]);
    setIsLoading(true);

    const aiResponse = await getGeminiResponse(
      userMsg.text, 
      userMsg.attachments,
      selectedTool.id,
      selectedModel.id,
      systemInstruction
    );

    const aiMsg: Message = {
      id: (Date.now() + 1).toString(),
      text: aiResponse.text,
      generatedImageUrl: aiResponse.generatedImageUrl,
      sender: SenderType.AI,
      timestamp: new Date(),
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, aiMsg] } : c
    ));
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const deleteConversation = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setConversations(prev => prev.filter(c => c.id !== id));
    if (activeId === id) setActiveId(null);
  };

  const suggestedPrompts = [
    { 
      category: 'Strategic Vision', 
      label: 'ASEAN HUB', 
      text: "Conceptualize a logistics-first AI data hub in ASEAN.", 
      tool: 'image',
      icon: '🌐'
    },
    { 
      category: 'Technical Execution', 
      label: 'RLHF QUALITY', 
      text: "Compare data quality benchmarks for multi-lingual RLHF.", 
      tool: 'research',
      icon: '📊'
    },
    { 
      category: 'Brand Value', 
      label: 'ESG GOALS', 
      text: "How does Lifewood's 'Always On' model reduce ESG carbon footprint?", 
      tool: 'chat',
      icon: '🌱'
    }
  ];

  const getThemeClasses = () => {
    switch(theme) {
      case 'dark': return 'bg-[#133020] text-white';
      case 'high-contrast': return 'bg-black text-[#FFB347]';
      default: return 'bg-[#f5eedb] text-[#133020]';
    }
  };

  const getFooterBackground = () => {
    switch(theme) {
      case 'dark': return 'from-[#133020] via-[#133020] to-transparent';
      case 'high-contrast': return 'from-black via-black to-transparent';
      default: return 'from-[#f5eedb] via-[#f5eedb] to-transparent';
    }
  };

  const getNavbarClasses = () => {
    switch(theme) {
      case 'dark': return 'bg-[#133020]/80 border-white/5';
      case 'high-contrast': return 'bg-black/80 border-white/10';
      default: return 'bg-[#f5eedb]/80 border-[#133020]/5';
    }
  };

  return (
    <div className={`flex h-screen overflow-hidden transition-colors duration-500 ${getThemeClasses()}`}>

      {/* Sidebar - Persistent Storage Access */}
      <aside className={`fixed inset-y-0 left-0 z-[100] w-72 bg-[#133020] transition-transform duration-300 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 flex flex-col shadow-2xl`}>
        <div className="p-8 border-b border-white/5">
          <LifewoodLogo />
          <button 
            onClick={startNewChat}
            className="w-full mt-10 bg-[#046241] hover:bg-[#057a51] text-white py-4 rounded-xl flex items-center justify-center gap-2 font-google font-bold text-xs uppercase tracking-widest transition-all shadow-lg active:scale-95"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M12 4v16m8-8H4"/></svg>
            New Session
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-1 lifewood-scrollbar">
          <h3 className="text-white/30 text-[10px] font-google font-black uppercase tracking-[0.2em] px-4 py-4">Knowledge Base</h3>
          {conversations.map(conv => (
            <div 
              key={conv.id}
              onClick={() => { setActiveId(conv.id); setIsSidebarOpen(false); }}
              className={`group relative px-4 py-3.5 rounded-xl cursor-pointer transition-all flex items-center justify-between ${activeId === conv.id ? 'bg-[#046241] text-white shadow-xl' : 'hover:bg-white/5 text-white/60 hover:text-white'}`}
            >
              <div className="flex-1 min-w-0">
                <div className="text-[13px] font-semibold truncate leading-tight">{conv.title}</div>
                <div className="text-[9px] font-black uppercase tracking-tighter opacity-40 mt-1">{conv.createdAt.toLocaleDateString()}</div>
              </div>
              <button onClick={(e) => deleteConversation(e, conv.id)} className="opacity-0 group-hover:opacity-100 p-2 hover:bg-red-500/20 rounded-lg transition-all text-red-400">
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
              </button>
            </div>
          ))}
        </div>

        <div className="p-6 bg-black/20 border-t border-white/5 space-y-4">
          <button 
            onClick={() => setShowSettings(true)}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-white/5 text-white/40 hover:text-white transition-all text-[10px] font-google font-black uppercase tracking-widest"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37a1.724 1.724 0 002.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            Config
          </button>
        </div>
      </aside>

      {/* Main UI Canvas */}
      <main className={`flex-1 flex flex-col relative h-full transition-all duration-300 ${isSidebarOpen ? 'opacity-20 pointer-events-none lg:opacity-100 lg:pointer-events-auto' : 'opacity-100'}`}>

        {/* Architectural Navbar - Centered Convo Title */}
        <header className={`sticky top-0 left-0 right-0 h-16 flex items-center justify-between px-6 z-40 backdrop-blur-md border-b transition-all duration-500 ${getNavbarClasses()}`}>
          <div className="flex-1 flex items-center">
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 bg-[#133020] text-white rounded-lg shadow-xl lg:hidden">
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M4 6h16M4 12h16m-7 6h7"/></svg>
            </button>
          </div>

          <div className="flex-1 flex justify-center">
            {currentConversation && (
              <h1 className="text-[10px] font-google font-black uppercase tracking-[0.4em] opacity-40 truncate max-w-[200px] sm:max-w-md text-center">
                {currentConversation.title}
              </h1>
            )}
          </div>

          <div className="flex-1 flex justify-end">
            <div className="hidden sm:flex items-center gap-2">
               <span className="text-[8px] font-black uppercase tracking-widest opacity-20">Secure Instance</span>
               <div className="w-1.5 h-1.5 rounded-full bg-[#046241]"></div>
            </div>
          </div>
        </header>

        {/* Scrollable Conversation Container - START LOWER (35vh) and TIGHTENED (space-y-10) */}
        <div className="flex-1 overflow-y-auto flex flex-col items-center lifewood-scrollbar pb-80 px-6 pt-[35vh]">
          {/* Widened to max-w-5xl to push AI responses leftward within the lane */}
          <div className="w-full max-w-5xl space-y-10">

            {(!currentConversation || currentConversation.messages.length === 0) && (
              <div className="mt-16 space-y-12 animate-in fade-in duration-1000 max-w-2xl mx-auto">
