import React, { useState, useRef, useEffect } from 'react';
import { LifewoodLogo, SparkleIcon, TOOLS, MODELS } from './constants';
import { Message, SenderType, Conversation, FileData, Folder } from './types';
import { getGeminiResponse } from './services/geminiService';

const App: React.FC = () => {
  // Persistence states
  const [conversations, setConversations] = useState<Conversation[]>(() => {
    const saved = localStorage.getItem('lifewood_v3_conversations');
    return saved ? JSON.parse(saved).map((c: any) => ({
      ...c,
      messages: c.messages.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
      createdAt: new Date(c.createdAt)
    })) : [];
  });

  const [folders, setFolders] = useState<Folder[]>(() => {
    const saved = localStorage.getItem('lifewood_folders');
    return saved ? JSON.parse(saved).map((f: any) => ({
      ...f,
      createdAt: new Date(f.createdAt)
    })) : [];
  });

  const [systemInstruction, setSystemInstruction] = useState(() => 
    localStorage.getItem('lifewood_system_instruction') || 'You are Lifewood Intelligence, a proactive innovation partner focusing on AI data strategy and global logistics.'
  );

  const [theme, setTheme] = useState(() => localStorage.getItem('lifewood_theme') || 'classic');

  // UI states
  const [activeId, setActiveId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [attachments, setAttachments] = useState<FileData[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  const [showTools, setShowTools] = useState(false);
  const [selectedTool, setSelectedTool] = useState(TOOLS[0]); // STRICT DEFAULT: GENERAL CHAT
  const [showModels, setShowModels] = useState(false);
  const [selectedModel, setSelectedModel] = useState(MODELS[0]);

  // Menu states
  const [activeMenuId, setActiveMenuId] = useState<string | null>(null);
  const [editingConvId, setEditingConvId] = useState<string | null>(null);
  const [editingFolderId, setEditingFolderId] = useState<string | null>(null);
  const [tempRenameValue, setTempRenameValue] = useState('');

  // Confirmation Modal states
  const [confirmModal, setConfirmModal] = useState<{
    show: boolean;
    type: 'conversation' | 'folder';
    id: string;
    title: string;
  }>({ show: false, type: 'conversation', id: '', title: '' });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const toolsMenuRef = useRef<HTMLDivElement>(null);
  const currentConversation = conversations.find(c => c.id === activeId);

  // Persistence Effects
  useEffect(() => {
    localStorage.setItem('lifewood_v3_conversations', JSON.stringify(conversations));
  }, [conversations]);

  useEffect(() => {
    localStorage.setItem('lifewood_folders', JSON.stringify(folders));
  }, [folders]);

  useEffect(() => {
    localStorage.setItem('lifewood_system_instruction', systemInstruction);
  }, [systemInstruction]);

  useEffect(() => {
    localStorage.setItem('lifewood_theme', theme);
  }, [theme]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [currentConversation?.messages, isLoading]);

  // Close menus when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setActiveMenuId(null);
      }
      if (toolsMenuRef.current && !toolsMenuRef.current.contains(event.target as Node)) {
        setShowTools(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Folder & Conversation Actions
  const createNewFolder = () => {
    const newFolder: Folder = {
      id: Date.now().toString(),
      name: 'New Collection',
      createdAt: new Date(),
      isOpen: true
    };
    setFolders(prev => [newFolder, ...prev]);
    setEditingFolderId(newFolder.id);
    setTempRenameValue(newFolder.name);
  };

  const triggerDeleteConfirm = (e: React.MouseEvent, type: 'conversation' | 'folder', id: string, title: string) => {
    e.stopPropagation();
    setConfirmModal({ show: true, type, id, title });
    setActiveMenuId(null);
  };

  const handleConfirmedDelete = () => {
    if (confirmModal.type === 'conversation') {
      setConversations(prev => prev.filter(c => c.id !== confirmModal.id));
      if (activeId === confirmModal.id) setActiveId(null);
    } else {
      setFolders(prev => prev.filter(f => f.id !== confirmModal.id));
      setConversations(prev => prev.map(c => c.folderId === confirmModal.id ? { ...c, folderId: undefined } : c));
    }
    setConfirmModal({ ...confirmModal, show: false });
  };

  const toggleFolder = (folderId: string) => {
    setFolders(prev => prev.map(f => f.id === folderId ? { ...f, isOpen: !f.isOpen } : f));
  };

  const startNewChat = () => {
    setActiveId(null);
    setInput('');
    setAttachments([]);
    setIsSidebarOpen(false);
    setSelectedTool(TOOLS[0]); // Reset to General Chat
  };

  const moveConversation = (convId: string, folderId?: string) => {
    setConversations(prev => prev.map(c => c.id === convId ? { ...c, folderId } : c));
    setActiveMenuId(null);
  };

  const handleRenameConv = (id: string) => {
    if (tempRenameValue.trim()) {
      setConversations(prev => prev.map(c => c.id === id ? { ...c, title: tempRenameValue } : c));
    }
    setEditingConvId(null);
  };

  const handleRenameFolder = (id: string) => {
    if (tempRenameValue.trim()) {
      setFolders(prev => prev.map(f => f.id === id ? { ...f, name: tempRenameValue } : f));
    }
    setEditingFolderId(null);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    Array.from(files).forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        setAttachments(prev => [...prev, {
          data: event.target?.result as string,
          mimeType: file.type,
          fileName: file.name
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleSend = async (overrideInput?: string) => {
    const finalInput = overrideInput || input;
    if ((!finalInput.trim() && attachments.length === 0) || isLoading) return;

    let targetConv = currentConversation;
    if (!targetConv) {
      const newId = Date.now().toString();
      targetConv = {
        id: newId,
        title: finalInput.slice(0, 30) || 'New Lifewood Session',
        messages: [],
        personaId: 'default',
        createdAt: new Date(),
      };
      setConversations(prev => [targetConv!, ...prev]);
      setActiveId(newId);
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      text: finalInput,
      sender: SenderType.USER,
      timestamp: new Date(),
      attachments: [...attachments],
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, userMsg] } : c
    ));

    setInput('');
    setAttachments([]);
    setIsLoading(true);

    const aiResponse = await getGeminiResponse(
      userMsg.text, 
      userMsg.attachments,
      selectedTool.id,
      selectedModel.id,
      systemInstruction
    );

    const aiMsg: Message = {
      id: (Date.now() + 1).toString(),
      text: aiResponse.text,
      generatedImageUrl: aiResponse.generatedImageUrl,
      sender: SenderType.AI,
      timestamp: new Date(),
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, aiMsg] } : c
    ));
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const suggestedPrompts = [
    { category: 'Strategic Vision', label: 'ASEAN HUB', text: "Conceptualize a logistics-first AI data hub in ASEAN.", tool: 'chat', icon: '🌐' },
    { category: 'Technical Execution', label: 'RLHF QUALITY', text: "Compare data quality benchmarks for multi-lingual RLHF.", tool: 'research', icon: '📊' },
    { category: 'Brand Value', label: 'ESG GOALS', text: "How does Lifewood's 'Always On' model reduce ESG carbon footprint?", tool: 'chat', icon: '🌱' }
  ];

  const getThemeClasses = () => {
    switch(theme) {
      case 'dark': return 'bg-[#133020] text-white';
      case 'high-contrast': return 'bg-black text-[#FFB347]';
      default: return 'bg-[#f5eedb] text-[#133020]';
    }
  };

  const getFooterBackground = () => {
    switch(theme) {
      case 'dark': return 'from-[#133020] via-[#133020] to-transparent';
      case 'high-contrast': return 'from-black via-black to-transparent';
      default: return 'from-[#f5eedb] via-[#f5eedb] to-transparent';
    }
  };

  const getNavbarClasses = () => {
    switch(theme) {
      case 'dark': return 'bg-[#133020]/80 border-white/5';
      case 'high-contrast': return 'bg-black/80 border-white/10';
      default: return 'bg-[#f5eedb]/80 border-[#133020]/5';
    }
  };

  const renderConvItem = (conv: Conversation) => (
    <div 
      key={conv.id} 
      onClick={() => { setActiveId(conv.id); setIsSidebarOpen(false); }} 
      className={`group relative px-4 py-2.5 rounded-xl cursor-pointer transition-all flex items-center gap-3 ${activeId === conv.id ? 'bg-[#046241] text-white shadow-xl' : 'hover:bg-white/5 text-white/60 hover:text-white'}`}
    >
      <div className="flex-1 min-w-0">
        {editingConvId === conv.id ? (
          <input 
            autoFocus
            className="w-full bg-white/10 border-none outline-none text-white px-2 py-0.5 rounded text-[13px] font-semibold"
            value={tempRenameValue}
            onChange={(e) => setTempRenameValue(e.target.value)}
            onBlur={() => handleRenameConv(conv.id)}
            onKeyDown={(e) => e.key === 'Enter' && handleRenameConv(conv.id)}
            onClick={(e) => e.stopPropagation()}
          />
        ) : (
          <div className="text-[13px] font-semibold truncate leading-tight">{conv.title}</div>
        )}
        <div className="text-[9px] font-black uppercase tracking-tighter opacity-40 mt-0.5">{conv.createdAt.toLocaleDateString()}</div>
      </div>

      <div className="relative">
        <button 
          onClick={(e) => { e.stopPropagation(); setActiveMenuId(activeMenuId === conv.id ? null : conv.id); }}
          className="p-1.5 hover:bg-white/10 rounded-lg text-white/40 hover:text-white transition-all opacity-0 group-hover:opacity-100"
        >
          <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M12 7a2 2 0 100-4 2 2 0 000 4zM12 14a2 2 0 100-4 2 2 0 000 4zM12 21a2 2 0 100-4 2 2 0 000 4z"/></svg>
        </button>

        {activeMenuId === conv.id && (
          <div 
            ref={menuRef}
            className="absolute right-0 top-full mt-1 w-44 bg-[#133020] border border-white/10 rounded-xl shadow-2xl z-[150] overflow-hidden popover-enter"
            onClick={(e) => e.stopPropagation()}
          >
            <button 
              onClick={() => { setEditingConvId(conv.id); setTempRenameValue(conv.title); setActiveMenuId(null); }}
              className="w-full text-left px-4 py-3 text-[10px] font-google font-black uppercase tracking-widest text-white/60 hover:text-white hover:bg-white/5 transition-all flex items-center gap-2"
            >
              <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
              Rename
            </button>
            {conv.folderId && (
              <button 
                onClick={() => moveConversation(conv.id, undefined)}
                className="w-full text-left px-4 py-3 text-[10px] font-google font-black uppercase tracking-widest text-white/60 hover:text-white hover:bg-white/5 transition-all flex items-center gap-2"
              >
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M6 18L18 6M6 6l12 12"/></svg>
                Remove from Group
              </button>
            )}
            <button 
              onClick={(e) => triggerDeleteConfirm(e, 'conversation', conv.id, conv.title)}
              className="w-full text-left px-4 py-3 text-[10px] font-google font-black uppercase tracking-widest text-red-400 hover:text-red-300 hover:bg-red-500/10 transition-all flex items-center gap-2"
            >
              <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
              Delete
            </button>
          </div>
        )}
      </div>
    </div>
  );

  return (
    <div className={`flex h-screen overflow-hidden transition-colors duration-500 ${getThemeClasses()}`}>
      {/* Confirmation Modal */}
      {confirmModal.show && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-6 bg-black/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className="w-full max-w-sm bg-[#133020] rounded-[2rem] overflow-hidden shadow-2xl border border-white/10 text-white p-8 space-y-6">
            <h3 className="text-lg font-google font-black uppercase tracking-widest text-[#FFB347]">Confirm Delete</h3>
            <p className="text-xs text-white/60 leading-relaxed font-google">
              Are you sure you want to permanently delete <span className="text-white font-bold">"{confirmModal.title}"</span>? This action is irreversible.
            </p>
            <div className="flex gap-3 pt-2">
              <button 
                onClick={() => setConfirmModal({ ...confirmModal, show: false })}
                className="flex-1 py-3 rounded-xl bg-white/5 hover:bg-white/10 text-white/40 hover:text-white transition-all text-[10px] font-google font-black uppercase tracking-widest"
              >
                Cancel
              </button>
              <button 
                onClick={handleConfirmedDelete}
                className="flex-1 py-3 rounded-xl bg-red-500/80 hover:bg-red-500 text-white transition-all text-[10px] font-google font-black uppercase tracking-widest shadow-lg"
              >
                Delete
              </button>
            </div>
          </div>
        </div>
      )}

      <aside className={`fixed inset-y-0 left-0 z-[100] w-72 bg-[#133020] transition-transform duration-300 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 flex flex-col shadow-2xl`}>
        <div className="p-8 border-b border-white/5">
          <LifewoodLogo />
          <div className="grid grid-cols-2 gap-2 mt-10">
            <button onClick={() => startNewChat()} className="bg-[#046241] hover:bg-[#057a51] text-white py-3.5 rounded-xl flex items-center justify-center gap-2 font-google font-bold text-[10px] uppercase tracking-widest transition-all shadow-lg active:scale-95">
              <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M12 4v16m8-8H4"/></svg>
              Chat
            </button>
            <button onClick={createNewFolder} className="bg-white/5 hover:bg-white/10 text-white/80 py-3.5 rounded-xl flex items-center justify-center gap-2 font-google font-bold text-[10px] uppercase tracking-widest transition-all active:scale-95">
              <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M12 9v6m3-3H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
              Folder
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto px-4 py-4 space-y-6 lifewood-scrollbar">
          <div className="space-y-2">
            <h3 className="text-white/20 text-[9px] font-google font-black uppercase tracking-[0.2em] px-4 mb-2">Projects & Groups</h3>
            {folders.map(folder => (
              <div key={folder.id} className="space-y-1">
                <div className={`group flex items-center gap-3 px-4 py-2.5 rounded-xl cursor-pointer transition-all ${folder.isOpen ? 'bg-white/5 text-white' : 'text-white/40 hover:text-white/60'}`} onClick={() => toggleFolder(folder.id)} onDragOver={(e) => e.preventDefault()} onDrop={(e) => {
                    const convId = e.dataTransfer.getData('convId');
                    if (convId) moveConversation(convId, folder.id);
                  }}>
                  <svg className={`w-4 h-4 transition-transform duration-300 ${folder.isOpen ? 'rotate-90' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M9 5l7 7-7 7"/></svg>
                  <div className="flex-1 min-w-0">
                    {editingFolderId === folder.id ? (
                      <input autoFocus className="w-full bg-white/10 border-none outline-none text-white px-2 py-0.5 rounded text-[11px] font-bold uppercase" value={tempRenameValue} onChange={(e) => setTempRenameValue(e.target.value)} onBlur={() => handleRenameFolder(folder.id)} onKeyDown={(e) => e.key === 'Enter' && handleRenameFolder(folder.id)} onClick={(e) => e.stopPropagation()} />
                    ) : (
                      <div className="text-[11px] font-bold uppercase tracking-wider truncate">{folder.name}</div>
                    )}
                  </div>
                  <div className="flex items-center opacity-0 group-hover:opacity-100 transition-opacity">
                    <button onClick={(e) => { e.stopPropagation(); setEditingFolderId(folder.id); setTempRenameValue(folder.name); }} className="p-1 hover:bg-white/10 rounded">
                      <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
                    </button>
                    <button onClick={(e) => triggerDeleteConfirm(e, 'folder', folder.id, folder.name)} className="p-1 hover:bg-red-500/20 rounded text-red-400/60">
                      <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M6 18L18 6M6 6l12 12"/></svg>
                    </button>
                  </div>
                </div>
                {folder.isOpen && (
                  <div className="pl-4 space-y-1 animate-in slide-in-from-top-2 duration-300">
                    {conversations.filter(c => c.folderId === folder.id).map(conv => (
                      <div key={conv.id} draggable onDragStart={(e) => e.dataTransfer.setData('convId', conv.id)}>
                        {renderConvItem(conv)}
                      </div>
                    ))}
                    {conversations.filter(c => c.folderId === folder.id).length === 0 && (
                      <div className="text-[9px] text-white/10 italic px-6 py-2">Empty collection</div>
                    )}
                  </div>
                )}
              </div>
            ))}
          </div>
          <div className="space-y-1">
            <h3 className="text-white/20 text-[9px] font-google font-black uppercase tracking-[0.2em] px-4 mb-2">Uncategorized</h3>
            <div onDragOver={(e) => e.preventDefault()} onDrop={(e) => {
              const convId = e.dataTransfer.getData('convId');
              if (convId) moveConversation(convId, undefined);
            }}>
              {conversations.filter(c => !c.folderId).map(conv => (
                <div key={conv.id} draggable onDragStart={(e) => e.dataTransfer.setData('convId', conv.id)}>
                  {renderConvItem(conv)}
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="p-6 bg-black/20 border-t border-white/5 space-y-4">
          <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-white/5 text-white/40 hover:text-white transition-all text-[10px] font-google font-black uppercase tracking-widest">
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37a1.724 1.724 0 002.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            Config
          </button>
        </div>
      </aside>

      <main className={`flex-1 flex flex-col relative h-full transition-all duration-300 ${isSidebarOpen ? 'opacity-20 pointer-events-none lg:opacity-100 lg:pointer-events-auto' : 'opacity-100'}`}>
        <header className={`sticky top-0 left-0 right-0 h-16 flex items-center justify-between px-6 z-40 backdrop-blur-md border-b transition-all duration-500 ${getNavbarClasses()}`}>
          <div className="flex-1 flex items-center">
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 bg-[#133020] text-white rounded-lg shadow-xl lg:hidden">
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M4 6h16M4 12h16m-7 6h7"/></svg>
            </button>
          </div>
          <div className="flex-1 flex justify-center">
            {currentConversation && (
              <h1 className="text-[10px] font-google font-black uppercase tracking-[0.4em] opacity-40 truncate max-w-[200px] sm:max-w-md text-center">
                {currentConversation.title}
              </h1>
            )}
          </div>
          <div className="flex-1 flex justify-end">
            <div className="hidden sm:flex items-center gap-2">
               <span className="text-[8px] font-black uppercase tracking-widest opacity-20">Secure Instance</span>
               <div className="w-1.5 h-1.5 rounded-full bg-[#046241]"></div>
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto flex flex-col items-center lifewood-scrollbar pb-64 px-6 pt-[48vh]">
          <div className="w-full max-w-5xl space-y-6">
            {(!currentConversation || currentConversation.messages.length === 0) && (
              <div className="mt-8 space-y-12 animate-in fade-in duration-1000 max-w-2xl mx-auto">
                <div className="text-center space-y-6">
                  <h2 className={`text-6xl font-google font-black tracking-tighter ${theme === 'classic' ? 'text-[#046241]' : 'text-[#FFB347]'}`}>
                    Innovation. <br/> <span className={theme === 'classic' ? 'text-[#FFB347]' : 'text-white'}>Verified.</span>
                  </h2>
                  <p className="text-[11px] font-google font-black uppercase tracking-[0.6em] opacity-30">
                    Enterprise Intelligence Engine
                  </p>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {suggestedPrompts.map((s, i) => (
                    <button key={i} onClick={() => { setSelectedTool(TOOLS.find(t => t.id === s.tool) || TOOLS[0]); setInput(s.text); }} className={`group p-6 rounded-[2rem] border transition-all text-left flex flex-col justify-between ${theme === 'classic' ? 'bg-white border-[#133020]/5 hover:border-[#FFB347]' : 'bg-white/5 border-white/10 hover:border-[#FFB347]'}`}>
                      <div>
                        <div className="flex items-center justify-between mb-4">
                           <span className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${theme === 'classic' ? 'bg-[#133020]/5 text-[#133020]/60' : 'bg-white/10 text-white/60'}`}>{s.category}</span>
                           <span className="text-lg opacity-40 group-hover:opacity-100 transition-opacity">{s.icon}</span>
                        </div>
                        <h4 className="text-[10px] font-black uppercase tracking-tighter text-[#FFB347] mb-1">{s.label}</h4>
                        <p className={`text-[13px] font-bold leading-snug ${theme === 'classic' ? 'text-[#133020]' : 'text-white'}`}>{s.text}</p>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}
            {currentConversation?.messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.sender === SenderType.USER ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-4 duration-500`}>
                <div className={`flex gap-6 ${msg.sender === SenderType.USER ? 'flex-row-reverse max-w-[80%]' : 'max-w-[85%]'}`}>
                   {msg.sender === SenderType.AI && (
                     <div className="mt-1 flex-shrink-0">
                       <div className="w-10 h-10 rounded-full bg-[#133020] flex items-center justify-center shadow-lg border border-white/10">
                          <SparkleIcon className="w-5 h-5 fill-[#FFB347]" />
                       </div>
                     </div>
                   )}
                   <div className="flex-1">
                      <div className={`
                        ${msg.sender === SenderType.USER 
                          ? 'bg-[#FFB347] text-[#133020] px-6 py-4 rounded-3xl rounded-tr-none font-google font-bold text-[14px] shadow-lg border border-[#133020]/10' 
                          : `font-serif text-[19px] leading-relaxed tracking-wide opacity-90 py-1 ${theme === 'classic' ? 'text-[#133020]' : 'text-white/90'}`
                        }
                      `}>
                        {msg.text}
                        {msg.generatedImageUrl && (
                          <div className="mt-8 rounded-[2rem] overflow-hidden shadow-2xl border border-white/5 bg-black/10 p-2 max-w-xl">
                            <img src={msg.generatedImageUrl} className="w-full h-auto rounded-[1.8rem]" alt="AI Generated" />
                          </div>
                        )}
                      </div>
                      <div className={`mt-1 text-[9px] font-google font-black uppercase tracking-widest opacity-20 ${msg.sender === SenderType.USER ? 'text-right' : ''}`}>
                        {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </div>
                   </div>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex gap-6 w-full animate-pulse justify-start">
                <div className="w-10 h-10 rounded-full bg-black/10" />
                <div className="flex-1 space-y-4 pt-3">
                  <div className={`h-2.5 rounded-full w-3/4 ${theme === 'classic' ? 'bg-[#133020]/5' : 'bg-white/10'}`}></div>
                  <div className={`h-2.5 rounded-full w-1/2 ${theme === 'classic' ? 'bg-[#133020]/5' : 'bg-white/10'}`}></div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
        </div>

        <div className={`fixed bottom-0 left-0 right-0 pt-32 pb-8 px-8 flex justify-center bg-gradient-to-t ${getFooterBackground()} z-[50] pointer-events-none`}>
          <div className="w-full max-w-3xl pointer-events-auto">
            {attachments.length > 0 && (
              <div className="flex flex-wrap gap-2 mb-4 px-2 animate-in slide-in-from-bottom-2">
                {attachments.map((file, idx) => (
                  <div key={idx} className="relative group bg-white p-1 rounded-xl shadow-lg border border-[#133020]/5 w-20 h-20">
                    <img src={file.data} className="w-full h-full object-cover rounded-lg" alt="Attachment" />
                    <button onClick={() => setAttachments(prev => prev.filter((_, i) => i !== idx))} className="absolute -top-2 -right-2 bg-[#133020] text-white p-1 rounded-full shadow-md scale-75">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12"/></svg>
                    </button>
                  </div>
                ))}
              </div>
            )}
            <div className={`rounded-[1.8rem] overflow-visible border-none shadow-2xl relative ${theme === 'classic' ? 'bg-white' : 'bg-[#046241]/95 backdrop-blur-2xl border border-white/5'}`}>
              <div className="p-3 flex items-center gap-2 relative">
                <button onClick={() => fileInputRef.current?.click()} className={`p-4 rounded-xl transition-all active:scale-95 ${theme === 'classic' ? 'hover:bg-[#133020]/5 text-[#133020]/20' : 'hover:bg-white/5 text-white/20'}`}>
                  <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M12 4v16m8-8H4"/></svg>
                </button>
                <input type="file" ref={fileInputRef} className="hidden" multiple onChange={handleFileUpload} />

                <div className="relative">
                  {/* High-Fidelity Tool Selector Button */}
                  <button onClick={() => { setShowTools(!showTools); setShowModels(false); }} className={`flex items-center gap-3 px-6 py-3 rounded-2xl transition-all font-google font-black text-[10px] uppercase tracking-widest active:scale-95 shadow-md border border-[#133020]/10 bg-[#FFB347] text-[#133020]`}>
                    <span className="text-sm">{selectedTool.icon}</span>
                    <span className="hidden sm:inline">{selectedTool.name}</span>
                  </button>

                  {showTools && (
                    <div ref={toolsMenuRef} className="absolute bottom-full left-0 mb-4 w-64 bg-[#0d2116] border border-white/10 rounded-[1.5rem] shadow-2xl overflow-hidden popover-enter z-[200] p-1.5">
                      <div className="space-y-0.5">
                        {TOOLS.map(t => (
                          <button key={t.id} onClick={() => { setSelectedTool(t); setShowTools(false); }} className={`w-full text-left p-4 rounded-xl transition-all flex items-center gap-4 ${selectedTool.id === t.id ? 'bg-[#046241] text-white' : 'hover:bg-white/5 text-white/60'}`}>
                            <span className="text-lg opacity-80">{t.icon}</span>
                            <div className="text-[10px] font-google font-black uppercase tracking-widest">{t.name}</div>
                          </button>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                <div className="flex-1 min-w-0">
                  <textarea rows={1} value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={handleKeyPress} placeholder="Synthesize new request..." className={`w-full bg-transparent border-none resize-none py-3 px-4 text-[16px] font-google font-bold focus:ring-0 focus:outline-none ring-0 outline-none max-h-40 no-scrollbar ${theme === 'classic' ? 'text-[#133020]' : 'text-white'}`} />
                </div>

                <div className="flex items-center gap-3 pr-3">
                   <div className="relative hidden sm:block">
                     <button onClick={() => { setShowModels(!showModels); setShowTools(false); }} className={`px-3 py-2 rounded-lg text-[9px] font-google font-black uppercase tracking-widest transition-all ${theme === 'classic' ? 'text-[#133020]/20 hover:text-[#133020]/40' : 'text-white/20 hover:text-white/40'}`}>
                        {selectedModel.name}
                      </button>
                   </div>
                   <button disabled={isLoading || (!input.trim() && attachments.length === 0)} onClick={() => handleSend()} className={`p-4 rounded-2xl transition-all active:scale-90 ${(!input.trim() && attachments.length === 0) ? 'bg-black/5 text-black/10' : 'bg-black/5 text-[#133020] hover:bg-black/10 shadow-lg'}`}>
                      <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M13.5 4.5L21 12m0 0l-7.5 7.5M21 12H3"/></svg>
                   </button>
                </div>
              </div>
            </div>
            <p className="text-[9px] font-google opacity-20 text-center mt-6 font-black uppercase tracking-[0.4em]">
              Intelligence Authenticated - Lifewood Core
            </p>
          </div>
        </div>
      </main>

      {showSettings && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className="w-full max-w-xl bg-[#133020] rounded-[2.5rem] overflow-hidden shadow-2xl border border-white/10 text-white animate-in slide-in-from-bottom-4">
            <div className="p-8 border-b border-white/5 flex items-center justify-between">
              <div><h3 className="text-xl font-google font-black uppercase tracking-tighter">Core Directives</h3></div>
              <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M6 18L18 6M6 6l12 12"/></svg>
              </button>
            </div>
            <div className="p-8 space-y-8">
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] opacity-40">System Directives</label>
                <textarea value={systemInstruction} onChange={(e) => setSystemInstruction(e.target.value)} placeholder="Define how Lifewood Intelligence should behave..." className="w-full h-32 bg-black/40 border border-white/10 rounded-2xl p-4 text-xs font-medium leading-relaxed resize-none focus:border-[#FFB347] transition-all focus:ring-0" />
              </div>
            </div>
            <div className="p-8 bg-black/20 flex justify-end">
              <button onClick={() => setShowSettings(false)} className="bg-[#FFB347] text-[#133020] px-8 py-3 rounded-xl font-google font-black text-xs uppercase tracking-widest active:scale-95 transition-all shadow-lg">Sync Configuration</button>
            </div>
          </div>
        </div>
      )}

      {isSidebarOpen && (
        <div className="fixed inset-0 bg-[#133020]/40 backdrop-blur-sm z-[90] lg:hidden animate-in fade-in" onClick={() => setIsSidebarOpen(false)}></div>
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { LifewoodLogo } from '../constants';
import { Conversation, Folder } from '../types';

interface SidebarProps {
  conversations: Conversation[];
  folders: Folder[];
  activeId: string | null;
  setActiveId: (id: string | null) => void;
  isSidebarOpen: boolean;
  setIsSidebarOpen: (open: boolean) => void;
  startNewChat: () => void;
  createNewFolder: () => void;
  toggleFolder: (id: string) => void;
  moveConversation: (convId: string, folderId?: string) => void;
  editingConvId: string | null;
  setEditingConvId: (id: string | null) => void;
  editingFolderId: string | null;
  setEditingFolderId: (id: string | null) => void;
  tempRenameValue: string;
  setTempRenameValue: (val: string) => void;
  handleRenameConv: (id: string) => void;
  handleRenameFolder: (id: string) => void;
  activeMenuId: string | null;
  setActiveMenuId: (id: string | null) => void;
  triggerDeleteConfirm: (e: React.MouseEvent, type: 'conversation' | 'folder', id: string, title: string) => void;
  setShowSettings: (show: boolean) => void;
  menuRef: React.RefObject<HTMLDivElement | null>;
}

export const Sidebar: React.FC<SidebarProps> = ({
  conversations, folders, activeId, setActiveId, isSidebarOpen, setIsSidebarOpen,
  startNewChat, createNewFolder, toggleFolder, moveConversation,
  editingConvId, setEditingConvId, editingFolderId, setEditingFolderId,
  tempRenameValue, setTempRenameValue, handleRenameConv, handleRenameFolder,
  activeMenuId, setActiveMenuId, triggerDeleteConfirm, setShowSettings, menuRef
}) => {
  const renderConvItem = (conv: Conversation) => (
    <div 
      key={conv.id} 
      onClick={() => { setActiveId(conv.id); setIsSidebarOpen(false); }} 
      className={`group relative px-4 py-2.5 rounded-xl cursor-pointer transition-all flex items-center gap-3 ${activeId === conv.id ? 'bg-[#046241] text-white shadow-xl' : 'hover:bg-white/5 text-white/60 hover:text-white'}`}
    >
      <div className="flex-1 min-w-0">
        {editingConvId === conv.id ? (
          <input 
            autoFocus
            className="w-full bg-white/10 border-none outline-none text-white px-2 py-0.5 rounded text-[13px] font-semibold"
            value={tempRenameValue}
            onChange={(e) => setTempRenameValue(e.target.value)}
            onBlur={() => handleRenameConv(conv.id)}
            onKeyDown={(e) => e.key === 'Enter' && handleRenameConv(conv.id)}
            onClick={(e) => e.stopPropagation()}
          />
        ) : (
          <div className="text-[13px] font-semibold truncate leading-tight">{conv.title}</div>
        )}
        <div className="text-[9px] font-black uppercase tracking-tighter opacity-40 mt-0.5">{conv.createdAt.toLocaleDateString()}</div>
      </div>

      <div className="relative">
        <button 
          onClick={(e) => { e.stopPropagation(); setActiveMenuId(activeMenuId === conv.id ? null : conv.id); }}
          className="p-1.5 hover:bg-white/10 rounded-lg text-white/40 hover:text-white transition-all opacity-0 group-hover:opacity-100"
        >
          <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M12 7a2 2 0 100-4 2 2 0 000 4zM12 14a2 2 0 100-4 2 2 0 000 4zM12 21a2 2 0 100-4 2 2 0 000 4z"/></svg>
        </button>

        {activeMenuId === conv.id && (
          <div 
            ref={menuRef}
            className="absolute right-0 top-full mt-1 w-44 bg-[#133020] border border-white/10 rounded-xl shadow-2xl z-[150] overflow-hidden popover-enter"
            onClick={(e) => e.stopPropagation()}
          >
            <button 
              onClick={() => { setEditingConvId(conv.id); setTempRenameValue(conv.title); setActiveMenuId(null); }}
              className="w-full text-left px-4 py-3 text-[10px] font-google font-black uppercase tracking-widest text-white/60 hover:text-white hover:bg-white/5 transition-all flex items-center gap-2"
            >
              <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
              Rename
            </button>
            {conv.folderId && (
              <button 
                onClick={() => moveConversation(conv.id, undefined)}
                className="w-full text-left px-4 py-3 text-[10px] font-google font-black uppercase tracking-widest text-white/60 hover:text-white hover:bg-white/5 transition-all flex items-center gap-2"
              >
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M6 18L18 6M6 6l12 12"/></svg>
                Remove from Group
              </button>
            )}
            <button 
              onClick={(e) => triggerDeleteConfirm(e, 'conversation', conv.id, conv.title)}
              className="w-full text-left px-4 py-3 text-[10px] font-google font-black uppercase tracking-widest text-red-400 hover:text-red-300 hover:bg-red-500/10 transition-all flex items-center gap-2"
            >
              <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
              Delete
            </button>
          </div>
        )}
      </div>
    </div>
  );

  return (
    <aside className={`fixed inset-y-0 left-0 z-[100] w-72 bg-[#133020] transition-transform duration-300 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:relative lg:translate-x-0 flex flex-col shadow-2xl`}>
      <div className="p-8 border-b border-white/5">
        <LifewoodLogo />
        <div className="grid grid-cols-2 gap-2 mt-10">
          <button onClick={startNewChat} className="bg-[#046241] hover:bg-[#057a51] text-white py-3.5 rounded-xl flex items-center justify-center gap-2 font-google font-bold text-[10px] uppercase tracking-widest transition-all shadow-lg active:scale-95">
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M12 4v16m8-8H4"/></svg>
            Chat
          </button>
          <button onClick={createNewFolder} className="bg-white/5 hover:bg-white/10 text-white/80 py-3.5 rounded-xl flex items-center justify-center gap-2 font-google font-bold text-[10px] uppercase tracking-widest transition-all active:scale-95">
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M12 9v6m3-3H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
            Folder
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-4 py-4 space-y-6 lifewood-scrollbar">
        <div className="space-y-2">
          <h3 className="text-white/20 text-[9px] font-google font-black uppercase tracking-[0.2em] px-4 mb-2">Projects & Groups</h3>
          {folders.map(folder => (
            <div key={folder.id} className="space-y-1">
              <div 
                className={`group flex items-center gap-3 px-4 py-2.5 rounded-xl cursor-pointer transition-all ${folder.isOpen ? 'bg-white/5 text-white' : 'text-white/40 hover:text-white/60'}`}
                onClick={() => toggleFolder(folder.id)}
                onDragOver={(e) => e.preventDefault()}
                onDrop={(e) => {
                  const convId = e.dataTransfer.getData('convId');
                  if (convId) moveConversation(convId, folder.id);
                }}
              >
                <svg className={`w-4 h-4 transition-transform duration-300 ${folder.isOpen ? 'rotate-90' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M9 5l7 7-7 7"/></svg>
                <div className="flex-1 min-w-0">
                  {editingFolderId === folder.id ? (
                    <input 
                      autoFocus
                      className="w-full bg-white/10 border-none outline-none text-white px-2 py-0.5 rounded text-[11px] font-bold uppercase"
                      value={tempRenameValue}
                      onChange={(e) => setTempRenameValue(e.target.value)}
                      onBlur={() => handleRenameFolder(folder.id)}
                      onKeyDown={(e) => e.key === 'Enter' && handleRenameFolder(folder.id)}
                      onClick={(e) => e.stopPropagation()}
                    />
                  ) : (
                    <div className="text-[11px] font-bold uppercase tracking-wider truncate">{folder.name}</div>
                  )}
                </div>
                <div className="flex items-center opacity-0 group-hover:opacity-100 transition-opacity">
                  <button onClick={(e) => { e.stopPropagation(); setEditingFolderId(folder.id); setTempRenameValue(folder.name); }} className="p-1 hover:bg-white/10 rounded">
                    <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"/></svg>
                  </button>
                  <button onClick={(e) => triggerDeleteConfirm(e, 'folder', folder.id, folder.name)} className="p-1 hover:bg-red-500/20 rounded text-red-400/60">
                    <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path d="M6 18L18 6M6 6l12 12"/></svg>
                  </button>
                </div>
              </div>
              {folder.isOpen && (
                <div className="pl-4 space-y-1 animate-in slide-in-from-top-2 duration-300">
                  {conversations.filter(c => c.folderId === folder.id).map(conv => (
                    <div key={conv.id} draggable onDragStart={(e) => e.dataTransfer.setData('convId', conv.id)}>
                      {renderConvItem(conv)}
                    </div>
                  ))}
                  {conversations.filter(c => c.folderId === folder.id).length === 0 && (
                    <div className="text-[9px] text-white/10 italic px-6 py-2">Empty collection</div>
                  )}
                </div>
              )}
            </div>
          ))}
        </div>
        <div className="space-y-1">
          <h3 className="text-white/20 text-[9px] font-google font-black uppercase tracking-[0.2em] px-4 mb-2">Uncategorized</h3>
          <div onDragOver={(e) => e.preventDefault()} onDrop={(e) => {
            const convId = e.dataTransfer.getData('convId');
            if (convId) moveConversation(convId, undefined);
          }}>
            {conversations.filter(c => !c.folderId).map(conv => (
              <div key={conv.id} draggable onDragStart={(e) => e.dataTransfer.setData('convId', conv.id)}>
                {renderConvItem(conv)}
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="p-6 bg-black/20 border-t border-white/5 space-y-4">
        <button onClick={() => setShowSettings(true)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-white/5 text-white/40 hover:text-white transition-all text-[10px] font-google font-black uppercase tracking-widest">
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37a1.724 1.724 0 002.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
          Config
        </button>
      </div>
    </aside>
  );
};

