import React, { useState, useRef, useEffect } from 'react';
import { TOOLS, MODELS, LifewoodLogo } from './constants';
import { Message, SenderType, Conversation, FileData, Folder } from './types';
import { getGeminiResponse } from './services/geminiService';

// Components
import { Sidebar } from './components/Sidebar';
import { MessageList } from './components/MessageList';
import { ChatInput } from './components/ChatInput';
import { ConfirmationModal, SettingsModal } from './components/Modals';

const App: React.FC = () => {
  // Persistence states
  const [conversations, setConversations] = useState<Conversation[]>(() => {
    const saved = localStorage.getItem('lifewood_v3_conversations');
    return saved ? JSON.parse(saved).map((c: any) => ({
      ...c,
      messages: c.messages.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
      createdAt: new Date(c.createdAt)
    })) : [];
  });

  const [folders, setFolders] = useState<Folder[]>(() => {
    const saved = localStorage.getItem('lifewood_folders');
    return saved ? JSON.parse(saved).map((f: any) => ({
      ...f,
      createdAt: new Date(f.createdAt)
    })) : [];
  });

  const [systemInstruction, setSystemInstruction] = useState(() => 
    localStorage.getItem('lifewood_system_instruction') || 'You are Lifewood Intelligence, a proactive innovation partner focusing on AI data strategy and global logistics.'
  );

  const [theme, setTheme] = useState(() => localStorage.getItem('lifewood_theme') || 'classic');

  // UI states
  const [activeId, setActiveId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [attachments, setAttachments] = useState<FileData[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  const [showTools, setShowTools] = useState(false);
  const [selectedTool, setSelectedTool] = useState(TOOLS[0]); 
  const [showModels, setShowModels] = useState(false);
  const [selectedModel, setSelectedModel] = useState(MODELS[0]);

  // Menu states
  const [activeMenuId, setActiveMenuId] = useState<string | null>(null);
  const [editingConvId, setEditingConvId] = useState<string | null>(null);
  const [editingFolderId, setEditingFolderId] = useState<string | null>(null);
  const [tempRenameValue, setTempRenameValue] = useState('');

  // Confirmation Modal states
  const [confirmModal, setConfirmModal] = useState<{
    show: boolean;
    type: 'conversation' | 'folder';
    id: string;
    title: string;
  }>({ show: false, type: 'conversation', id: '', title: '' });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const toolsMenuRef = useRef<HTMLDivElement>(null);
  const currentConversation = conversations.find(c => c.id === activeId);

  // Persistence Effects
  useEffect(() => {
    localStorage.setItem('lifewood_v3_conversations', JSON.stringify(conversations));
  }, [conversations]);

  useEffect(() => {
    localStorage.setItem('lifewood_folders', JSON.stringify(folders));
  }, [folders]);

  useEffect(() => {
    localStorage.setItem('lifewood_system_instruction', systemInstruction);
  }, [systemInstruction]);

  useEffect(() => {
    localStorage.setItem('lifewood_theme', theme);
  }, [theme]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [currentConversation?.messages, isLoading]);

  // Folder & Conversation Actions
  const createNewFolder = () => {
    const newFolder: Folder = {
      id: Date.now().toString(),
      name: 'New Collection',
      createdAt: new Date(),
      isOpen: true
    };
    setFolders(prev => [newFolder, ...prev]);
    setEditingFolderId(newFolder.id);
    setTempRenameValue(newFolder.name);
  };

  const triggerDeleteConfirm = (e: React.MouseEvent, type: 'conversation' | 'folder', id: string, title: string) => {
    e.stopPropagation();
    setConfirmModal({ show: true, type, id, title });
    setActiveMenuId(null);
  };

  const handleConfirmedDelete = () => {
    if (confirmModal.type === 'conversation') {
      setConversations(prev => prev.filter(c => c.id !== confirmModal.id));
      if (activeId === confirmModal.id) setActiveId(null);
    } else {
      setFolders(prev => prev.filter(f => f.id !== confirmModal.id));
      setConversations(prev => prev.map(c => c.folderId === confirmModal.id ? { ...c, folderId: undefined } : c));
    }
    setConfirmModal({ ...confirmModal, show: false });
  };

  const toggleFolder = (folderId: string) => {
    setFolders(prev => prev.map(f => f.id === folderId ? { ...f, isOpen: !f.isOpen } : f));
  };

  const startNewChat = () => {
    setActiveId(null);
    setInput('');
    setAttachments([]);
    setIsSidebarOpen(false);
    setSelectedTool(TOOLS[0]);
  };

  const moveConversation = (convId: string, folderId?: string) => {
    setConversations(prev => prev.map(c => c.id === convId ? { ...c, folderId } : c));
    setActiveMenuId(null);
  };

  const handleRenameConv = (id: string) => {
    if (tempRenameValue.trim()) {
      setConversations(prev => prev.map(c => c.id === id ? { ...c, title: tempRenameValue } : c));
    }
    setEditingConvId(null);
  };

  const handleRenameFolder = (id: string) => {
    if (tempRenameValue.trim()) {
      setFolders(prev => prev.map(f => f.id === id ? { ...f, name: tempRenameValue } : f));
    }
    setEditingFolderId(null);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    Array.from(files).forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        setAttachments(prev => [...prev, {
          data: event.target?.result as string,
          mimeType: file.type,
          fileName: file.name
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleSend = async () => {
    if ((!input.trim() && attachments.length === 0) || isLoading) return;

    let targetConv = currentConversation;
    if (!targetConv) {
      const newId = Date.now().toString();
      targetConv = {
        id: newId,
        title: input.slice(0, 30) || 'New Lifewood Session',
        messages: [],
        personaId: 'default',
        createdAt: new Date(),
      };
      setConversations(prev => [targetConv!, ...prev]);
      setActiveId(newId);
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      text: input,
      sender: SenderType.USER,
      timestamp: new Date(),
      attachments: [...attachments],
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, userMsg] } : c
    ));

    setInput('');
    setAttachments([]);
    setIsLoading(true);

    const aiResponse = await getGeminiResponse(
      userMsg.text, 
      userMsg.attachments,
      selectedTool.id,
      selectedModel.id,
      systemInstruction
    );

    const aiMsg: Message = {
      id: (Date.now() + 1).toString(),
      text: aiResponse.text,
      generatedImageUrl: aiResponse.generatedImageUrl,
      sender: SenderType.AI,
      timestamp: new Date(),
    };

    setConversations(prev => prev.map(c => 
      c.id === targetConv!.id ? { ...c, messages: [...c.messages, aiMsg] } : c
    ));
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const getThemeClasses = () => {
    switch(theme) {
      case 'dark': return 'bg-[#133020] text-white';
      case 'high-contrast': return 'bg-black text-[#FFB347]';
      default: return 'bg-[#f5eedb] text-[#133020]';
    }
  };

  const getFooterBackground = () => {
    switch(theme) {
      case 'dark': return 'from-[#133020] via-[#133020] to-transparent';
      case 'high-contrast': return 'from-black via-black to-transparent';
      default: return 'from-[#f5eedb] via-[#f5eedb] to-transparent';
    }
  };

  const getNavbarClasses = () => {
    switch(theme) {
      case 'dark': return 'bg-[#133020]/80 border-white/5';
      case 'high-contrast': return 'bg-black/80 border-white/10';
      default: return 'bg-transparent border-transparent';
    }
  };

  return (
    <div className={`flex h-screen overflow-hidden transition-colors duration-500 ${getThemeClasses()}`}>

      <ConfirmationModal 
        confirmModal={confirmModal} 
        setConfirmModal={setConfirmModal} 
        handleConfirmedDelete={handleConfirmedDelete} 
      />

      <Sidebar 
        conversations={conversations}
        folders={folders}
        activeId={activeId}
        setActiveId={setActiveId}
        isSidebarOpen={isSidebarOpen}
        setIsSidebarOpen={setIsSidebarOpen}
        startNewChat={startNewChat}
        createNewFolder={createNewFolder}
        toggleFolder={toggleFolder}
        moveConversation={moveConversation}
        editingConvId={editingConvId}
        setEditingConvId={setEditingConvId}
        editingFolderId={editingFolderId}
        setEditingFolderId={setEditingFolderId}
        tempRenameValue={tempRenameValue}
        setTempRenameValue={setTempRenameValue}
        handleRenameConv={handleRenameConv}
        handleRenameFolder={handleRenameFolder}
        activeMenuId={activeMenuId}
        setActiveMenuId={setActiveMenuId}
        triggerDeleteConfirm={triggerDeleteConfirm}
        setShowSettings={setShowSettings}
        menuRef={menuRef}
      />

      <main className={`flex-1 flex flex-col relative h-full transition-all duration-300 ${isSidebarOpen ? 'opacity-20 pointer-events-none lg:opacity-100 lg:pointer-events-auto' : 'opacity-100'}`}>
        <header className={`sticky top-0 left-0 right-0 h-20 flex items-center justify-between px-8 z-40 transition-all duration-500 ${getNavbarClasses()}`}>
          <div className="flex-1 flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(true)} className="w-10 h-10 bg-[#133020] text-white rounded-lg shadow-xl flex items-center justify-center lg:hidden active:scale-95 transition-transform">
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M4 6h16M4 12h16m-7 6h7"/></svg>
            </button>
            <div className="hidden lg:flex w-10 h-10 bg-[#133020] text-white rounded-lg shadow-xl items-center justify-center">
               <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="3"><path d="M4 6h16M4 12h16m-7 6h7"/></svg>
            </div>
            <LifewoodLogo className="h-6" textClass={theme === 'classic' ? 'text-[#133020]' : 'text-white'} />
          </div>
          <div className="flex-1 flex justify-center">
            {currentConversation && (
              <h1 className="text-[10px] font-google font-black uppercase tracking-[0.4em] opacity-40 truncate max-w-[200px] sm:max-w-md text-center">
                {currentConversation.title}
              </h1>
            )}
          </div>
          <div className="flex-1 flex justify-end">
            <div className="flex items-center gap-2">
               <span className="text-[8px] font-black uppercase tracking-widest opacity-20">SECURE INSTANCE</span>
               <div className="w-1.5 h-1.5 rounded-full bg-[#046241]"></div>
            </div>
          </div>
        </header>

        <MessageList 
          currentConversation={currentConversation}
          isLoading={isLoading}
          theme={theme}
          setSelectedTool={setSelectedTool}
          setInput={setInput}
          messagesEndRef={messagesEndRef}
        />

        <ChatInput 
          input={input}
          setInput={setInput}
          isLoading={isLoading}
          handleSend={handleSend}
          handleKeyPress={handleKeyPress}
          selectedTool={selectedTool}
          setSelectedTool={setSelectedTool}
          showTools={showTools}
          setShowTools={setShowTools}
          selectedModel={selectedModel}
          setSelectedModel={setSelectedModel}
          showModels={showModels}
          setShowModels={setShowModels}
          attachments={attachments}
          setAttachments={setAttachments}
          handleFileUpload={handleFileUpload}
          fileInputRef={fileInputRef}
          toolsMenuRef={toolsMenuRef}
          theme={theme}
          getFooterBackground={getFooterBackground}
        />
      </main>

      <SettingsModal 
        showSettings={showSettings}
        setShowSettings={setShowSettings}
        systemInstruction={systemInstruction}
        setSystemInstruction={setSystemInstruction}
        theme={theme}
        setTheme={setTheme}
      />

      {isSidebarOpen && (
        <div className="fixed inset-0 bg-[#133020]/40 backdrop-blur-sm z-[90] lg:hidden animate-in fade-in" onClick={() => setIsSidebarOpen(false)}></div>
      )}
    </div>
  );
};

export default App;

import React from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { SparkleIcon, TOOLS } from '../constants';
import { Message, SenderType, Conversation, FileData } from '../types';

interface MessageListProps {
  currentConversation: Conversation | undefined;
  isLoading: boolean;
  theme: string;
  setSelectedTool: (tool: any) => void;
  setInput: (val: string) => void;
  messagesEndRef: React.RefObject<HTMLDivElement | null>;
}

export const MessageList: React.FC<MessageListProps> = ({
  currentConversation, isLoading, theme, setSelectedTool, setInput, messagesEndRef
}) => {
  const suggestedPrompts = [
    { category: 'Strategic Vision', label: 'ASEAN HUB', text: "Conceptualize a logistics-first AI data hub in ASEAN.", tool: 'chat', icon: '🌐' },
    { category: 'Technical Execution', label: 'RLHF QUALITY', text: "Compare data quality benchmarks for multi-lingual RLHF.", tool: 'research', icon: '📊' },
    { category: 'Brand Value', label: 'ESG GOALS', text: "How does Lifewood's 'Always On' model reduce ESG carbon footprint?", tool: 'chat', icon: '🌱' }
  ];

  const isEmpty = !currentConversation || currentConversation.messages.length === 0;

  return (
    <div className={`flex-1 overflow-y-auto flex flex-col items-center lifewood-scrollbar pb-64 px-6 ${isEmpty ? 'pt-[10vh]' : 'pt-8'}`}>
      <div className="w-full max-w-5xl space-y-6">
        {isEmpty && (
          <div className="space-y-12 animate-in fade-in duration-1000 max-w-2xl mx-auto py-10">
            <div className="text-center space-y-6">
              <h2 className={`text-6xl font-google font-black tracking-tighter leading-tight ${theme === 'classic' ? 'text-[#046241]' : 'text-[#FFB347]'}`}>
                Innovation. <br/> <span className={theme === 'classic' ? 'text-[#FFB347]' : 'text-white'}>Verified.</span>
              </h2>
              <p className="text-[11px] font-google font-black uppercase tracking-[0.6em] opacity-30">
                Enterprise Intelligence Engine
              </p>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              {suggestedPrompts.map((s, i) => (
                <button key={i} onClick={() => { setSelectedTool(TOOLS.find(t => t.id === s.tool) || TOOLS[0]); setInput(s.text); }} className={`group p-6 rounded-[2rem] border transition-all text-left flex flex-col justify-between ${theme === 'classic' ? 'bg-white border-[#133020]/5 hover:border-[#FFB347]' : 'bg-white/5 border-white/10 hover:border-[#FFB347]'}`}>
                  <div>
                    <div className="flex items-center justify-between mb-4">
                       <span className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${theme === 'classic' ? 'bg-[#133020]/5 text-[#133020]/60' : 'bg-white/10 text-white/60'}`}>{s.category}</span>
                       <span className="text-lg opacity-40 group-hover:opacity-100 transition-opacity">{s.icon}</span>
                    </div>
                    <h4 className="text-[10px] font-black uppercase tracking-tighter text-[#FFB347] mb-1">{s.label}</h4>
                    <p className={`text-[13px] font-bold leading-snug ${theme === 'classic' ? 'text-[#133020]' : 'text-white'}`}>{s.text}</p>
                  </div>
                </button>
              ))}
            </div>
          </div>
        )}
        {currentConversation?.messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.sender === SenderType.USER ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-4 duration-500`}>
            <div className={`flex gap-6 ${msg.sender === SenderType.USER ? 'flex-row-reverse max-w-[80%]' : 'max-w-[85%]'}`}>
               {msg.sender === SenderType.AI && (
                 <div className="mt-1 flex-shrink-0">
                   <div className="w-10 h-10 rounded-full bg-[#133020] flex items-center justify-center shadow-lg border border-white/10">
                      <SparkleIcon className="w-5 h-5 fill-[#FFB347]" />
                   </div>
                 </div>
               )}
               <div className="flex-1">
                  <div className={`
                    ${msg.sender === SenderType.USER 
                      ? 'bg-[#FFB347] text-[#133020] px-6 py-4 rounded-3xl rounded-tr-none font-google font-bold text-[14px] shadow-lg border border-[#133020]/10 whitespace-pre-wrap' 
                      : `font-serif text-[19px] leading-relaxed tracking-wide opacity-90 py-1 markdown-content ${theme === 'classic' ? 'text-[#133020]' : 'text-white/90'}`
                    }
                  `}>
                    {msg.sender === SenderType.AI ? (
                      <ReactMarkdown remarkPlugins={[remarkGfm]}>
                        {msg.text}
                      </ReactMarkdown>
                    ) : (
                      msg.text
                    )}

                    {msg.generatedImageUrl && (
                      <div className="mt-8 rounded-[2rem] overflow-hidden shadow-2xl border border-white/5 bg-black/10 p-2 max-w-xl">
                        <img src={msg.generatedImageUrl} className="w-full h-auto rounded-[1.8rem]" alt="AI Generated" />
                      </div>
                    )}
                  </div>
                  <div className={`mt-1 text-[9px] font-google font-black uppercase tracking-widest opacity-20 ${msg.sender === SenderType.USER ? 'text-right' : ''}`}>
                    {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </div>
               </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex gap-6 w-full animate-pulse justify-start">
            <div className="w-10 h-10 rounded-full bg-black/10" />
            <div className="flex-1 space-y-4 pt-3">
              <div className={`h-2.5 rounded-full w-3/4 ${theme === 'classic' ? 'bg-[#133020]/5' : 'bg-white/10'}`}></div>
              <div className={`h-2.5 rounded-full w-1/2 ${theme === 'classic' ? 'bg-[#133020]/5' : 'bg-white/10'}`}></div>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>
    </div>
  );
};
